-- Nội dung khởi tạo của Hành trình Đông A (sinh bằng backend/scripts/saga-seed/build.cjs, đã kiểm tra bằng các hàm chuẩn hóa của máy chủ).
-- 13 chặng của ba cuộc kháng chiến (3 + 6 + 4), 79 câu luyện tập, 13 thẻ nhân vật, 14 mục tư liệu, 5 huy hiệu.
-- Dữ kiện lịch sử đối chiếu với Wikipedia tiếng Việt (ba bài "Chiến tranh Nguyên Mông – Đại Việt lần 1/2/3", "Trận Bạch Đằng (1288)", các bài nhân vật) và Bảo tàng Lịch sử quốc gia.
-- Lời thoại, nhân vật phụ và chỉ số trận đánh là phần sáng tạo của trò chơi. Không chứa dữ liệu tài khoản. Chạy lại không tạo trùng (ON CONFLICT DO NOTHING).

INSERT INTO public.hk_saga_maps (campaign_no, title, short_title, years, enemy, places, summary, image_key, image_w, image_h, credit, credit_url) VALUES
    (1, $hq$Kháng chiến lần thứ nhất chống quân Mông Cổ$hq$, $hq$Lần I$hq$, $hq$1258$hq$, $hq$Quân Mông Cổ$hq$, $hq$Đông Bộ Đầu$hq$, $hq$Quân Mông Cổ từ Vân Nam tràn xuống. Quân Trần lui quân giữ sức, làm “vườn không nhà trống” rồi đánh úp ở Đông Bộ Đầu, giải phóng Thăng Long.$hq$, $hq$ban-do-khang-chien-1$hq$, 1500, 1052, $hq$Bản đồ: Lưu Ly, Wikimedia Commons (phạm vi công cộng), lấy từ bài Wikipedia tiếng Việt về cuộc kháng chiến.$hq$, $hq$https://vi.wikipedia.org/wiki/T%E1%BA%ADp_tin:Chongquannguyenlan1.svg$hq$),
    (2, $hq$Kháng chiến lần thứ hai chống quân Nguyên$hq$, $hq$Lần II$hq$, $hq$1285$hq$, $hq$Quân Nguyên$hq$, $hq$Chương Dương · Hàm Tử$hq$, $hq$Chuẩn bị từ Bình Than, Diên Hồng; lui quân trước thế giặc mạnh rồi tổng phản công ở Hàm Tử, Chương Dương, Tây Kết.$hq$, $hq$ban-do-khang-chien-2$hq$, 1000, 1458, $hq$Bản đồ: Lưu Ly, Wikimedia Commons (phạm vi công cộng), lấy từ bài Wikipedia tiếng Việt về cuộc kháng chiến.$hq$, $hq$https://vi.wikipedia.org/wiki/T%E1%BA%ADp_tin:Chongquannguyenlan2.svg$hq$),
    (3, $hq$Kháng chiến lần thứ ba chống quân Nguyên$hq$, $hq$Lần III$hq$, $hq$1287–1288$hq$, $hq$Quân Nguyên$hq$, $hq$Vân Đồn · Bạch Đằng$hq$, $hq$Đánh tan đoàn thuyền lương ở Vân Đồn, dồn giặc vào thế phải rút, rồi tiêu diệt thủy quân Nguyên trên sông Bạch Đằng.$hq$, $hq$ban-do-khang-chien-3$hq$, 1300, 974, $hq$Bản đồ: Lưu Ly, Wikimedia Commons (phạm vi công cộng), lấy từ bài Wikipedia tiếng Việt về cuộc kháng chiến.$hq$, $hq$https://vi.wikipedia.org/wiki/T%E1%BA%ADp_tin:Chongquannguyenlan3.svg$hq$)
ON CONFLICT (campaign_no) DO NOTHING;

INSERT INTO public.hk_saga_cards (code, name, title, rarity, years, intro, role_text, quote, quote_source, source, source_url, portrait, sort_order) VALUES
    ($hq$le-phu-tran$hq$, $hq$Lê Phụ Trần$hq$, $hq$Tướng hộ giá ở Bình Lệ Nguyên$hq$, $hq$rare$hq$, NULL, $hq$Còn gọi là Lê Tần, người Ái Châu, danh tướng phục vụ ba triều vua Trần Thái Tông, Trần Thánh Tông và Trần Nhân Tông. Sử sách không chép năm sinh, năm mất của ông.$hq$, $hq$Trong trận Bình Lệ Nguyên (17/1/1258), ông một mình một ngựa ra vào trận giặc, khuyên vua tạm lui quân, giữ phía sau và lấy ván thuyền che tên cho vua.$hq$, $hq$Nay thì bệ hạ chỉ đánh một ván dốc túi thôi! Hãy nên tạm lánh chúng.$hq$, $hq$Lời can vua ở Bình Lệ Nguyên, theo Đại Việt sử ký toàn thư$hq$, $hq$Wikipedia tiếng Việt, bài “Lê Phụ Trần”$hq$, $hq$https://vi.wikipedia.org/wiki/L%C3%AA_Ph%E1%BB%A5_Tr%E1%BA%A7n$hq$, $hq$le-phu-tran$hq$, 1),
    ($hq$tran-thu-do$hq$, $hq$Trần Thủ Độ$hq$, $hq$Thái sư nhà Trần$hq$, $hq$epic$hq$, $hq$1194 – 1264$hq$, $hq$Nhà chính trị có vai trò lớn trong việc lập nên nhà Trần, giữ chức Thái sư dưới triều vua Trần Thái Tông.$hq$, $hq$Năm 1258, khi quân Trần vừa thua trận và có người khuyên vua sang lánh đất Tống, ông giữ vững quyết tâm kháng chiến của triều đình.$hq$, $hq$Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác.$hq$, $hq$Lời tâu vua Trần Thái Tông trên sông Thiên Mạc, 1258$hq$, $hq$Wikipedia tiếng Việt, bài “Trần Thủ Độ”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Th%E1%BB%A7_%C4%90%E1%BB%99$hq$, $hq$tran-thu-do$hq$, 2),
    ($hq$tran-thai-tong$hq$, $hq$Trần Thái Tông$hq$, $hq$Vị vua đầu tiên của nhà Trần$hq$, $hq$epic$hq$, $hq$1218 – 1277$hq$, $hq$Tên thật là Trần Cảnh, ở ngôi từ năm 1226 đến năm 1258, sau đó làm Thái thượng hoàng.$hq$, $hq$Đích thân chỉ huy trận Bình Lệ Nguyên; nửa đêm 28/1/1258 cùng Thái tử Trần Hoảng ngự lâu thuyền đánh úp quân Mông Cổ ở Đông Bộ Đầu, giải phóng Thăng Long.$hq$, NULL, NULL, $hq$Wikipedia tiếng Việt, bài “Trần Thái Tông”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Th%C3%A1i_T%C3%B4ng$hq$, $hq$tran-thai-tong$hq$, 3),
    ($hq$tran-quoc-toan$hq$, $hq$Trần Quốc Toản$hq$, $hq$Hoài Văn hầu$hq$, $hq$rare$hq$, $hq$1267 – 1285$hq$, $hq$Tông thất nhà Trần. Năm 1282, vì còn nhỏ không được dự hội nghị Bình Than, ông tức giận bóp nát quả cam trong tay lúc nào không hay.$hq$, $hq$Tự tập hợp hơn nghìn gia nô và người nhà, sắm vũ khí, đóng chiến thuyền, dựng cờ sáu chữ; làm phó tướng trong trận Chương Dương năm 1285. Ông mất ngay trong năm ấy; sử sách chép không thống nhất về hoàn cảnh.$hq$, $hq$Phá cường địch, báo hoàng ân.$hq$, $hq$Sáu chữ trên lá cờ: phá giặc mạnh, báo ơn vua$hq$, $hq$Wikipedia tiếng Việt, bài “Trần Quốc Toản”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Qu%E1%BB%91c_To%E1%BA%A3n$hq$, $hq$tran-quoc-toan$hq$, 4),
    ($hq$tran-thanh-tong$hq$, $hq$Trần Thánh Tông$hq$, $hq$Thái thượng hoàng$hq$, $hq$epic$hq$, $hq$1240 – 1290$hq$, $hq$Tên thật là Trần Hoảng, vị vua thứ hai của nhà Trần (1258 – 1278), sau đó làm Thái thượng hoàng. Khi còn là Thái tử, ông cùng vua cha dự trận Đông Bộ Đầu.$hq$, $hq$Mời các bô lão cả nước về điện Diên Hồng hỏi kế đánh giặc; cùng vua Trần Nhân Tông lãnh đạo hai cuộc kháng chiến chống quân Nguyên năm 1285 và 1287 – 1288.$hq$, NULL, NULL, $hq$Wikipedia tiếng Việt, bài “Trần Thánh Tông”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Th%C3%A1nh_T%C3%B4ng$hq$, $hq$tran-thanh-tong$hq$, 5),
    ($hq$tran-binh-trong$hq$, $hq$Trần Bình Trọng$hq$, $hq$Bảo Nghĩa vương$hq$, $hq$epic$hq$, $hq$1259 – 1285$hq$, $hq$Danh tướng nhà Trần, dòng dõi vua Lê Đại Hành, được truy phong Bảo Nghĩa vương.$hq$, $hq$Tháng 2/1285, ông giữ bãi Đà Mạc, cầm chân quân Nguyên để vua và triều đình rút lui an toàn. Bị bắt, ông không chịu đầu hàng và hy sinh ngày 26/2/1285.$hq$, $hq$Ta thà làm ma nước Nam, chứ không thèm làm vương đất Bắc.$hq$, $hq$Lời đáp khi giặc dụ hàng, theo Đại Việt sử ký toàn thư$hq$, $hq$Wikipedia tiếng Việt, bài “Trần Bình Trọng”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_B%C3%ACnh_Tr%E1%BB%8Dng$hq$, $hq$tran-binh-trong$hq$, 6),
    ($hq$tran-nhat-duat$hq$, $hq$Trần Nhật Duật$hq$, $hq$Chiêu Văn vương$hq$, $hq$rare$hq$, $hq$1255 – 1330$hq$, $hq$Con trai thứ sáu của vua Trần Thái Tông, nhà chính trị và quân sự thời Trần.$hq$, $hq$Chỉ huy trận Hàm Tử năm 1285. Trong quân ông có tướng Triệu Trung và những người Tống cũ mặc sắc phục Tống, khiến quân Nguyên hoang mang.$hq$, NULL, NULL, $hq$Wikipedia tiếng Việt, bài “Trần Nhật Duật”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Nh%E1%BA%ADt_Du%E1%BA%ADt$hq$, $hq$tran-nhat-duat$hq$, 7),
    ($hq$tran-quang-khai$hq$, $hq$Trần Quang Khải$hq$, $hq$Thượng tướng thái sư$hq$, $hq$epic$hq$, $hq$1241 – 1294$hq$, $hq$Chiêu Minh đại vương, tôn thất nhà Trần, làm tới chức Thừa tướng, là người cầm quân và cũng là nhà thơ.$hq$, $hq$Làm chánh tướng trận Chương Dương rồi giải phóng Thăng Long năm 1285; tác giả bài thơ “Tụng giá hoàn kinh sư” (Phò giá về kinh).$hq$, $hq$Đoạt sáo Chương Dương độ, / Cầm Hồ Hàm Tử quan.$hq$, $hq$Tụng giá hoàn kinh sư, 1285$hq$, $hq$Wikipedia tiếng Việt, bài “Trần Quang Khải”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Quang_Kh%E1%BA%A3i$hq$, $hq$tran-quang-khai$hq$, 8),
    ($hq$tran-nhan-tong$hq$, $hq$Trần Nhân Tông$hq$, $hq$Vị vua thứ ba của nhà Trần$hq$, $hq$epic$hq$, $hq$1258 – 1308$hq$, $hq$Tên là Trần Khâm, ở ngôi từ năm 1278 đến năm 1293; về sau xuất gia và sáng lập Thiền phái Trúc Lâm Yên Tử.$hq$, $hq$Triệu tập hội nghị Bình Than; cùng Thượng hoàng Trần Thánh Tông lãnh đạo quân dân Đại Việt đánh thắng quân Nguyên hai lần (1285 và 1287 – 1288).$hq$, $hq$Xã tắc hai phen bon ngựa đá, / Non sông ngàn thuở vững âu vàng.$hq$, $hq$Hai câu thơ của vua Trần Nhân Tông (bản dịch)$hq$, $hq$Wikipedia tiếng Việt, bài “Trần Nhân Tông”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Nh%C3%A2n_T%C3%B4ng$hq$, $hq$tran-nhan-tong$hq$, 9),
    ($hq$pham-ngu-lao$hq$, $hq$Phạm Ngũ Lão$hq$, $hq$Danh tướng nhà Trần$hq$, $hq$rare$hq$, $hq$1255 – 1320$hq$, $hq$Danh tướng nổi tiếng thời Trần, lập nhiều chiến công trong hai cuộc kháng chiến chống quân Nguyên.$hq$, $hq$Năm 1285 làm phó tướng cùng Trần Quang Khải đánh trận Chương Dương; tiếp tục cầm quân trong cuộc kháng chiến lần thứ ba.$hq$, NULL, NULL, $hq$Wikipedia tiếng Việt, bài “Phạm Ngũ Lão”$hq$, $hq$https://vi.wikipedia.org/wiki/Ph%E1%BA%A1m_Ng%C5%A9_L%C3%A3o$hq$, $hq$pham-ngu-lao$hq$, 10),
    ($hq$tran-khanh-du$hq$, $hq$Trần Khánh Dư$hq$, $hq$Nhân Huệ vương$hq$, $hq$rare$hq$, $hq$1240 – 1339$hq$, $hq$Nhà quân sự thời Trần. Từng có tội, ông được tha để về dự hội nghị Bình Than năm 1282.$hq$, $hq$Trấn giữ Vân Đồn. Cuối năm 1287, ông đón đánh tan đoàn thuyền lương của Trương Văn Hổ, khiến quân Nguyên thiếu lương và rơi vào thế bị động.$hq$, NULL, NULL, $hq$Wikipedia tiếng Việt, bài “Trần Khánh Dư”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_Kh%C3%A1nh_D%C6%B0$hq$, $hq$tran-khanh-du$hq$, 11),
    ($hq$nguyen-khoai$hq$, $hq$Nguyễn Khoái$hq$, $hq$Chỉ huy quân Thánh Dực$hq$, $hq$rare$hq$, $hq$1240 – 1300$hq$, $hq$Tướng nhà Trần, quê Hồng Châu, chỉ huy quân Thánh Dực, lực lượng cấm quân tinh nhuệ hộ giá vua.$hq$, $hq$Trong trận Bạch Đằng năm 1288, ông chỉ huy quân Thánh Dực giao chiến với thủy quân Nguyên.$hq$, NULL, NULL, $hq$Wikipedia tiếng Việt, bài “Nguyễn Khoái”$hq$, $hq$https://vi.wikipedia.org/wiki/Nguy%E1%BB%85n_Kho%C3%A1i$hq$, $hq$nguyen-khoai$hq$, 12),
    ($hq$tran-hung-dao$hq$, $hq$Trần Hưng Đạo$hq$, $hq$Quốc công Tiết chế$hq$, $hq$legendary$hq$, $hq$? – 1300$hq$, $hq$Tên thật là Trần Quốc Tuấn, con của Trần Liễu, cháu gọi vua Trần Thái Tông bằng chú. Ông là nhà chiến lược quân sự lớn của Đại Việt, mất năm 1300.$hq$, $hq$Thống lĩnh quân đội trong hai cuộc kháng chiến 1285 và 1287 – 1288; viết Hịch tướng sĩ; bày trận địa cọc và chỉ huy trận Bạch Đằng năm 1288.$hq$, $hq$Khoan thư sức dân để làm kế sâu rễ bền gốc, đó là thượng sách giữ nước vậy.$hq$, $hq$Lời dặn vua trước khi mất$hq$, $hq$Wikipedia tiếng Việt, bài “Trần Hưng Đạo”$hq$, $hq$https://vi.wikipedia.org/wiki/Tr%E1%BA%A7n_H%C6%B0ng_%C4%90%E1%BA%A1o$hq$, $hq$tran-hung-dao$hq$, 13)
ON CONFLICT (code) DO NOTHING;

