-- ---------------------------------------------------------------------- chặng 1: Bình Lệ Nguyên (17/1/1258)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$binh-le-nguyen$hq$, 1, 1, $hq$Bình Lệ Nguyên$hq$, $hq$Bình Lệ Nguyên (nay thuộc Vĩnh Phúc)$hq$, $hq$17/1/1258$hq$, $hq$battle$hq$, $hq$swords$hq$, $hq$Trận đánh mở đầu: vua Trần Thái Tông đích thân chỉ huy, thế trận bất lợi nên chủ động lui quân để giữ lực lượng.$hq$, 0.585, 0.5, NULL, NULL, NULL, 70, 100, 30, $hq$le-phu-tran$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Nêu được hoàn cảnh quân Mông Cổ tiến vào Đại Việt và diễn biến trận Bình Lệ Nguyên ngày 17/1/1258."},{"id":"o2","text":"Giải thích được vì sao vua Trần Thái Tông chủ động lui quân để bảo toàn lực lượng."}],"cards":[{"id":"c1","kind":"why","title":"Vì sao giặc tới?","body":"Sau khi chiếm nước Đại Lý, tướng Mông Cổ Ngột Lương Hợp Thai đóng quân sát phía bắc Đại Việt và sai sứ sang dụ hàng. Triều Trần giam sứ giả, truyền cả nước sắm sửa vũ khí và đem quân thủy bộ lên giữ biên giới.","facts":[{"label":"Thời gian","value":"Cuối năm 1257"},{"label":"Chỉ huy Mông Cổ","value":"Ngột Lương Hợp Thai, con là A Truật"}],"objective":"o1","source":"w1","art":"envoy"},{"id":"c2","kind":"how","title":"Trận Bình Lệ Nguyên","body":"Ngày 17/1/1258, vua Trần Thái Tông đích thân chỉ huy, bày voi chiến, kỵ binh và bộ binh bên sông chờ giặc. Quân Mông Cổ bắn tên vào mắt voi; voi đau và hoảng sợ quay lại giẫm vào đội hình khiến quân Trần núng thế.","facts":[{"label":"Ngày","value":"17/1/1258"},{"label":"Nơi","value":"Bình Lệ Nguyên (nay thuộc Vĩnh Phúc)"}],"objective":"o1","source":"w1","art":"elephant"},{"id":"c3","kind":"who","title":"Lê Tần, người hộ giá","body":"Giữa trận, tướng Lê Tần một mình một ngựa ra vào trận giặc, sắc mặt không đổi. Ông can vua đừng “đánh một ván dốc túi” mà hãy tạm lánh. Khi lui quân, ông giữ phía sau và lấy ván thuyền che tên cho vua.","facts":[{"label":"Về sau","value":"Được ban tên Lê Phụ Trần"}],"objective":"o2","source":"w1","art":"shield"},{"id":"c4","kind":"why","title":"Lui quân để giữ sức","body":"Quân Trần thất lợi nhưng lui có trật tự: giữ được thuyền và lực lượng chủ lực, về Phù Lỗ rồi sông Thiên Mạc. Hôm sau, quân Trần chặt cầu Phù Lỗ cản địch rồi chủ động rời Thăng Long. Giữ được quân thì còn ngày phản công.","facts":[{"label":"Trận Phù Lỗ","value":"18/1/1258"}],"objective":"o2","source":"w1","art":"boat"}],"sources":[{"key":"w1","title":"Chiến tranh Nguyên Mông – Đại Việt lần 1","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_1","note":"Bản đồ gốc của bài: Chongquannguyenlan1.svg, tác giả Lưu Ly, phạm vi công cộng."}],"explore":{"scene":"camp","title":"Doanh trại bên đồng Bình Lệ","intro":"Em là tiểu tướng mới vào quân. Giặc đã tới gần, tướng Lê Tần đang chờ người truyền lệnh.","grid":["TTTTTTTTTT==TTTTTTTTTT","T########.==.########T","T#h.h..f..==..f..h.h#T","T#........==........#T","T#..c.....==.....D..#T","T#==================#T","T#..F.....==........#T","T#........==...c.c..#T","T#.h...h..==........#T","T#........==..f.....#T","T########.==.########T","TTTTTTTTT.==.TTTTTTTTT",".........====........."],"spawn":[10,11],"npcs":[{"id":"letan","name":"Lê Tần","role":"Tướng hộ giá","sprite":"general","at":[6,3],"idle":"Giữ vững hàng ngũ. Việc gì cũng phải làm cho chắc.","fictional":false},{"id":"keeper","name":"Người giữ thuyền","role":"Lính thủy quân","sprite":"soldier","at":[15,8],"idle":"Thuyền vẫn buộc chắc ở bến, em yên tâm.","fictional":true},{"id":"mahout","name":"Quản tượng","role":"Người điều khiển voi chiến","sprite":"villager","at":[5,9],"idle":"Voi của ta khỏe lắm, chỉ sợ tên bắn vào mắt.","fictional":true},{"id":"cook","name":"Hỏa đầu quân","role":"Lính nấu bếp","sprite":"villager","at":[5,6],"idle":"Ăn no mới có sức đánh giặc, em ạ.","fictional":true},{"id":"guard","name":"Lính cấm vệ","role":"Canh cổng bắc","sprite":"soldier","at":[12,3],"idle":"Cổng bắc mở ra đồng Bình Lệ. Chưa có lệnh thì chưa ra.","fictional":true}],"items":[{"id":"plank","name":"Tấm ván thuyền","sprite":"plank","at":[16,8]}],"zones":[{"id":"front","name":"Đồng Bình Lệ","rect":[9,0,4,2],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Vào doanh trại gặp tướng Lê Tần để nhận lệnh.","clue":"Lệnh của tướng Lê Tần: thuyền giữ nguyên ở bến sông; voi chiến đi trước, bộ binh theo sau.","type":"talk","npc":"letan","lines":["Quân Mông Cổ đã tới đồng Bình Lệ. Ngài ngự đích thân ra trận.","Em hãy truyền lệnh của ta: “Thuyền giữ nguyên ở bến sông. Voi chiến đi trước, bộ binh theo sau.”","Nhớ cho kỹ rồi tìm người giữ thuyền mà truyền lại."]},{"id":"s2","goal":"Tìm người giữ thuyền: anh lính đứng gần đống bao lương ở phía đông doanh trại.","type":"find","npc":"keeper","lines":["Ta giữ thuyền ở bến đây. Em mang lệnh gì tới?"],"wrong":"Ta không giữ thuyền. Em tìm anh lính đứng gần đống bao lương phía đông ấy."},{"id":"s3","goal":"Truyền lại đúng lệnh của tướng Lê Tần cho người giữ thuyền.","type":"ask","npc":"keeper","prompt":"Lệnh của tướng Lê Tần là gì?","options":[{"id":"a","text":"Đem hết thuyền ra giữa sông đánh trước."},{"id":"b","text":"Thuyền giữ nguyên ở bến; voi chiến đi trước, bộ binh theo sau."},{"id":"c","text":"Đốt thuyền để quân sĩ quyết tử."}],"correct":"b","right":"Rõ! Giữ được thuyền thì khi cần, quân ta còn đường lui về xuôi.","wrong":"Hình như chưa đúng. Em nhớ lại lời tướng quân xem."},{"id":"s4","goal":"Người giữ thuyền nhờ em mang một tấm ván thuyền về cho tướng Lê Tần. Tấm ván ở ngay cạnh anh ấy.","type":"pickup","item":"plank"},{"id":"s5","goal":"Mang tấm ván thuyền về cho tướng Lê Tần.","type":"give","npc":"letan","item":"plank","lines":["Tốt lắm. Ngoài trận tên bay như mưa, tấm ván này sẽ che cho Ngài ngự.","Giặc đã áp sát. Ra cổng bắc, theo ta ra trận!"]},{"id":"s6","goal":"Ra cổng bắc của doanh trại, tiến về đồng Bình Lệ.","type":"battle","zone":"front"},{"id":"s7","goal":"Trở về doanh trại gặp tướng Lê Tần.","type":"talk","npc":"letan","lines":["Hôm nay ta lui quân, nhưng thuyền còn, quân còn.","Giữ được lực lượng thì còn ngày đánh lại. Em ghi nhớ lấy."]}]},"battle":{"mode":"tactics","title":"Trụ vững ở Bình Lệ Nguyên","intro":"Kỵ binh Mông Cổ vượt sông ập tới. Nhiệm vụ của em không phải là diệt hết giặc, mà là trụ vững đủ lâu để vua và chủ lực lui về thuyền an toàn.","allies":[{"id":"voi","name":"Tượng binh","cls":"voi","row":"front","hp":18,"atk":6,"def":2,"spd":3,"skill":{"id":"skill","name":"Voi xung trận","text":"Đòn rất mạnh vào một đơn vị ở hàng trước.","cost":2,"cooldown":2,"kind":"strike","power":1.6},"tags":[],"sprite":"voi"},{"id":"thanhduc","name":"Cấm quân Thánh Dực","cls":"bo","row":"front","hp":16,"atk":5,"def":2,"spd":5,"skill":{"id":"skill","name":"Giáo dài cản ngựa","text":"Đòn mạnh; bộ binh cầm giáo khắc chế kỵ binh.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"bo"},{"id":"letan","name":"Lê Tần","cls":"tuong","row":"front","hp":16,"atk":5,"def":2,"spd":6,"skill":{"id":"skill","name":"Ván thuyền che tên","text":"Che chắn cho một người: người đó chỉ chịu nửa sát thương cho tới hết vòng sau.","cost":1,"cooldown":1,"kind":"cover"},"tags":[],"sprite":"tuong"},{"id":"vua","name":"Vua Trần Thái Tông","cls":"tuong","row":"back","hp":13,"atk":3,"def":1,"spd":4,"skill":{"id":"skill","name":"Đốc chiến","text":"Cả đội tăng sát thương trong 2 vòng.","cost":2,"cooldown":3,"kind":"rally","turns":2},"tags":["vip"],"sprite":"vua"}],"enemies":[{"id":"tiendo","name":"Kỵ binh tiên phong","cls":"ky","row":"front","hp":26,"atk":6,"def":2,"spd":8,"skill":{"id":"skill","name":"Xung kích","text":"Đòn mạnh vào một đơn vị.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"e_ky","note":"Đội tiên phong của Triệt Triệt Đô"},{"id":"kybinh","name":"Kỵ binh Mông Cổ","cls":"ky","row":"front","hp":24,"atk":6,"def":1,"spd":7,"skill":null,"tags":[],"sprite":"e_ky"},{"id":"atruat","name":"Kỵ xạ của A Truật","cls":"cung","row":"back","hp":18,"atk":5,"def":1,"spd":7,"skill":{"id":"skill","name":"Bắn mắt voi","text":"Voi hoảng loạn: choáng một lượt và giẫm vào đơn vị đứng cạnh.","cost":2,"cooldown":3,"kind":"panic"},"tags":[],"sprite":"e_cung"},{"id":"daily","name":"Hàng binh Đại Lý","cls":"bo","row":"front","hp":20,"atk":4,"def":2,"spd":4,"skill":null,"tags":[],"sprite":"e_bo"}],"supply":{"ally":3,"enemy":3,"regen":2,"enemy_regen":2,"per_supply_unit":0},"objective":{"type":"survive","rounds":4},"objective_text":"Trụ vững 4 vòng và giữ an toàn cho vua Trần Thái Tông.","protect":"vua","max_rounds":6,"hunger":null,"stratagem":{"name":"Lui quân có trật tự","text":"Dùng một lần: cả đội được hồi sức. Trả lời đúng thì hiệu quả gấp đôi.","prompt":"Khi voi chiến hoảng loạn và thế trận bất lợi, vua Trần Thái Tông đã quyết định thế nào?","options":[{"id":"a","text":"Dồn hết quân đánh một trận quyết định."},{"id":"b","text":"Chủ động lui quân, giữ thuyền và lực lượng."},{"id":"c","text":"Xin hàng để giữ kinh thành."}],"correct":"b","explain":"Lê Tần can vua đừng “đánh một ván dốc túi”. Vua lui quân về sông Lô rồi sông Thiên Mạc, giữ được thuyền và lực lượng chủ lực.","effect":{"type":"heal_all","value":6}},"tips":["Mục tiêu là trụ vững 4 vòng, không cần diệt hết địch. Địch rất đông, đừng dốc hết sức vào tấn công.","Kỵ xạ địch bắn tới hàng sau: hãy để Lê Tần che chắn cho vua, hoặc cho vua Phòng thủ.","Kỵ xạ địch sẽ bắn mắt voi làm voi hoảng loạn. Phòng thủ giảm nửa sát thương và hồi quân lương."],"win_text":"Quân ta trụ vững rồi lui về sông Thiên Mạc, giữ được thuyền và lực lượng chủ lực.","lose_text":"Đội hình vỡ trước khi kịp lui quân. Hãy che chắn cho vua và đừng dốc hết sức vào tấn công."},"debrief":{"title":"Bình Lệ Nguyên trong sử sách","paragraphs":["Cuối năm 1257, sau khi chiếm Đại Lý, tướng Mông Cổ Ngột Lương Hợp Thai sai sứ sang dụ hàng. Triều Trần giam sứ giả và đem quân thủy bộ giữ biên giới.","Ngày 17/1/1258, hai bên giao chiến ở Bình Lệ Nguyên (nay thuộc Vĩnh Phúc). Vua Trần Thái Tông đích thân chỉ huy. Quân Mông Cổ bắn tên vào mắt voi làm voi hoảng sợ quay lại, quân Trần núng thế.","Tướng Lê Tần khuyên vua tạm lánh, giữ phía sau và lấy ván thuyền che tên cho vua. Quân Trần chủ động lui về Phù Lỗ rồi sông Thiên Mạc; quân Mông Cổ không chiếm được thuyền nên quân Trần bảo toàn được lực lượng.","Ngày 18/1/1258, hai bên chạm trán lần nữa ở Phù Lỗ; sau đó quân Trần chủ động rời Thăng Long. Thua một trận đầu nhưng giữ được quân chính là điều kiện để phản công sau này."],"sources":["w1"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s01-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Trận Bình Lệ Nguyên diễn ra vào ngày nào?$hq$, $hq${"options":[{"id":"a","text":"17/1/1258"},{"id":"b","text":"28/1/1258"},{"id":"c","text":"24/6/1285"},{"id":"d","text":"9/4/1288"}],"correct":"a"}$hq$::jsonb, $hq$Hai bên giao chiến ở Bình Lệ Nguyên ngày 17/1/1258; đêm 28/1/1258 là trận phản công Đông Bộ Đầu.$hq$, $hq$w1$hq$),
    ($hq$s01-p1$hq$, 2, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi nhân vật với việc làm trong trận Bình Lệ Nguyên.$hq$, $hq${"left_label":"Nhân vật","right_label":"Việc làm","pairs":[{"id":"p1","left":"Trần Thái Tông","right":"Đích thân chỉ huy quân Trần"},{"id":"p2","left":"Lê Tần","right":"Lấy ván thuyền che tên cho vua"},{"id":"p3","left":"Ngột Lương Hợp Thai","right":"Chỉ huy quân Mông Cổ"},{"id":"p4","left":"A Truật","right":"Cho bắn tên vào mắt voi"}]}$hq$::jsonb, $hq$Vua Trần Thái Tông đích thân ra trận; Lê Tần hộ giá; Ngột Lương Hợp Thai chỉ huy quân Mông Cổ, con ông là A Truật ra lệnh bắn tên vào mắt voi.$hq$, $hq$w1$hq$),
    ($hq$s01-s1$hq$, 3, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc theo đúng thứ tự thời gian.$hq$, $hq${"items":[{"id":"m1","text":"Sứ Mông Cổ sang dụ hàng, triều Trần giam sứ giả","when":"1257"},{"id":"m2","text":"Vua Trần đem quân thủy bộ lên giữ biên giới","when":"Cuối 1257"},{"id":"m3","text":"Giao chiến ở Bình Lệ Nguyên","when":"17/1/1258"},{"id":"m4","text":"Quân Trần chặt cầu, cản địch ở Phù Lỗ","when":"18/1/1258"}]}$hq$::jsonb, $hq$Dụ hàng không được, quân Mông Cổ tiến đánh. Sau trận Bình Lệ Nguyên (17/1), quân Trần lui về Phù Lỗ và chặt cầu cản địch (18/1).$hq$, $hq$w1$hq$),
    ($hq$s01-t1$hq$, 4, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em là người chỉ huy, em chọn cách nào?$hq$, $hq${"situation":"Voi chiến trúng tên vào mắt, hoảng sợ quay lại giẫm vào đội hình. Quân ta núng thế, nhưng thuyền vẫn còn nguyên ở bến sông.","options":[{"id":"a","text":"Dốc toàn lực đánh tiếp một trận quyết định.","feedback":"Đánh “một ván dốc túi” lúc thế bất lợi có thể mất cả lực lượng chủ lực. Lê Tần đã can vua không làm thế.","score":0},{"id":"b","text":"Lui quân có trật tự, giữ thuyền và lực lượng.","feedback":"Đúng với lựa chọn của vua Trần Thái Tông: lui để bảo toàn lực lượng, chờ thời cơ phản công.","score":2},{"id":"c","text":"Giải tán quân, ai về nhà nấy.","feedback":"Giải tán thì không còn lực lượng để phản công; triều Trần đã không làm vậy.","score":0}]}$hq$::jsonb, $hq$Quân Trần chủ động lui quân, giữ được thuyền và chủ lực. Đó là điều kiện để phản công ở Đông Bộ Đầu mười ngày sau.$hq$, $hq$w1$hq$),
    ($hq$s01-l1$hq$, 5, $hq$locate$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Ngày 18/1/1258, hai bên chạm trán lần nữa tại Phù Lỗ. Hãy chọn Phù Lỗ trên bản đồ.$hq$, $hq${"campaign_no":1,"spots":[{"id":"s1","label":"Quy Hóa","x":0.157,"y":0.285},{"id":"s2","label":"Bạch Hạc","x":0.467,"y":0.447},{"id":"s3","label":"Phù Lỗ","x":0.693,"y":0.547},{"id":"s4","label":"Đông Bộ Đầu","x":0.72,"y":0.7}],"correct":"s3"}$hq$::jsonb, $hq$Phù Lỗ nằm phía bắc Thăng Long, trên đường quân Mông Cổ tiến về kinh thành.$hq$, $hq$w1$hq$),
    ($hq$s01-q2$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Vì sao quân Trần chủ động lui quân sau trận Bình Lệ Nguyên?$hq$, $hq${"options":[{"id":"a","text":"Để bảo toàn lực lượng và thuyền bè, chờ thời cơ phản công"},{"id":"b","text":"Vì quân Trần đã hết lương thực"},{"id":"c","text":"Vì vua Trần muốn sang lánh ở đất Tống"},{"id":"d","text":"Vì quân Mông Cổ đã rút về nước"}],"correct":"a"}$hq$::jsonb, $hq$Thế giặc đang mạnh; lui quân có trật tự giúp giữ được thuyền và lực lượng chủ lực.$hq$, $hq$w1$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$binh-le-nguyen$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 2: Vườn không nhà trống (18 – 27/1/1258)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$vuon-khong-nha-trong$hq$, 1, 2, $hq$Vườn không nhà trống$hq$, $hq$Thăng Long – sông Thiên Mạc$hq$, $hq$18 – 27/1/1258$hq$, $hq$strategy$hq$, $hq$home$hq$, $hq$Triều đình rời Thăng Long, nhân dân cất giấu lương thực. Quân Mông Cổ chiếm kinh thành trống và lâm vào cảnh thiếu lương.$hq$, 0.705, 0.875, NULL, NULL, $hq$binh-le-nguyen$hq$, 70, 100, 30, $hq$tran-thu-do$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Trình bày được kế “vườn không nhà trống” và tác dụng của nó đối với quân Mông Cổ."},{"id":"o2","text":"Nêu được câu nói của Thái sư Trần Thủ Độ và ý nghĩa giữ vững quyết tâm kháng chiến."}],"cards":[{"id":"c1","kind":"why","title":"Điểm yếu của kỵ binh Mông Cổ","body":"Để hành quân thật nhanh, quân Mông Cổ không mang theo dân phu chở lương, chỉ đem ít lương đủ ăn vài ngày rồi cướp lương thực của nơi đánh tới. Họ cũng không có thủy quân nên gặp sông ngòi là lúng túng.","facts":[{"label":"Điểm mạnh","value":"Kỵ binh cơ động"},{"label":"Điểm yếu","value":"Thiếu lương, không có thủy quân"}],"objective":"o1","source":"w1","art":"horse"},{"id":"c2","kind":"how","title":"Vườn không nhà trống","body":"Triều Trần sớm ra lệnh cho nhân dân cất giấu hết lương thực. Sau trận Phù Lỗ, quân Trần chủ động rời Thăng Long. Quân Mông Cổ vào kinh thành nhưng kho tàng trống rỗng, đi cướp lương quanh vùng cũng không được bao nhiêu.","facts":[{"label":"Kết quả","value":"Quân Mông Cổ thiếu lương thực"}],"objective":"o1","source":"w1","art":"granary"},{"id":"c3","kind":"who","title":"Lời Thái sư Trần Thủ Độ","body":"Trên sông Thiên Mạc, vua Trần Thái Tông ngự thuyền đi hỏi kế. Thái úy Trần Nhật Hiệu chấm nước viết hai chữ “nhập Tống” (sang lánh đất Tống). Thái sư Trần Thủ Độ thì tâu: “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác.”","facts":[{"label":"Ý nghĩa","value":"Quyết tâm đánh giặc đến cùng"}],"objective":"o2","source":"w1","art":"scroll"},{"id":"c4","kind":"where","title":"Sông Thiên Mạc","body":"Thiên Mạc là khúc sông nơi vua Trần và triều đình đóng thuyền trú quân sau khi rời Thăng Long. Từ đây quân Trần giữ được lực lượng thủy quân, theo dõi tình hình giặc và chờ thời cơ phản công.","facts":[{"label":"Lợi thế","value":"Thủy quân mạnh, giặc không có thuyền"}],"objective":"o1","source":"w1","art":"river"}],"sources":[{"key":"w1","title":"Chiến tranh Nguyên Mông – Đại Việt lần 1","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_1","note":"Bản đồ gốc của bài: Chongquannguyenlan1.svg, tác giả Lưu Ly, phạm vi công cộng."}],"explore":{"scene":"village","title":"Làng ven kinh thành","intro":"Lệnh của triều đình đã về tới làng: không để lại gì cho giặc. Em giúp dân làng cất giấu lương thực rồi lên thuyền về xuôi.","grid":["BBBBBBBBBB==BBBBBBBBBB","B.H..H....==....H..H.B","B.........==.........B","B..,...W..==..,......B","B====================B","B.........==.........B","B.H.......==....%%%%.B","B.....T...==....%%%%.B","B..c......==....%%%%.B","B.........==.........B","B.~~~.....==..H...H..B","B.~~~.....==.........B","BBBBBBBBBB==BBBBBBBBBB"],"spawn":[10,11],"npcs":[{"id":"chief","name":"Ông trưởng làng","role":"Người truyền lệnh triều đình","sprite":"elder","at":[8,3],"idle":"Làng ta không để lại cho giặc một hạt thóc nào.","fictional":true},{"id":"boatman","name":"Bác lái đò","role":"Chở lương về xuôi","sprite":"villager","at":[5,9],"idle":"Thuyền của bác chở được nhiều lắm, cứ mang thóc ra đây.","fictional":true},{"id":"granny","name":"Bà cụ đầu làng","role":"Người ở lại sau cùng","sprite":"woman","at":[17,2],"idle":"Bà còn cái chum tương, tiếc quá con ạ.","fictional":true},{"id":"boy","name":"Cậu bé chăn trâu","role":"Dắt trâu vào rừng","sprite":"boy","at":[14,9],"idle":"Em dắt trâu vào rừng tre rồi, giặc không tìm thấy đâu.","fictional":true},{"id":"farmer","name":"Chú nông dân","role":"Giấu thóc","sprite":"villager","at":[13,5],"idle":"Thóc gặt rồi phải giấu ngay, không thì giặc lấy mất.","fictional":true}],"items":[{"id":"rice","name":"Bao thóc","sprite":"rice","at":[4,8]}],"zones":[{"id":"pier","name":"Bến thuyền về xuôi","rect":[9,11,4,2],"kind":"goal"}],"steps":[{"id":"s1","goal":"Gặp ông trưởng làng bên giếng nước để nghe lệnh của triều đình.","clue":"Lệnh của triều đình: cất giấu hết thóc gạo, dắt trâu bò vào rừng, người theo thuyền về xuôi; không để lại lương thực cho giặc.","type":"talk","npc":"chief","lines":["Giặc sắp tới kinh thành. Triều đình truyền: thóc gạo cất giấu hết, trâu bò dắt vào rừng, người thì theo thuyền về xuôi.","Tuyệt đối không để lại lương thực cho giặc. Giặc không cướp được gì thì sẽ đói."]},{"id":"s2","goal":"Mang bao thóc còn để ngoài sân (phía tây nam làng) đi cất.","type":"pickup","item":"rice"},{"id":"s3","goal":"Đưa bao thóc cho bác lái đò ở bờ ao để chở về xuôi.","type":"give","npc":"boatman","item":"rice","lines":["Được rồi, thóc này bác chở theo thuyền. Giặc tới chỉ thấy vườn không nhà trống!"]},{"id":"s4","goal":"Còn một người chưa rời làng. Tìm bà cụ ở căn nhà phía đông bắc và mời bà lên thuyền.","type":"find","npc":"granny","lines":["Thôi được, bà đi. Giữ được người, giữ được thóc thì giặc tới cũng tay trắng."],"wrong":"Tôi sắp đi rồi. Em tìm bà cụ ở căn nhà phía đông bắc xem."},{"id":"s5","goal":"Trở lại báo với ông trưởng làng.","type":"ask","npc":"chief","prompt":"Ông hỏi lại cho chắc: vì sao ta phải cất giấu hết lương thực?","options":[{"id":"a","text":"Để quân giặc không cướp được lương, dần đói và suy yếu."},{"id":"b","text":"Để đem bán cho quân giặc lấy tiền."},{"id":"c","text":"Vì năm nay mất mùa nên phải để dành."}],"correct":"a","right":"Đúng thế. Quân Mông Cổ đi nhanh nên mang ít lương, toàn trông vào cướp bóc. Không cướp được thì chúng không ở lâu được.","wrong":"Chưa phải. Em nhớ lại lời triều đình truyền xem."},{"id":"s6","goal":"Ra bến ở cổng nam, lên thuyền về xuôi cùng dân làng.","type":"zone","zone":"pier"}]},"battle":null,"debrief":{"title":"Kinh thành trống và lời Trần Thủ Độ","paragraphs":["Quân Mông Cổ hành quân nhanh nên mang rất ít lương, chủ yếu dựa vào cướp bóc. Triều Trần nhận ra điểm yếu này và sớm ra lệnh cho nhân dân cất giấu lương thực.","Sau trận Phù Lỗ (18/1/1258), quân Trần chủ động rời Thăng Long. Quân Mông Cổ chiếm được kinh thành nhưng kho tàng trống rỗng, cướp lương quanh vùng cũng không kết quả, lâm vào cảnh thiếu lương thực.","Trên sông Thiên Mạc, khi vua Trần Thái Tông hỏi kế, Thái úy Trần Nhật Hiệu viết hai chữ “nhập Tống”, còn Thái sư Trần Thủ Độ tâu: “Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác.” Lời ấy giữ vững quyết tâm kháng chiến của triều đình."],"sources":["w1"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s02-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$“Đầu thần chưa rơi xuống đất, bệ hạ đừng lo gì khác” là lời của ai?$hq$, $hq${"options":[{"id":"a","text":"Thái sư Trần Thủ Độ"},{"id":"b","text":"Thái úy Trần Nhật Hiệu"},{"id":"c","text":"Tướng Lê Tần"},{"id":"d","text":"Thái tử Trần Hoảng"}],"correct":"a"}$hq$::jsonb, $hq$Thái sư Trần Thủ Độ tâu với vua Trần Thái Tông trên sông Thiên Mạc, thể hiện quyết tâm đánh giặc đến cùng.$hq$, $hq$w1$hq$),
    ($hq$s02-p1$hq$, 2, $hq$pairs$hq$, $hq$practice$hq$, $hq$o2$hq$, $hq$Lật thẻ và ghép mỗi nhân vật với lời nói hoặc việc làm.$hq$, $hq${"left_label":"Nhân vật","right_label":"Lời nói, việc làm","pairs":[{"id":"p1","left":"Trần Thủ Độ","right":"“Đầu thần chưa rơi xuống đất…”"},{"id":"p2","left":"Trần Nhật Hiệu","right":"Viết hai chữ “nhập Tống”"},{"id":"p3","left":"Trần Thái Tông","right":"Ngự thuyền đi hỏi kế giữ nước"},{"id":"p4","left":"Quân Mông Cổ","right":"Chiếm kinh thành trống, thiếu lương"}]}$hq$::jsonb, $hq$Trước cùng một câu hỏi của vua, Trần Nhật Hiệu khuyên sang lánh đất Tống, còn Trần Thủ Độ quyết tâm kháng chiến.$hq$, $hq$w1$hq$),
    ($hq$s02-t1$hq$, 3, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là người chỉ huy, em chọn cách nào?$hq$, $hq${"situation":"Giặc mạnh về kỵ binh, đi rất nhanh nhưng mang ít lương và không có thuyền. Quân ta vừa thua một trận, thủy quân còn nguyên.","options":[{"id":"a","text":"Cố thủ trong thành Thăng Long đến cùng.","feedback":"Cố thủ là đánh theo cách giặc muốn: chúng vây thành và ta có thể mất cả lực lượng.","score":0},{"id":"b","text":"Rời kinh thành, cất giấu lương thực, giữ quân trên sông chờ giặc suy yếu.","feedback":"Đây chính là điều triều Trần đã làm: tránh chỗ mạnh, đánh vào chỗ yếu là thiếu lương của giặc.","score":2},{"id":"c","text":"Chia quân nhỏ đi cướp lương của giặc.","feedback":"Quấy rối hậu cần là hướng đúng, nhưng giặc vốn mang rất ít lương. Việc chính vẫn là không để chúng cướp được lương của ta.","score":1}]}$hq$::jsonb, $hq$Kế “vườn không nhà trống” đánh vào điểm yếu thiếu lương của quân Mông Cổ, trong khi quân Trần giữ được lực lượng trên sông.$hq$, $hq$w1$hq$),
    ($hq$s02-s1$hq$, 4, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Triều đình ra lệnh cho dân cất giấu lương thực"},{"id":"m2","text":"Quân Trần chủ động rời Thăng Long"},{"id":"m3","text":"Quân Mông Cổ vào kinh thành, kho tàng trống rỗng"},{"id":"m4","text":"Quân Mông Cổ thiếu lương thực, suy yếu dần"}]}$hq$::jsonb, $hq$Chuẩn bị trước, rồi rời kinh thành; giặc chiếm thành nhưng không có lương nên suy yếu.$hq$, $hq$w1$hq$),
    ($hq$s02-q2$hq$, 5, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Vì sao quân Mông Cổ dễ rơi vào cảnh thiếu lương?$hq$, $hq${"options":[{"id":"a","text":"Vì hành quân nhanh, mang ít lương và trông vào cướp bóc"},{"id":"b","text":"Vì thuyền lương bị đánh chìm ở Vân Đồn"},{"id":"c","text":"Vì mùa màng năm ấy thất bát"},{"id":"d","text":"Vì bị quân Tống chặn đường tiếp tế"}],"correct":"a"}$hq$::jsonb, $hq$Kỵ binh Mông Cổ không mang theo dân phu chở lương; khi không cướp được lương của dân thì thiếu ăn. Trận Vân Đồn thuộc cuộc kháng chiến lần thứ ba.$hq$, $hq$w1$hq$),
    ($hq$s02-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Sau khi rời Thăng Long, vua Trần và triều đình trú quân ở đâu?$hq$, $hq${"options":[{"id":"a","text":"Trên sông Thiên Mạc"},{"id":"b","text":"Ở Vạn Kiếp"},{"id":"c","text":"Ở Thanh Hóa"},{"id":"d","text":"Ở Vân Đồn"}],"correct":"a"}$hq$::jsonb, $hq$Triều đình đóng thuyền trên sông Thiên Mạc, giữ được thủy quân và chờ thời cơ phản công.$hq$, $hq$w1$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$vuon-khong-nha-trong$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 3: Đông Bộ Đầu (Đêm 28/1/1258)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$dong-bo-dau$hq$, 1, 3, $hq$Đông Bộ Đầu$hq$, $hq$Bến Đông Bộ Đầu (Thăng Long)$hq$, $hq$Đêm 28/1/1258$hq$, $hq$battle$hq$, $hq$flame$hq$, $hq$Nửa đêm 28/1/1258, quân Trần từ Thiên Mạc ngược sông đánh úp quân Mông Cổ ở Đông Bộ Đầu, giải phóng Thăng Long.$hq$, 0.715, 0.695, NULL, NULL, $hq$vuon-khong-nha-trong$hq$, 70, 150, 50, $hq$tran-thai-tong$hq$, $hq$saga-dong-bo-dau$hq$,
     $hq${"objectives":[{"id":"o1","text":"Thuật lại được trận phản công Đông Bộ Đầu đêm 28/1/1258 và kết quả của cuộc kháng chiến lần thứ nhất."},{"id":"o2","text":"Giải thích được vì sao quân Trần chọn đúng thời điểm đó để phản công."}],"cards":[{"id":"c1","kind":"why","title":"Thời cơ đã đến","body":"Chiếm được Thăng Long nhưng quân Mông Cổ thiếu lương thực. Thấy quân Trần thua trận đầu, chúng cho rằng lực lượng ta đã kiệt quệ nên rất chủ quan. Quân Trần thì vẫn giữ được thuyền và chủ lực ở Thiên Mạc.","facts":[{"label":"Giặc","value":"Thiếu lương, chủ quan"},{"label":"Ta","value":"Còn nguyên thủy quân"}],"objective":"o2","source":"w1","art":"moon"},{"id":"c2","kind":"how","title":"Đánh úp lúc nửa đêm","body":"Nửa đêm 28/1/1258, từ Thiên Mạc, vua Trần Thái Tông cùng Thái tử Trần Hoảng ngự lâu thuyền ngược sông, bất ngờ đánh thẳng vào quân Mông Cổ ở Đông Bộ Đầu. Giặc không kịp trở tay, thua to.","facts":[{"label":"Thời điểm","value":"Nửa đêm 28/1/1258"},{"label":"Chỉ huy","value":"Trần Thái Tông, Thái tử Trần Hoảng"}],"objective":"o1","source":"w1","art":"boat"},{"id":"c3","kind":"where","title":"Giặc rút về Vân Nam","body":"Thua ở Đông Bộ Đầu, quân Mông Cổ không giữ nổi Thăng Long, rút chạy về Vân Nam theo dọc sông Thao. Tới Quy Hóa, chúng bị chủ trại Hà Bổng tập kích. Vì rút quá nhanh, không kịp cướp phá, giặc bị dân ta gọi mỉa là “giặc Bụt”.","facts":[{"label":"Tập kích ở Quy Hóa","value":"Chủ trại Hà Bổng"}],"objective":"o1","source":"w1","art":"map"},{"id":"c4","kind":"why","title":"Vì sao ta thắng?","body":"Lui quân đúng lúc để giữ lực lượng, cất giấu lương thực làm giặc đói, rồi phản công bất ngờ khi giặc chủ quan: ba việc nối tiếp nhau làm nên thắng lợi của cuộc kháng chiến lần thứ nhất.","facts":[{"label":"Kết quả","value":"Đại Việt giữ vững độc lập"}],"objective":"o2","source":"w1","art":"star"}],"sources":[{"key":"w1","title":"Chiến tranh Nguyên Mông – Đại Việt lần 1","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_1","note":"Bản đồ gốc của bài: Chongquannguyenlan1.svg, tác giả Lưu Ly, phạm vi công cộng."}],"explore":{"scene":"riverside","title":"Bến thuyền Thiên Mạc","intro":"Đêm đã khuya. Đoàn lâu thuyền lặng lẽ chuẩn bị ngược sông. Em mang lệnh xuất quân của nhà vua.","grid":["TTTTTTTTTTTTTTTTTTTTTT","T....h....==.....h...T","T.........==.........T","T..f......==......c..T","T====================T","T.........==.........T","T...T.....==...D.....T","T.........==.........T","::::::::::++::::::::::","~~~~b~~~~~++~~~~~b~~~~","~~~~~~~~~~++~~~~~~~~~~","~~~~~~~b~~~~~~b~~~~~~~","~~~~~~~~~~~~~~~~~~~~~~"],"spawn":[10,1],"npcs":[{"id":"captain","name":"Viên thuyền trưởng","role":"Chỉ huy lâu thuyền","sprite":"general","at":[9,7],"idle":"Sông đêm nay lặng gió, thuận cho thuyền ngược dòng.","fictional":true},{"id":"scout","name":"Lính trinh sát","role":"Vừa từ Thăng Long về","sprite":"scout","at":[16,2],"idle":"Ta mới ở kinh thành về, biết rõ tình hình giặc.","fictional":true},{"id":"drummer","name":"Người giữ trống","role":"Đánh trống lệnh","sprite":"soldier","at":[14,6],"idle":"Chưa có cờ lệnh thì ta chưa nổi trống.","fictional":true},{"id":"oarsman","name":"Anh lính chèo","role":"Thủy binh","sprite":"soldier","at":[5,5],"idle":"Mái chèo đã quấn giẻ, chèo không một tiếng động.","fictional":true},{"id":"sentry","name":"Lính gác lều","role":"Canh doanh trại","sprite":"soldier","at":[4,2],"idle":"Ai cũng đang chờ lệnh xuất quân.","fictional":true}],"items":[{"id":"flag","name":"Cờ lệnh","sprite":"flag","at":[4,3]}],"zones":[{"id":"dock","name":"Cầu thuyền ra sông","rect":[10,9,2,2],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Xuống bến gặp viên thuyền trưởng để nghe kế hoạch.","clue":"Kế hoạch: đúng nửa đêm lâu thuyền ngược sông; không đốt đuốc, không đánh trống trước khi tới bến Đông Bộ Đầu.","type":"talk","npc":"captain","lines":["Lệnh của Ngài ngự: “Đúng nửa đêm, lâu thuyền ngược sông. Không đốt đuốc, không đánh trống trước khi tới bến Đông Bộ Đầu.”","Trước hết em tìm người trinh sát vừa ở kinh thành về, hỏi cho rõ tình hình giặc."]},{"id":"s2","goal":"Tìm người lính trinh sát vừa từ Thăng Long về: anh đứng gần đống bao lương phía đông bắc.","type":"find","npc":"scout","lines":["Ta vừa ở kinh thành về đây. Giặc chiếm thành mà kho trống, lương sắp cạn. Chúng tưởng quân ta đã tan nên canh phòng lơ là."],"wrong":"Ta không đi trinh sát. Người em cần tìm đứng gần đống bao lương phía đông bắc."},{"id":"s3","goal":"Về báo tình hình giặc cho viên thuyền trưởng.","type":"ask","npc":"captain","prompt":"Tình hình quân giặc ở Thăng Long thế nào?","options":[{"id":"a","text":"Giặc đông, lương nhiều, canh phòng cẩn mật."},{"id":"b","text":"Giặc thiếu lương và chủ quan, canh phòng lơ là."},{"id":"c","text":"Giặc đã rút hết về nước."}],"correct":"b","right":"Vậy là thời cơ đã đến. Giặc đói và chủ quan, ta đánh úp lúc nửa đêm là trúng.","wrong":"Người trinh sát nói khác cơ. Em nhớ lại xem."},{"id":"s4","goal":"Lấy lá cờ lệnh cắm trước lều chỉ huy ở phía tây bắc.","type":"pickup","item":"flag"},{"id":"s5","goal":"Trao cờ lệnh cho người giữ trống.","type":"give","npc":"drummer","item":"flag","lines":["Có cờ lệnh rồi! Tới bến Đông Bộ Đầu ta mới nổi trống xung trận."]},{"id":"s6","goal":"Ra cầu thuyền, theo đoàn lâu thuyền ngược sông.","type":"battle","zone":"dock"},{"id":"s7","goal":"Trở lại bến gặp viên thuyền trưởng.","type":"talk","npc":"captain","lines":["Giặc tan rồi! Chúng bỏ Thăng Long chạy về Vân Nam.","Lui đúng lúc, đánh đúng lúc. Kinh thành lại về tay ta."]}]},"battle":{"mode":"tactics","title":"Đánh úp Đông Bộ Đầu","intro":"Lâu thuyền áp sát bến trong đêm. Giặc đang đói và chủ quan. Hãy đánh nhanh trước khi chúng kịp dàn trận.","allies":[{"id":"lauthuyen","name":"Lâu thuyền của vua","cls":"thuyen","row":"front","hp":18,"atk":6,"def":2,"spd":5,"ranged":true,"skill":{"id":"skill","name":"Nỏ lớn trên thuyền","text":"Bắn mạnh vào một đơn vị ở bất kỳ hàng nào.","cost":2,"cooldown":2,"kind":"strike","power":1.6,"ranged":true},"tags":[],"sprite":"thuyen"},{"id":"thaitu","name":"Thuyền Thái tử Trần Hoảng","cls":"thuyen","row":"front","hp":16,"atk":5,"def":2,"spd":6,"ranged":true,"skill":{"id":"skill","name":"Mưa tên","text":"Bắn cả một hàng quân địch.","cost":3,"cooldown":3,"kind":"volley","power":0.9},"tags":[],"sprite":"thuyen"},{"id":"dobo","name":"Quân đổ bộ","cls":"bo","row":"front","hp":16,"atk":5,"def":2,"spd":7,"skill":{"id":"skill","name":"Xung phong lên bến","text":"Đòn mạnh; bộ binh cầm giáo khắc chế kỵ binh.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"bo"}],"enemies":[{"id":"kybinh","name":"Kỵ binh Mông Cổ","cls":"ky","row":"front","hp":22,"atk":6,"def":1,"spd":8,"skill":{"id":"skill","name":"Xung kích","text":"Đòn mạnh vào một đơn vị.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"e_ky"},{"id":"canhtrai","name":"Lính canh trại","cls":"bo","row":"front","hp":18,"atk":5,"def":1,"spd":4,"skill":null,"tags":[],"sprite":"e_bo"},{"id":"kyxa","name":"Kỵ xạ","cls":"cung","row":"back","hp":16,"atk":5,"def":1,"spd":7,"skill":null,"tags":[],"sprite":"e_cung"}],"supply":{"ally":3,"enemy":1,"regen":2,"enemy_regen":1,"per_supply_unit":0},"objective":{"type":"eliminate"},"objective_text":"Đánh tan quân Mông Cổ ở bến Đông Bộ Đầu trong 7 vòng.","protect":null,"max_rounds":7,"hunger":{"from_round":1,"dmg":1},"stratagem":{"name":"Tập kích nửa đêm","text":"Dùng một lần: quân địch bị choáng một lượt. Trả lời đúng thì cả đội hình địch bị choáng.","prompt":"Vì sao quân Trần chọn phản công vào nửa đêm 28/1/1258?","options":[{"id":"a","text":"Vì giặc thiếu lương và chủ quan, tưởng quân Trần đã kiệt quệ."},{"id":"b","text":"Vì quân Trần vừa được quân Tống tiếp viện."},{"id":"c","text":"Vì giặc đã rút hết khỏi Thăng Long."}],"correct":"a","explain":"Quân Mông Cổ chiếm kinh thành trống nên thiếu lương, lại cho rằng quân Trần đã kiệt quệ. Bị tập kích lúc nửa đêm, chúng không kịp trở tay.","effect":{"type":"stun_all","turns":1}},"tips":["Giặc đang thiếu lương nên mất máu dần mỗi vòng và ít dùng được kỹ năng.","Thuyền bắn được cả hàng sau của địch.","Dùng mưu kế “Tập kích nửa đêm” sớm để chiếm thế chủ động."],"win_text":"Quân Mông Cổ thua to, không giữ nổi Thăng Long và rút chạy về Vân Nam.","lose_text":"Chưa dứt điểm được trước khi giặc dàn xong trận. Hãy dùng mưu kế sớm và tập trung đánh từng đơn vị."},"debrief":{"title":"Đông Bộ Đầu và kết cục năm 1258","paragraphs":["Chiếm được Thăng Long sau hai trận đánh nhưng quân Mông Cổ gặp kho tàng trống rỗng và thiếu lương thực. Thấy quân Trần thua trận đầu, chúng chủ quan cho rằng lực lượng ta đã kiệt quệ.","Nửa đêm 28/1/1258, từ nơi trú quân trên sông Thiên Mạc, vua Trần Thái Tông cùng Thái tử Trần Hoảng ngự lâu thuyền ngược sông, bất ngờ đánh thẳng vào quân Mông Cổ ở Đông Bộ Đầu. Giặc không kịp trở tay, thua to.","Quân Mông Cổ bỏ Thăng Long, rút chạy về Vân Nam. Tới Quy Hóa, chúng bị chủ trại Hà Bổng, một thổ quan người Tày, tập kích. Do rút quá nhanh, không kịp cướp phá, chúng bị dân gian gọi mỉa là “giặc Bụt”.","Cuộc kháng chiến lần thứ nhất kết thúc thắng lợi. Bài học lớn: lui quân giữ lực lượng, làm giặc thiếu lương, rồi phản công đúng thời cơ."],"sources":["w1"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s03-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Quân Trần phản công ở Đông Bộ Đầu vào thời điểm nào?$hq$, $hq${"options":[{"id":"a","text":"Nửa đêm 28/1/1258"},{"id":"b","text":"Sáng 17/1/1258"},{"id":"c","text":"Trưa 18/1/1258"},{"id":"d","text":"Sáng 9/4/1288"}],"correct":"a"}$hq$::jsonb, $hq$Nửa đêm 28/1/1258, lâu thuyền của vua Trần Thái Tông và Thái tử Trần Hoảng ngược sông đánh úp quân Mông Cổ.$hq$, $hq$w1$hq$),
    ($hq$s03-s1$hq$, 2, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc của cuộc kháng chiến lần thứ nhất theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Giao chiến ở Bình Lệ Nguyên","when":"17/1/1258"},{"id":"m2","text":"Quân Trần rời Thăng Long, giặc chiếm kinh thành trống","when":"Sau 18/1/1258"},{"id":"m3","text":"Quân Trần đánh úp ở Đông Bộ Đầu","when":"Đêm 28/1/1258"},{"id":"m4","text":"Giặc rút về Vân Nam, bị tập kích ở Quy Hóa","when":"Cuối tháng 1/1258"}]}$hq$::jsonb, $hq$Lui quân, làm giặc thiếu lương, phản công, rồi truy kích trên đường giặc rút.$hq$, $hq$w1$hq$),
    ($hq$s03-t1$hq$, 3, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em là người chỉ huy, em chọn cách nào?$hq$, $hq${"situation":"Trinh sát báo: giặc ở Thăng Long thiếu lương, canh phòng lơ là vì tưởng quân ta đã tan. Thủy quân ta còn nguyên ở Thiên Mạc.","options":[{"id":"a","text":"Tiếp tục chờ thêm vài tháng cho chắc.","feedback":"Chờ lâu thì giặc có thể kiếm được lương hoặc phát hiện quân ta. Thời cơ không chờ người.","score":0},{"id":"b","text":"Ngược sông đánh úp ngay trong đêm.","feedback":"Đúng như vua Trần Thái Tông đã làm: đánh bất ngờ lúc giặc đói và chủ quan.","score":2},{"id":"c","text":"Dàn quân giữa ban ngày, thách giặc ra đánh.","feedback":"Dàn trận ban ngày làm mất yếu tố bất ngờ, lại đúng sở trường kỵ binh của giặc.","score":0}]}$hq$::jsonb, $hq$Thời cơ phản công đến khi giặc suy yếu và chủ quan; đánh ban đêm bằng thủy quân phát huy thế mạnh của ta.$hq$, $hq$w1$hq$),
    ($hq$s03-l1$hq$, 4, $hq$locate$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Trên đường rút chạy, quân Mông Cổ bị chủ trại Hà Bổng tập kích ở đâu?$hq$, $hq${"campaign_no":1,"spots":[{"id":"s1","label":"Quy Hóa","x":0.157,"y":0.285},{"id":"s2","label":"Bạch Hạc","x":0.467,"y":0.447},{"id":"s3","label":"Phù Lỗ","x":0.693,"y":0.547},{"id":"s4","label":"Đông Bộ Đầu","x":0.72,"y":0.7}],"correct":"s1"}$hq$::jsonb, $hq$Quy Hóa (vùng Lào Cai, Yên Bái ngày nay) nằm trên đường quân Mông Cổ rút về Vân Nam dọc sông Thao.$hq$, $hq$w1$hq$),
    ($hq$s03-q2$hq$, 5, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Vì sao dân gian gọi mỉa quân Mông Cổ lúc rút chạy là “giặc Bụt”?$hq$, $hq${"options":[{"id":"a","text":"Vì chúng rút quá nhanh, không kịp cướp phá dân chúng"},{"id":"b","text":"Vì chúng theo đạo Phật"},{"id":"c","text":"Vì chúng xây nhiều chùa ở Thăng Long"},{"id":"d","text":"Vì chúng thả hết tù binh"}],"correct":"a"}$hq$::jsonb, $hq$Sợ bị truy kích, quân Mông Cổ cố rút thật nhanh và không cướp phá, nên bị gọi mỉa là “giặc Bụt” (hiền như Bụt).$hq$, $hq$w1$hq$),
    ($hq$s03-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Đâu là chuỗi việc làm nên thắng lợi năm 1258?$hq$, $hq${"options":[{"id":"a","text":"Lui quân giữ lực lượng, làm giặc thiếu lương, phản công đúng thời cơ"},{"id":"b","text":"Cố thủ trong thành, chờ viện binh nhà Tống"},{"id":"c","text":"Đánh một trận quyết định ngay ở biên giới"},{"id":"d","text":"Cầu hòa rồi chờ giặc tự rút"}],"correct":"a"}$hq$::jsonb, $hq$Ba việc nối tiếp nhau: bảo toàn lực lượng, “vườn không nhà trống”, rồi tập kích Đông Bộ Đầu.$hq$, $hq$w1$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$dong-bo-dau$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 4: Hội nghị Bình Than (Cuối năm 1282)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$binh-than$hq$, 2, 4, $hq$Hội nghị Bình Than$hq$, $hq$Bến Bình Than$hq$, $hq$Cuối năm 1282$hq$, $hq$council$hq$, $hq$users$hq$, $hq$Chuẩn bị trước khi giặc sang: vua Trần Nhân Tông họp vương hầu, tướng lĩnh bàn kế đánh, kế phòng và chia quân giữ nơi hiểm yếu.$hq$, 0.478, 0.233, NULL, NULL, NULL, 70, 100, 30, $hq$tran-quoc-toan$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Nêu được thời gian, mục đích của hội nghị Bình Than và biết đây là việc chuẩn bị trước cuộc kháng chiến lần thứ hai."},{"id":"o2","text":"Kể được chuyện Trần Quốc Toản bóp nát quả cam và lá cờ sáu chữ."}],"cards":[{"id":"c1","kind":"why","title":"Giặc chuẩn bị quay lại","body":"Sau khi thôn tính Nam Tống, nhà Nguyên ráo riết chuẩn bị đánh Đại Việt. Nhận được tin, triều Trần không chờ giặc tới mới lo: các vương hầu được lệnh tuyển thêm quân, quân đội liên tục tập trận.","facts":[{"label":"Kẻ địch","value":"Nhà Nguyên (vua Hốt Tất Liệt)"}],"objective":"o1","source":"w2","art":"envoy"},{"id":"c2","kind":"when","title":"Hội nghị Bình Than","body":"Cuối năm 1282, vua Trần Nhân Tông họp vương hầu và các tướng ở Bình Than để “bàn kế đánh phòng” và “chia quân giữ nơi hiểm yếu”. Đây là hội nghị quân sự, diễn ra hơn hai năm trước khi giặc tràn sang.","facts":[{"label":"Thời gian","value":"Cuối năm 1282"},{"label":"Người triệu tập","value":"Vua Trần Nhân Tông"}],"objective":"o1","source":"w2","art":"boat"},{"id":"c3","kind":"who","title":"Dùng người lúc nước nhà cần","body":"Những tướng lĩnh đang có tội, như Trần Khánh Dư, đều được tha để về hội nghị bàn việc nước. Sau này chính Trần Khánh Dư lập công lớn ở Vân Đồn trong cuộc kháng chiến lần thứ ba.","facts":[{"label":"Nhân vật","value":"Trần Khánh Dư"}],"objective":"o1","source":"w2","art":"general"},{"id":"c4","kind":"who","title":"Quả cam và lá cờ sáu chữ","body":"Trần Quốc Toản còn nhỏ tuổi nên không được dự bàn. Tức giận, ông bóp nát quả cam trong tay lúc nào không hay. Về quê, ông tập hợp hơn nghìn gia nô và người nhà, sắm vũ khí, đóng chiến thuyền, dựng cờ sáu chữ “Phá cường địch, báo hoàng ân”.","facts":[{"label":"Nghĩa sáu chữ","value":"Phá giặc mạnh, báo ơn vua"}],"objective":"o2","source":"w2","art":"flag"}],"sources":[{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."}],"explore":{"scene":"riverside","title":"Bến Bình Than","intro":"Thuyền của vương hầu, tướng lĩnh đậu kín bến. Em là tiểu tướng giúp việc ở hội nghị.","grid":["TTTTTTTTTTTTTTTTTTTTTT","T....h....==.....h...T","T.........==.........T","T..f......==......c..T","T====================T","T.........==.........T","T...T.....==...D.....T","T.........==.........T","::::::::::++::::::::::","~~~~b~~~~~++~~~~~b~~~~","~~~~~~~~~~++~~~~~~~~~~","~~~~~~~b~~~~~~b~~~~~~~","~~~~~~~~~~~~~~~~~~~~~~"],"spawn":[10,1],"npcs":[{"id":"guard","name":"Lính gác bến","role":"Canh nơi họp","sprite":"soldier","at":[9,3],"idle":"Bến đang có hội nghị, người lạ không được vào.","fictional":true},{"id":"khanhdu","name":"Trần Khánh Dư","role":"Tướng vừa được tha tội","sprite":"general","at":[5,7],"idle":"Nước nhà cần người, ta về đây bàn việc nước.","fictional":false},{"id":"hungdao","name":"Hưng Đạo vương","role":"Trần Quốc Tuấn","sprite":"commander","at":[8,5],"idle":"Phải lo giữ nước từ khi giặc chưa tới.","fictional":false},{"id":"quoctoan","name":"Trần Quốc Toản","role":"Hoài Văn hầu, còn nhỏ tuổi","sprite":"youth","at":[16,6],"idle":"Ta cũng muốn bàn việc đánh giặc!","fictional":false},{"id":"clerk","name":"Viên quan ghi chép","role":"Thư lại","sprite":"scholar","at":[13,2],"idle":"Ta đang chép lại lời bàn của hội nghị.","fictional":true}],"items":[{"id":"token","name":"Thẻ bài hội nghị","sprite":"token","at":[3,2]}],"zones":[{"id":"road","name":"Đường rời bến","rect":[9,1,4,1],"kind":"goal"}],"steps":[{"id":"s1","goal":"Hỏi người lính gác bến xem hội nghị bàn việc gì.","clue":"Hội nghị Bình Than bàn kế đánh, kế phòng và chia quân giữ những nơi hiểm yếu.","type":"talk","npc":"guard","lines":["Vua ngự ra Bình Than, họp vương hầu và các tướng.","Hội nghị bàn kế đánh, kế phòng và chia quân giữ những nơi hiểm yếu."]},{"id":"s2","goal":"Tìm vị tướng vừa được tha tội để về dự hội nghị: ông đứng gần chiếc thuyền ở bến phía tây.","type":"find","npc":"khanhdu","lines":["Ta là Trần Khánh Dư. Trước có tội, nay vua tha cho về bàn việc nước.","Em lấy thẻ bài ở lều phía tây bắc, mang tới cho Hưng Đạo vương giúp ta."],"wrong":"Ta không phải người em tìm. Vị ấy đứng gần chiếc thuyền ở bến phía tây."},{"id":"s3","goal":"Lấy thẻ bài hội nghị ở gần lều phía tây bắc.","type":"pickup","item":"token"},{"id":"s4","goal":"Mang thẻ bài tới cho Hưng Đạo vương.","type":"give","npc":"hungdao","item":"token","lines":["Tốt. Giặc Nguyên đang ráo riết chuẩn bị. Lần này ta phải chia quân giữ những nơi hiểm yếu từ sớm."]},{"id":"s5","goal":"Trả lời câu hỏi của Hưng Đạo vương.","type":"ask","npc":"hungdao","prompt":"Em nhắc lại xem: hội nghị Bình Than bàn việc gì?","options":[{"id":"a","text":"Bàn việc xin hàng để tránh chiến tranh."},{"id":"b","text":"Bàn kế đánh, kế phòng và chia quân giữ nơi hiểm yếu."},{"id":"c","text":"Bàn việc dời đô vào Thanh Hóa."}],"correct":"b","right":"Đúng. Chuẩn bị trước chính là một nửa thắng lợi.","wrong":"Chưa đúng. Em hỏi lại người lính gác bến xem."},{"id":"s6","goal":"Còn một người rất muốn dự hội nghị mà chưa đủ tuổi. Tìm cậu thiếu niên đứng cạnh chiếc trống lớn phía đông.","type":"find","npc":"quoctoan","lines":["Ta là Hoài Văn hầu Trần Quốc Toản. Vua bảo ta còn nhỏ, chưa được dự bàn. Quả cam trong tay ta nát lúc nào không hay!","Ta sẽ về tập hợp gia nô và người nhà, sắm vũ khí, đóng chiến thuyền, dựng cờ “Phá cường địch, báo hoàng ân”."],"wrong":"Ta không phải cậu ấy. Cậu thiếu niên đứng cạnh chiếc trống lớn phía đông."},{"id":"s7","goal":"Hội nghị đã xong. Theo đường lớn phía bắc rời bến Bình Than.","type":"zone","zone":"road"}]},"battle":null,"debrief":{"title":"Bình Than: lo giữ nước từ khi giặc chưa tới","paragraphs":["Sau khi diệt Nam Tống, nhà Nguyên chuẩn bị đánh Đại Việt lần nữa. Triều Trần tăng cường quân đội: các vương hầu tuyển thêm quân, quân sĩ tập trận liên tục.","Cuối năm 1282, vua Trần Nhân Tông triệu tập hội nghị quân sự ở Bình Than để bàn kế đánh, kế phòng và chia quân giữ nơi hiểm yếu. Các tướng đang có tội như Trần Khánh Dư cũng được tha để về bàn việc.","Đại Việt sử ký toàn thư chép: Trần Quốc Toản vì nhỏ tuổi không được dự hội nghị, tức giận bóp nát quả cam; sau đó ông tự tập hợp hơn nghìn người, dựng cờ sáu chữ “Phá cường địch, báo hoàng ân”."],"sources":["w2"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s04-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Hội nghị Bình Than họp để làm gì?$hq$, $hq${"options":[{"id":"a","text":"Bàn kế đánh, kế phòng và chia quân giữ nơi hiểm yếu"},{"id":"b","text":"Hỏi ý các bô lão nên hòa hay nên đánh"},{"id":"c","text":"Ăn mừng chiến thắng Đông Bộ Đầu"},{"id":"d","text":"Chọn người nối ngôi vua"}],"correct":"a"}$hq$::jsonb, $hq$Bình Than là hội nghị quân sự của vua với vương hầu, tướng lĩnh. Hỏi ý các bô lão là hội nghị Diên Hồng.$hq$, $hq$w2$hq$),
    ($hq$s04-p1$hq$, 2, $hq$pairs$hq$, $hq$practice$hq$, $hq$o2$hq$, $hq$Lật thẻ và ghép mỗi nhân vật với chi tiết gắn với hội nghị Bình Than.$hq$, $hq${"left_label":"Nhân vật","right_label":"Chi tiết","pairs":[{"id":"p1","left":"Trần Nhân Tông","right":"Triệu tập hội nghị"},{"id":"p2","left":"Trần Khánh Dư","right":"Được tha tội để về bàn việc"},{"id":"p3","left":"Trần Quốc Toản","right":"Bóp nát quả cam vì không được dự"},{"id":"p4","left":"Hốt Tất Liệt","right":"Vua Nguyên, chuẩn bị xâm lược"}]}$hq$::jsonb, $hq$Vua Trần Nhân Tông triệu tập; Trần Khánh Dư được tha tội về dự; Trần Quốc Toản còn nhỏ nên không được dự bàn.$hq$, $hq$w2$hq$),
    ($hq$s04-s1$hq$, 3, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các việc chuẩn bị kháng chiến theo đúng thứ tự thời gian.$hq$, $hq${"items":[{"id":"m1","text":"Nhà Nguyên ráo riết chuẩn bị đánh Đại Việt"},{"id":"m2","text":"Hội nghị Bình Than","when":"Cuối 1282"},{"id":"m3","text":"Hội nghị Diên Hồng","when":"Đầu 1285"},{"id":"m4","text":"Quân Nguyên tiến vào Đại Việt","when":"1285"}]}$hq$::jsonb, $hq$Bình Than (cuối 1282) họp trước Diên Hồng (đầu 1285); cả hai đều là việc chuẩn bị trước khi giặc sang.$hq$, $hq$w2$hq$),
    ($hq$s04-q2$hq$, 4, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Sáu chữ trên lá cờ của Trần Quốc Toản có nghĩa là gì?$hq$, $hq${"options":[{"id":"a","text":"Phá giặc mạnh, báo ơn vua"},{"id":"b","text":"Thà chết không hàng"},{"id":"c","text":"Giữ nước cốt ở lòng dân"},{"id":"d","text":"Đánh cho giặc không còn manh giáp"}],"correct":"a"}$hq$::jsonb, $hq$“Phá cường địch, báo hoàng ân” nghĩa là phá giặc mạnh, báo ơn vua.$hq$, $hq$w2$hq$),
    ($hq$s04-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là người cầm quân, em chọn cách nào?$hq$, $hq${"situation":"Tin báo về: nhà Nguyên vừa diệt xong Nam Tống và đang chuẩn bị đánh nước ta. Giặc chưa sang.","options":[{"id":"a","text":"Chờ giặc sang rồi mới bàn cách đối phó.","feedback":"Giặc rất mạnh và đi nhanh; đợi chúng tới mới lo thì không kịp.","score":0},{"id":"b","text":"Họp ngay các tướng, bàn kế và chia quân giữ nơi hiểm yếu.","feedback":"Đúng như triều Trần đã làm ở Bình Than: chuẩn bị từ khi giặc chưa tới.","score":2},{"id":"c","text":"Đem quân sang đánh nhà Nguyên trước.","feedback":"Lực lượng chênh lệch rất lớn; đánh sang đất giặc là bỏ mọi lợi thế của người giữ nước.","score":0}]}$hq$::jsonb, $hq$Chuẩn bị sớm, dùng đúng người và chia quân giữ nơi hiểm yếu giúp Đại Việt không bị động khi giặc tràn sang.$hq$, $hq$w2$hq$),
    ($hq$s04-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Hội nghị Bình Than diễn ra khi nào so với cuộc kháng chiến lần thứ hai?$hq$, $hq${"options":[{"id":"a","text":"Hơn hai năm trước khi giặc sang (cuối 1282)"},{"id":"b","text":"Ngay sau trận Tây Kết"},{"id":"c","text":"Giữa lúc giặc đang chiếm Thăng Long"},{"id":"d","text":"Sau khi giặc đã rút về nước"}],"correct":"a"}$hq$::jsonb, $hq$Bình Than họp cuối năm 1282, còn quân Nguyên tới đầu năm 1285 mới tràn sang.$hq$, $hq$w2$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$binh-than$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 5: Hội nghị Diên Hồng (Đầu năm 1285)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$dien-hong$hq$, 2, 5, $hq$Hội nghị Diên Hồng$hq$, $hq$Điện Diên Hồng (Thăng Long)$hq$, $hq$Đầu năm 1285$hq$, $hq$council$hq$, $hq$landmark$hq$, $hq$Thượng hoàng Trần Thánh Tông hỏi các bô lão nên hòa hay nên đánh; muôn người cùng hô “Đánh!”. Hịch tướng sĩ khích lệ quân sĩ.$hq$, 0.362, 0.272, NULL, NULL, $hq$binh-than$hq$, 70, 100, 30, $hq$tran-thanh-tong$hq$, $hq$saga-dien-hong$hq$,
     $hq${"objectives":[{"id":"o1","text":"Trình bày được nội dung và ý nghĩa của hội nghị Diên Hồng."},{"id":"o2","text":"Nêu được vai trò của Hịch tướng sĩ và hai chữ “Sát Thát” đối với tinh thần quân đội."}],"cards":[{"id":"c1","kind":"when","title":"Điện Diên Hồng","body":"Đầu năm 1285 (tháng Chạp năm Giáp Thân), khi giặc sắp tràn sang, Thái thượng hoàng Trần Thánh Tông mời các bậc tuổi cao có uy tín trong cả nước về điện Diên Hồng ở Thăng Long để trình bày chủ trương của triều đình.","facts":[{"label":"Người triệu tập","value":"Thượng hoàng Trần Thánh Tông"},{"label":"Người dự","value":"Các bô lão cả nước"}],"objective":"o1","source":"w2","art":"palace"},{"id":"c2","kind":"how","title":"“Đánh!”","body":"Khi được hỏi có nên đánh lại quân Nguyên hay không, các bô lão đồng thanh trả lời “Đánh!”. Đại Việt sử ký toàn thư chép: “vạn người cùng nói như từ một miệng”.","facts":[{"label":"Ý nghĩa","value":"Cả nước đồng lòng đánh giặc"}],"objective":"o1","source":"w2","art":"crowd"},{"id":"c3","kind":"who","title":"Hịch tướng sĩ và “Sát Thát”","body":"Trần Quốc Tuấn viết Hịch tướng sĩ để nâng cao tinh thần quân sĩ. Nhiều chiến sĩ thích lên cánh tay hai chữ “Sát Thát” (giết giặc Thát, tức quân Mông – Nguyên) để tỏ quyết tâm chiến đấu.","facts":[{"label":"Tác giả","value":"Trần Quốc Tuấn"}],"objective":"o2","source":"w2","art":"scroll"},{"id":"c4","kind":"who","title":"Người cầm quân","body":"Trần Quốc Tuấn được phong Quốc công Tiết chế, thống lĩnh mọi lực lượng của Đại Việt; Trần Quang Khải giữ chức Thượng tướng thái sư. Triều đình còn ra lệnh: giặc đến phải liều chết mà đánh, sức không địch nổi thì lánh vào rừng núi, không được đầu hàng.","facts":[{"label":"Tổng chỉ huy","value":"Quốc công Tiết chế Trần Quốc Tuấn"}],"objective":"o2","source":"w2","art":"general"}],"sources":[{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."}],"explore":{"scene":"palace","title":"Thềm điện Diên Hồng","intro":"Các bô lão từ khắp nước đã về kinh. Em theo viên quan truyền chỉ vào thềm điện.","grid":["wwwwwwwwwwwwwwwwwwwwww","wwwwwwwww____wwwwwwwww","#__P______________P__#","#____________________#","#__P______________P__#","#____________________#","#__f______________f__#","#____________________#","#__P______________P__#","#____________________#","#########____#########","..T......====......T..",".........====........."],"spawn":[10,12],"npcs":[{"id":"thuonghoang","name":"Thượng hoàng Trần Thánh Tông","role":"Người triệu tập hội nghị","sprite":"king","at":[10,2],"idle":"Việc nước là việc của muôn dân.","fictional":false},{"id":"herald","name":"Viên quan truyền chỉ","role":"Dẫn các bô lão","sprite":"scholar","at":[8,8],"idle":"Các cụ đã về đông đủ cả rồi.","fictional":true},{"id":"elder1","name":"Cụ bô lão Kinh Bắc","role":"Bô lão","sprite":"elder","at":[5,5],"idle":"Làng lão trai tráng đã tập võ cả năm nay.","fictional":true},{"id":"elder2","name":"Cụ bô lão xứ Thanh","role":"Bô lão","sprite":"elder","at":[16,5],"idle":"Xứ Thanh sẵn thóc gạo nuôi quân.","fictional":true},{"id":"elder3","name":"Cụ bô lão chống gậy trúc","role":"Bô lão đi xa nhất","sprite":"elder","at":[15,7],"idle":"Lão đi mười ngày đường mới tới kinh.","fictional":true},{"id":"crier","name":"Lính truyền hịch","role":"Đọc hịch cho quân sĩ","sprite":"soldier","at":[4,8],"idle":"Ta đang chờ bản hịch để đọc cho anh em.","fictional":true}],"items":[{"id":"scroll","name":"Bản Hịch tướng sĩ","sprite":"scroll","at":[12,4]}],"zones":[{"id":"door","name":"Cửa điện","rect":[9,10,4,1],"kind":"goal"}],"steps":[{"id":"s1","goal":"Hỏi viên quan truyền chỉ về hội nghị.","clue":"Thượng hoàng hỏi các bô lão: giặc Nguyên sắp sang, nên hòa hay nên đánh?","type":"talk","npc":"herald","lines":["Thượng hoàng mời các bô lão khắp nước về điện Diên Hồng.","Người chỉ hỏi một điều: giặc Nguyên sắp sang, nên hòa hay nên đánh?"]},{"id":"s2","goal":"Tìm cụ bô lão chống gậy trúc, đứng gần lá cờ phía đông điện, để hỏi ý cụ.","type":"find","npc":"elder3","lines":["Giặc mạnh thật. Nhưng vua tôi một lòng, dân cả nước một lòng thì lo gì không thắng."],"wrong":"Lão không chống gậy trúc. Cụ ấy đứng gần lá cờ phía đông kia."},{"id":"s3","goal":"Giữa điện có một bản hịch của Hưng Đạo vương. Hãy cầm lấy.","type":"pickup","item":"scroll"},{"id":"s4","goal":"Mang bản hịch cho người lính truyền hịch ở phía tây điện.","type":"give","npc":"crier","item":"scroll","lines":["Đây là Hịch tướng sĩ. Hưng Đạo vương viết để khích lệ tướng sĩ luyện tập, sẵn sàng đánh giặc.","Nghe hịch xong, anh em trong quân thích lên cánh tay hai chữ “Sát Thát”."]},{"id":"s5","goal":"Lên thềm điện, nơi Thượng hoàng đang hỏi ý các bô lão.","type":"ask","npc":"thuonghoang","prompt":"Thượng hoàng hỏi: “Thế giặc mạnh, nên hòa hay nên đánh?” Các bô lão trả lời thế nào?","options":[{"id":"a","text":"“Xin hòa!”"},{"id":"b","text":"“Đánh!”"},{"id":"c","text":"“Xin dời đô!”"}],"correct":"b","right":"Muôn người cùng hô như từ một miệng: “Đánh!”","wrong":"Các bô lão không trả lời như thế. Em nghĩ lại xem."},{"id":"s6","goal":"Hội nghị đã xong. Ra cửa điện phía nam.","type":"zone","zone":"door"}]},"battle":null,"debrief":{"title":"Diên Hồng: cả nước một lòng","paragraphs":["Đầu năm 1285 (tháng Chạp năm Giáp Thân), Thái thượng hoàng Trần Thánh Tông mời các bô lão có uy tín trong cả nước về điện Diên Hồng ở Thăng Long. Khi được hỏi có nên đánh lại quân Nguyên hay không, các bô lão “vạn người cùng nói như từ một miệng”: “Đánh!”.","Trước đó, Trần Quốc Tuấn đã viết Hịch tướng sĩ để khích lệ quân sĩ; nhiều chiến sĩ thích hai chữ “Sát Thát” lên cánh tay. Ông được phong Quốc công Tiết chế, thống lĩnh toàn bộ lực lượng.","Bình Than là hội nghị của vương hầu, tướng lĩnh; Diên Hồng là hội nghị hỏi ý dân. Hai hội nghị cho thấy sự đồng lòng từ triều đình tới nhân dân trước khi giặc sang."],"sources":["w2"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s05-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Ai đã mời các bô lão về điện Diên Hồng?$hq$, $hq${"options":[{"id":"a","text":"Thái thượng hoàng Trần Thánh Tông"},{"id":"b","text":"Thái sư Trần Thủ Độ"},{"id":"c","text":"Trần Quốc Toản"},{"id":"d","text":"Trần Khánh Dư"}],"correct":"a"}$hq$::jsonb, $hq$Thái thượng hoàng Trần Thánh Tông mời các bậc tuổi cao có uy tín trong cả nước về điện Diên Hồng.$hq$, $hq$w2$hq$),
    ($hq$s05-p1$hq$, 2, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi hội nghị, văn bản với nội dung của nó.$hq$, $hq${"left_label":"Sự kiện","right_label":"Nội dung","pairs":[{"id":"p1","left":"Hội nghị Bình Than","right":"Vua bàn kế đánh với vương hầu, tướng lĩnh"},{"id":"p2","left":"Hội nghị Diên Hồng","right":"Hỏi ý các bô lão: hòa hay đánh"},{"id":"p3","left":"Hịch tướng sĩ","right":"Khích lệ tinh thần quân sĩ"},{"id":"p4","left":"Hai chữ “Sát Thát”","right":"Thích lên tay tỏ quyết tâm giết giặc"}]}$hq$::jsonb, $hq$Bình Than: hội nghị quân sự; Diên Hồng: hỏi ý dân; Hịch tướng sĩ và “Sát Thát”: nâng cao tinh thần quân đội.$hq$, $hq$w2$hq$),
    ($hq$s05-q2$hq$, 3, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Hai chữ “Sát Thát” có nghĩa là gì?$hq$, $hq${"options":[{"id":"a","text":"Giết giặc Thát (quân Mông – Nguyên)"},{"id":"b","text":"Giữ thành đến cùng"},{"id":"c","text":"Thà chết không lui"},{"id":"d","text":"Đánh nhanh thắng nhanh"}],"correct":"a"}$hq$::jsonb, $hq$“Sát” là giết, “Thát” chỉ người Mông Cổ; chiến sĩ thích hai chữ này lên tay để tỏ quyết tâm.$hq$, $hq$w2$hq$),
    ($hq$s05-s1$hq$, 4, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc theo đúng thứ tự thời gian.$hq$, $hq${"items":[{"id":"m1","text":"Hội nghị Bình Than","when":"Cuối 1282"},{"id":"m2","text":"Hội nghị Diên Hồng","when":"Đầu 1285"},{"id":"m3","text":"Quân Nguyên đánh tới Thăng Long","when":"17 – 18/2/1285"},{"id":"m4","text":"Quân Trần tổng phản công","when":"Từ tháng 5/1285"}]}$hq$::jsonb, $hq$Chuẩn bị (Bình Than, Diên Hồng), giặc tràn sang, rồi quân Trần lui quân và phản công.$hq$, $hq$w2$hq$),
    ($hq$s05-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là người lãnh đạo, em chọn cách nào?$hq$, $hq${"situation":"Giặc rất mạnh và sắp tràn sang. Muốn kháng chiến lâu dài thì phải dựa vào sức dân cả nước.","options":[{"id":"a","text":"Giữ kín chủ trương, chỉ triều đình biết.","feedback":"Dân không biết chủ trương thì khó đồng lòng làm “vườn không nhà trống” hay nuôi quân.","score":0},{"id":"b","text":"Mời các bô lão về kinh, hỏi ý dân và nói rõ quyết tâm đánh giặc.","feedback":"Đúng như Thượng hoàng đã làm ở Diên Hồng: lấy sự đồng lòng của dân làm gốc.","score":2},{"id":"c","text":"Bắt dân các làng phải nộp hết lương thực cho triều đình.","feedback":"Ép buộc làm mất lòng dân, trong khi kháng chiến cần dân tự nguyện góp sức.","score":0}]}$hq$::jsonb, $hq$Hội nghị Diên Hồng biến quyết tâm của triều đình thành quyết tâm của cả nước.$hq$, $hq$w2$hq$),
    ($hq$s05-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Ai được phong Quốc công Tiết chế, thống lĩnh toàn bộ lực lượng Đại Việt?$hq$, $hq${"options":[{"id":"a","text":"Trần Quốc Tuấn"},{"id":"b","text":"Trần Quang Khải"},{"id":"c","text":"Trần Nhật Duật"},{"id":"d","text":"Trần Bình Trọng"}],"correct":"a"}$hq$::jsonb, $hq$Trần Quốc Tuấn (Hưng Đạo vương) được phong Quốc công Tiết chế; Trần Quang Khải giữ chức Thượng tướng thái sư.$hq$, $hq$w2$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$dien-hong$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 6: Rút lui chiến lược (Tháng 2/1285)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$rut-lui-1285$hq$, 2, 6, $hq$Rút lui chiến lược$hq$, $hq$Thăng Long → Thiên Trường$hq$, $hq$Tháng 2/1285$hq$, $hq$strategy$hq$, $hq$shield$hq$, $hq$Trước thế giặc mạnh, quân Trần rời Thăng Long, làm “vườn không nhà trống”. Trần Bình Trọng chặn giặc ở bãi Đà Mạc để triều đình rút lui an toàn.$hq$, 0.355, 0.415, NULL, NULL, $hq$dien-hong$hq$, 70, 120, 40, $hq$tran-binh-trong$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Giải thích được vì sao Trần Quốc Tuấn chọn lui binh và “vườn không nhà trống” thay vì đối đầu trực diện."},{"id":"o2","text":"Kể được việc Trần Bình Trọng chặn giặc ở bãi Đà Mạc và câu nói bất khuất của ông."}],"cards":[{"id":"c1","kind":"why","title":"Giặc muốn đánh nhanh","body":"Với sức mạnh áp đảo, quân Nguyên muốn đánh nhanh thắng nhanh. Trần Quốc Tuấn hiểu rằng đối đầu trực diện là trúng ý giặc, còn đội quân đánh nhanh có một điểm yếu chí tử: hậu cần không bảo đảm được lâu dài.","facts":[{"label":"Điểm yếu của giặc","value":"Lương thảo"}],"objective":"o1","source":"w2","art":"horse"},{"id":"c2","kind":"how","title":"Lui binh, vườn không nhà trống","body":"Quân Trần chuyển từ đối đầu sang lui binh, làm “vườn không nhà trống” để triệt nguồn lương của giặc. Ngày 17 – 18/2/1285, quân Trần cản giặc bên sông Hồng cho kịp sơ tán hoàng gia và dân chúng, rồi rời Thăng Long. Giặc vào thành chỉ thấy “cung thất nhẵn không”.","facts":[{"label":"Giặc tới Thăng Long","value":"17 – 18/2/1285"}],"objective":"o1","source":"w2","art":"granary"},{"id":"c3","kind":"who","title":"Trần Bình Trọng ở Đà Mạc","body":"Để cản giặc đuổi theo đường sông, Trần Bình Trọng chặn đánh ở bãi Đà Mạc. Khoảng 600 quân Thánh Dực kìm chân mấy nghìn quân giặc qua 6 đợt tấn công. Ông bị bắt; khi giặc dụ hàng, ông trả lời: “Ta thà làm ma nước Nam, chứ không thèm làm vương đất Bắc.”","facts":[{"label":"Hy sinh","value":"26/2/1285"}],"objective":"o2","source":"w2","art":"shield"},{"id":"c4","kind":"where","title":"Giữ quân chờ thời","body":"Quân Trần lui về Thiên Trường (Nam Định), Trường Yên (Ninh Bình), rồi vào Thanh Hóa để củng cố. Ở ngoài bắc, quân Nguyên không hợp thủy thổ, gặp mùa hè nóng bức, mưa lớn, bệnh tật và thiếu lương.","facts":[{"label":"Nơi lui quân","value":"Thiên Trường, Trường Yên, Thanh Hóa"}],"objective":"o1","source":"w2","art":"river"}],"sources":[{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."}],"explore":{"scene":"riverside","title":"Bãi sông Đà Mạc","intro":"Thuyền ngự vừa rời Thăng Long. Giặc đuổi sát phía sau. Em nhận lệnh của tướng Trần Bình Trọng.","grid":["TTTTTTTTTTTTTTTTTTTTTT","T....h....==.....h...T","T.........==.........T","T..f......==......c..T","T====================T","T.........==.........T","T...T.....==...D.....T","T.........==.........T","::::::::::++::::::::::","~~~~b~~~~~++~~~~~b~~~~","~~~~~~~~~~++~~~~~~~~~~","~~~~~~~b~~~~~~b~~~~~~~","~~~~~~~~~~~~~~~~~~~~~~"],"spawn":[10,1],"npcs":[{"id":"binhtrong","name":"Trần Bình Trọng","role":"Tướng chặn hậu","sprite":"general","at":[15,3],"idle":"Còn ta ở đây thì giặc chưa qua được bãi sông này.","fictional":false},{"id":"helmsman","name":"Người lái thuyền ngự","role":"Thủy binh","sprite":"soldier","at":[9,7],"idle":"Thuyền đã sẵn sào, chỉ chờ lệnh.","fictional":true},{"id":"fisher","name":"Bác dân chài","role":"Dân ven sông","sprite":"villager","at":[3,6],"idle":"Thóc lúa nhà bác giấu cả rồi, giặc tới chỉ còn vườn không.","fictional":true},{"id":"soldier1","name":"Lính Thánh Dực","role":"Cấm quân","sprite":"soldier","at":[13,5],"idle":"Sáu trăm anh em ta sẽ giữ bãi sông này.","fictional":true},{"id":"soldier2","name":"Lính Thánh Dực","role":"Cấm quân","sprite":"soldier","at":[17,6],"idle":"Giặc đông, nhưng bãi sông hẹp, chúng không dàn hết quân được.","fictional":true}],"items":[{"id":"banner","name":"Cờ hiệu Thánh Dực","sprite":"flag","at":[4,3]}],"zones":[{"id":"east","name":"Đường phía đông","rect":[19,4,2,1],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Gặp tướng Trần Bình Trọng ở phía đông bến.","clue":"Lệnh của tướng Trần Bình Trọng: thuyền ngự xuôi về Thiên Trường ngay, không để lại dấu vết.","type":"talk","npc":"binhtrong","lines":["Thăng Long đã bỏ trống, giặc đang đuổi theo thuyền ngự.","Ta cùng quân Thánh Dực ở lại bãi Đà Mạc cầm chân chúng. Em truyền lệnh: “Thuyền ngự xuôi về Thiên Trường ngay, không để lại dấu vết.”"]},{"id":"s2","goal":"Tìm người lái thuyền ngự: ông đứng gần đầu cầu ván ra sông.","type":"find","npc":"helmsman","lines":["Ta lái thuyền ngự đây. Lệnh của tướng quân thế nào?"],"wrong":"Ta không lái thuyền ngự. Ông ấy đứng gần đầu cầu ván kia."},{"id":"s3","goal":"Truyền lại đúng lệnh cho người lái thuyền ngự.","type":"ask","npc":"helmsman","prompt":"Lệnh của tướng Trần Bình Trọng là gì?","options":[{"id":"a","text":"Cho thuyền quay lại Thăng Long."},{"id":"b","text":"Thuyền ngự xuôi về Thiên Trường ngay, không để lại dấu vết."},{"id":"c","text":"Neo thuyền chờ ở bãi Đà Mạc."}],"correct":"b","right":"Rõ! Nhổ sào ngay. Có quân Thánh Dực chặn hậu, thuyền ngự sẽ đi thoát.","wrong":"Hình như không phải. Em nhớ lại lời tướng quân xem."},{"id":"s4","goal":"Lấy lá cờ hiệu Thánh Dực cắm ở phía tây bắc bến.","type":"pickup","item":"banner"},{"id":"s5","goal":"Mang cờ hiệu về cho tướng Trần Bình Trọng.","type":"give","npc":"binhtrong","item":"banner","lines":["Cờ Thánh Dực đã dựng. Anh em ta sẽ giữ bãi sông này.","Giặc tới rồi, ở phía đường đông!"]},{"id":"s6","goal":"Theo đường lớn ra phía đông, nơi giặc đang kéo tới.","type":"battle","zone":"east"},{"id":"s7","goal":"Trở lại gặp tướng Trần Bình Trọng.","type":"talk","npc":"binhtrong","lines":["Thuyền ngự đã đi xa. Việc của ta thế là xong.","Em theo đường thủy về Thiên Trường đi. Giữ lấy thân mà đánh giặc lâu dài."]}]},"battle":{"mode":"tactics","title":"Chặn giặc ở bãi Đà Mạc","intro":"Quân Nguyên đuổi theo thuyền ngự. Quân Thánh Dực phải cầm chân chúng đủ lâu. Không cần diệt hết giặc, chỉ cần giữ vững bãi sông.","allies":[{"id":"binhtrong","name":"Trần Bình Trọng","cls":"tuong","row":"front","hp":24,"atk":6,"def":3,"spd":6,"skill":{"id":"skill","name":"Thề giữ bãi sông","text":"Cả đội tăng sát thương trong 2 vòng.","cost":2,"cooldown":3,"kind":"rally","turns":2},"tags":[],"sprite":"tuong"},{"id":"thanhduc1","name":"Quân Thánh Dực","cls":"bo","row":"front","hp":18,"atk":5,"def":2,"spd":5,"skill":{"id":"skill","name":"Giáo dài cản ngựa","text":"Đòn mạnh; bộ binh cầm giáo khắc chế kỵ binh.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"bo"},{"id":"thanhduc2","name":"Quân Thánh Dực","cls":"bo","row":"front","hp":18,"atk":5,"def":2,"spd":7,"skill":{"id":"skill","name":"Khiên che đồng đội","text":"Che chắn cho một người: người đó chỉ chịu nửa sát thương cho tới hết vòng sau.","cost":1,"cooldown":1,"kind":"cover"},"tags":[],"sprite":"bo"}],"enemies":[{"id":"ky1","name":"Kỵ binh Nguyên","cls":"ky","row":"front","hp":26,"atk":6,"def":2,"spd":8,"skill":{"id":"skill","name":"Xung kích","text":"Đòn mạnh vào một đơn vị.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"e_ky"},{"id":"ky2","name":"Kỵ binh Nguyên","cls":"ky","row":"front","hp":24,"atk":6,"def":1,"spd":7,"skill":null,"tags":[],"sprite":"e_ky"},{"id":"bo1","name":"Bộ binh Nguyên","cls":"bo","row":"front","hp":22,"atk":5,"def":2,"spd":4,"skill":null,"tags":[],"sprite":"e_bo"},{"id":"cung","name":"Cung thủ Nguyên","cls":"cung","row":"back","hp":16,"atk":5,"def":1,"spd":6,"skill":null,"tags":[],"sprite":"e_cung"}],"supply":{"ally":3,"enemy":3,"regen":2,"enemy_regen":2,"per_supply_unit":0},"objective":{"type":"survive","rounds":4},"objective_text":"Giữ vững bãi sông 4 vòng: chỉ cần quân ta còn trụ lại là giặc chưa qua được.","protect":null,"max_rounds":6,"hunger":null,"stratagem":{"name":"Lấy ít địch nhiều","text":"Dùng một lần: cả đội tăng sát thương. Trả lời đúng thì hiệu lực dài gấp đôi.","prompt":"Nhiệm vụ của Trần Bình Trọng ở bãi Đà Mạc là gì?","options":[{"id":"a","text":"Tiêu diệt toàn bộ quân Nguyên."},{"id":"b","text":"Cầm chân giặc để triều đình rút lui an toàn."},{"id":"c","text":"Chiếm lại Thăng Long."}],"correct":"b","explain":"Trần Bình Trọng giữ bãi Đà Mạc để chặn giặc đuổi theo, bảo đảm cho vua và triều đình rút lui an toàn.","effect":{"type":"rally_all","turns":2}},"tips":["Mục tiêu là trụ vững 4 vòng. Giặc đông gấp bội: Phòng thủ giảm nửa sát thương và hồi quân lương.","Bộ binh cầm giáo khắc chế kỵ binh.","Dùng “Khiên che đồng đội” cho người đang bị đánh nhiều nhất."],"win_text":"Quân Thánh Dực đã cầm chân giặc đủ lâu, thuyền ngự đi thoát. Trong lịch sử, Trần Bình Trọng bị bắt sau trận này và hy sinh, không chịu đầu hàng.","lose_text":"Phòng tuyến vỡ quá sớm. Hãy luân phiên phòng thủ, che chắn cho nhau và đừng dốc hết sức vào tấn công."},"debrief":{"title":"Lui để thắng","paragraphs":["Quân Nguyên muốn đánh nhanh thắng nhanh. Trần Quốc Tuấn chủ trương không đối đầu trực diện mà lui binh, làm “vườn không nhà trống” để triệt nguồn lương của giặc, chờ chúng suy yếu mới phản công.","Ngày 17 – 18/2/1285, quân Trần cản giặc bên sông Hồng để kịp sơ tán hoàng gia và dân chúng, rồi rời Thăng Long. Quân Nguyên vào thành chỉ thấy cung thất trống không.","Trên đường rút theo sông Hồng, Trần Bình Trọng chặn giặc ở bãi Đà Mạc: khoảng 600 quân Thánh Dực kìm chân mấy nghìn quân giặc qua 6 đợt tấn công. Ông bị bắt và hy sinh ngày 26/2/1285, để lại câu nói: “Ta thà làm ma nước Nam, chứ không thèm làm vương đất Bắc.”","Quân Trần lui về Thiên Trường, Trường Yên rồi vào Thanh Hóa củng cố lực lượng. Quân Nguyên chiếm được đất nhưng thiếu lương, bệnh tật, sa lầy giữa mùa hè."],"sources":["w2"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
