    ($hq$s06-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$“Ta thà làm ma nước Nam, chứ không thèm làm vương đất Bắc” là câu nói của ai?$hq$, $hq${"options":[{"id":"a","text":"Trần Bình Trọng"},{"id":"b","text":"Trần Quốc Toản"},{"id":"c","text":"Trần Thủ Độ"},{"id":"d","text":"Trần Khánh Dư"}],"correct":"a"}$hq$::jsonb, $hq$Trần Bình Trọng nói câu này khi bị giặc bắt và dụ hàng sau trận Đà Mạc.$hq$, $hq$w2$hq$),
    ($hq$s06-t1$hq$, 2, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là Quốc công Tiết chế, em chọn cách nào?$hq$, $hq${"situation":"Đại quân Nguyên rất đông và mạnh, đang tiến thẳng về Thăng Long. Chúng muốn đánh một trận lớn để kết thúc nhanh.","options":[{"id":"a","text":"Dàn toàn bộ quân quyết chiến giữ Thăng Long.","feedback":"Đó chính là điều giặc muốn. Đối đầu trực diện lúc giặc đang mạnh nhất có thể mất cả chủ lực.","score":0},{"id":"b","text":"Cản giặc đủ lâu để sơ tán, rồi rời kinh thành, không để lại lương thực.","feedback":"Đúng với chủ trương của Trần Quốc Tuấn: lui binh, “vườn không nhà trống”, chờ giặc suy yếu.","score":2},{"id":"c","text":"Xin hàng để giữ cho kinh thành khỏi bị tàn phá.","feedback":"Triều đình đã ra lệnh: sức không địch nổi thì lánh vào rừng núi, không được đầu hàng.","score":0}]}$hq$::jsonb, $hq$Rút lui chiến lược giúp bảo toàn lực lượng và đánh vào điểm yếu hậu cần của một đạo quân muốn đánh nhanh.$hq$, $hq$w2$hq$),
    ($hq$s06-s1$hq$, 3, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Quân Nguyên tới bờ sông Hồng trước Thăng Long","when":"17/2/1285"},{"id":"m2","text":"Quân Trần rời Thăng Long, xuôi sông Hồng","when":"18/2/1285"},{"id":"m3","text":"Trần Bình Trọng chặn giặc ở Đà Mạc","when":"Cuối tháng 2/1285"},{"id":"m4","text":"Quân Trần lui về Thiên Trường, Trường Yên"}]}$hq$::jsonb, $hq$Cản giặc để sơ tán, rời kinh thành, chặn hậu ở Đà Mạc, rồi tập hợp lại lực lượng ở Thiên Trường – Trường Yên.$hq$, $hq$w2$hq$),
    ($hq$s06-p1$hq$, 4, $hq$pairs$hq$, $hq$practice$hq$, $hq$o2$hq$, $hq$Lật thẻ và ghép cho đúng.$hq$, $hq${"left_label":"Tên","right_label":"Gắn với","pairs":[{"id":"p1","left":"Trần Bình Trọng","right":"Chặn giặc ở bãi Đà Mạc"},{"id":"p2","left":"Quân Thánh Dực","right":"Khoảng 600 người kìm chân giặc"},{"id":"p3","left":"Thăng Long","right":"Giặc vào chỉ thấy cung thất trống không"},{"id":"p4","left":"Thiên Trường","right":"Nơi quân Trần lui về tập hợp"}]}$hq$::jsonb, $hq$Quân Thánh Dực của Trần Bình Trọng chặn giặc ở Đà Mạc; triều đình rời Thăng Long về Thiên Trường.$hq$, $hq$w2$hq$),
    ($hq$s06-l1$hq$, 5, $hq$locate$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Sau khi rời Thăng Long, quân Trần lui về Thiên Trường. Hãy chọn Thiên Trường trên bản đồ.$hq$, $hq${"campaign_no":2,"spots":[{"id":"s1","label":"Vạn Kiếp","x":0.478,"y":0.233},{"id":"s2","label":"Thăng Long","x":0.362,"y":0.272},{"id":"s3","label":"Thiên Trường","x":0.385,"y":0.385},{"id":"s4","label":"Nội Bàng","x":0.545,"y":0.207}],"correct":"s3"}$hq$::jsonb, $hq$Thiên Trường (Nam Định ngày nay) nằm ở hạ lưu sông Hồng, phía nam Thăng Long.$hq$, $hq$w2$hq$),
    ($hq$s06-q2$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Vì sao quân Nguyên suy yếu dần dù chiếm được Thăng Long?$hq$, $hq${"options":[{"id":"a","text":"Vì thiếu lương, bệnh tật, không hợp thủy thổ"},{"id":"b","text":"Vì bị quân Tống đánh sau lưng"},{"id":"c","text":"Vì vua Nguyên ra lệnh rút quân"},{"id":"d","text":"Vì thuyền bị bão đánh chìm"}],"correct":"a"}$hq$::jsonb, $hq$“Vườn không nhà trống” làm giặc thiếu lương; mùa hè nóng bức, mưa lớn khiến chúng phát sinh bệnh tật.$hq$, $hq$w2$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$rut-lui-1285$hq$
