-- ---------------------------------------------------------------------- chặng 7: Hàm Tử (Tháng 5/1285)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$ham-tu$hq$, 2, 7, $hq$Hàm Tử$hq$, $hq$Cửa Hàm Tử (Hưng Yên)$hq$, $hq$Tháng 5/1285$hq$, $hq$battle$hq$, $hq$swords$hq$, $hq$Mở đầu cuộc tổng phản công: Trần Nhật Duật đánh thắng ở Hàm Tử; trong quân có tướng Triệu Trung và những người Tống cũ.$hq$, 0.64, 0.4, 0.422, 0.32, $hq$rut-lui-1285$hq$, 70, 120, 40, $hq$tran-nhat-duat$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Thuật lại được trận Hàm Tử và vai trò của Trần Nhật Duật."},{"id":"o2","text":"Giải thích được vì sao quân Trần chọn mùa hè năm 1285 để phản công."}],"cards":[{"id":"c1","kind":"why","title":"Thời cơ phản công","body":"Sau mấy tháng chiếm đóng, quân Nguyên không hợp thủy thổ, gặp mùa hè nóng bức và mưa lớn, phát sinh bệnh tật, lại thiếu lương. Nắm được tình hình, từ Thanh Hóa vua Trần đưa quân trở ra bắc, đánh vào các vị trí của giặc dọc sông Hồng.","facts":[{"label":"Giặc","value":"Thiếu lương, bệnh tật"},{"label":"Mục tiêu","value":"Tiến về Thăng Long"}],"objective":"o2","source":"w2","art":"sun"},{"id":"c2","kind":"who","title":"Trần Nhật Duật","body":"Chiêu Văn vương Trần Nhật Duật, con trai thứ sáu của vua Trần Thái Tông, được cử làm chánh tướng đánh giặc ở Hàm Tử. Sử cũ chép trận này vào tháng 4 âm lịch, khoảng tháng 5/1285.","facts":[{"label":"Tước hiệu","value":"Chiêu Văn vương"}],"objective":"o1","source":"w2","art":"general"},{"id":"c3","kind":"how","title":"Lá cờ nhà Tống","body":"Trong quân Trần Nhật Duật có tướng Triệu Trung, người Tống cũ sang theo Đại Việt. Thấy cờ hiệu và áo quân Tống, quân Nguyên lo lắng tưởng nhà Tống đã khôi phục, sang giúp Đại Việt. Quân Trần còn bắn tên gắn giấy nói chỉ đánh người Thát, khiến nhiều lính người Hoa trong quân Nguyên không tận lực.","facts":[{"label":"Tướng người Tống","value":"Triệu Trung"}],"objective":"o1","source":"w2","art":"flag"},{"id":"c4","kind":"where","title":"Hàm Tử trên sông Hồng","body":"Hàm Tử là cửa ải trên khúc sông Hồng chảy qua vùng Khoái Châu (Hưng Yên). Chiếm được vùng này, quân Trần có bàn đạp tiến đánh Thăng Long. Sử liệu chép khác nhau về các tướng cùng dự trận, nhưng đều ghi vai trò của Trần Nhật Duật và Triệu Trung.","facts":[{"label":"Vị trí","value":"Khúc sông Hồng qua Khoái Châu"}],"objective":"o1","source":"w2","art":"river"}],"sources":[{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."}],"explore":{"scene":"riverside","title":"Bến thuyền gần cửa Hàm Tử","intro":"Thủy quân của Chiêu Văn vương đã áp sát cửa Hàm Tử. Em giúp chuẩn bị cho đội quân của tướng Triệu Trung.","grid":["TTTTTTTTTTTTTTTTTTTTTT","T....h....==.....h...T","T.........==.........T","T..f......==......c..T","T====================T","T.........==.........T","T...T.....==...D.....T","T.........==.........T","::::::::::++::::::::::","~~~~b~~~~~++~~~~~b~~~~","~~~~~~~~~~++~~~~~~~~~~","~~~~~~~b~~~~~~b~~~~~~~","~~~~~~~~~~~~~~~~~~~~~~"],"spawn":[10,1],"npcs":[{"id":"nhatduat","name":"Trần Nhật Duật","role":"Chiêu Văn vương, chánh tướng","sprite":"commander","at":[8,6],"idle":"Đánh giặc phải đánh cả vào lòng giặc.","fictional":false},{"id":"trieutrung","name":"Triệu Trung","role":"Tướng người Tống theo Đại Việt","sprite":"general","at":[14,7],"idle":"Nước Tống của ta đã mất về tay giặc Nguyên.","fictional":false},{"id":"tong","name":"Người lính áo Tống","role":"Quân của Triệu Trung","sprite":"soldier","at":[16,5],"idle":"Chúng tôi xin đi đầu trận tuyến.","fictional":true},{"id":"scout","name":"Lính trinh sát","role":"Dò tình hình giặc","sprite":"scout","at":[3,2],"idle":"Giặc đóng thuyền kín cả cửa Hàm Tử.","fictional":true},{"id":"oarsman","name":"Anh lính chèo","role":"Thủy binh","sprite":"soldier","at":[6,7],"idle":"Chèo ngược sông Hồng mùa này nặng tay lắm.","fictional":true}],"items":[{"id":"songflag","name":"Cờ hiệu nhà Tống","sprite":"flag","at":[17,2]}],"zones":[{"id":"dock","name":"Cầu thuyền ra sông","rect":[10,9,2,2],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Gặp Chiêu Văn vương Trần Nhật Duật ở bến để nghe kế đánh.","clue":"Kế của Trần Nhật Duật: cho quân Triệu Trung mặc áo Tống, dựng cờ Tống, đi đầu trận để giặc hoang mang.","type":"talk","npc":"nhatduat","lines":["Giặc đóng thuyền ở cửa Hàm Tử. Trong quân ta có tướng Triệu Trung và những người Tống cũ.","Ta cho họ mặc áo Tống, dựng cờ Tống, cầm cung tên đi đầu. Giặc trông thấy ắt hoang mang."]},{"id":"s2","goal":"Lấy lá cờ hiệu nhà Tống để gần đống bao lương phía đông bắc.","type":"pickup","item":"songflag"},{"id":"s3","goal":"Trao lá cờ cho tướng Triệu Trung.","type":"give","npc":"trieutrung","item":"songflag","lines":["Đa tạ. Nay theo Chiêu Văn vương, anh em ta xin đi đầu đánh giặc Nguyên."]},{"id":"s4","goal":"Trả lời câu hỏi của tướng Triệu Trung.","type":"ask","npc":"trieutrung","prompt":"Em có biết vì sao Chiêu Văn vương cho chúng ta mặc áo Tống đi đầu không?","options":[{"id":"a","text":"Vì áo Tống bền hơn áo quân Trần."},{"id":"b","text":"Để giặc tưởng nhà Tống đã khôi phục, sang giúp Đại Việt mà hoang mang."},{"id":"c","text":"Để quân ta khỏi bắn nhầm nhau."}],"correct":"b","right":"Đúng vậy. Trong quân Nguyên có nhiều người Hoa, thấy cờ Tống là rối lòng.","wrong":"Chưa phải. Em nhớ lại lời Chiêu Văn vương xem."},{"id":"s5","goal":"Ra cầu thuyền, theo thủy quân tiến vào cửa Hàm Tử.","type":"battle","zone":"dock"},{"id":"s6","goal":"Trở lại bến gặp Chiêu Văn vương.","type":"talk","npc":"nhatduat","lines":["Thắng rồi! Phải cho người về báo tin thắng trận ngay.","Trận này mở đường cho ta tiến về Thăng Long."]}]},"battle":{"mode":"tactics","title":"Trận Hàm Tử","intro":"Thủy quân hai bên giáp nhau ở cửa Hàm Tử. Quân của Triệu Trung mặc áo Tống đi đầu. Hãy đánh tan đội thuyền giặc.","allies":[{"id":"nhatduat","name":"Thuyền Trần Nhật Duật","cls":"thuyen","row":"front","hp":18,"atk":6,"def":2,"spd":5,"ranged":true,"skill":{"id":"skill","name":"Trống trận","text":"Cả đội tăng sát thương trong 2 vòng.","cost":2,"cooldown":3,"kind":"rally","turns":2},"tags":[],"sprite":"thuyen"},{"id":"trieutrung","name":"Quân Triệu Trung","cls":"cung","row":"back","hp":15,"atk":6,"def":1,"spd":7,"skill":{"id":"skill","name":"Loạt tên áo Tống","text":"Bắn cả một hàng quân địch.","cost":3,"cooldown":3,"kind":"volley","power":0.9},"tags":[],"sprite":"cung"},{"id":"thuyquan","name":"Thủy quân nhà Trần","cls":"thuyen","row":"front","hp":16,"atk":5,"def":2,"spd":4,"ranged":true,"skill":{"id":"skill","name":"Đâm mạn thuyền","text":"Đòn mạnh vào một đơn vị ở bất kỳ hàng nào.","cost":2,"cooldown":2,"kind":"strike","power":1.5,"ranged":true},"tags":[],"sprite":"thuyen"}],"enemies":[{"id":"ethuyen1","name":"Chiến thuyền Nguyên","cls":"thuyen","row":"front","hp":22,"atk":6,"def":2,"spd":5,"ranged":true,"skill":{"id":"skill","name":"Bắn đá","text":"Đòn mạnh vào một đơn vị.","cost":2,"cooldown":2,"kind":"strike","power":1.5,"ranged":true},"tags":[],"sprite":"e_thuyen"},{"id":"ethuyen2","name":"Chiến thuyền Nguyên","cls":"thuyen","row":"front","hp":20,"atk":5,"def":2,"spd":6,"ranged":true,"skill":null,"tags":[],"sprite":"e_thuyen"},{"id":"ebo","name":"Lính Nguyên","cls":"bo","row":"front","hp":18,"atk":5,"def":1,"spd":6,"skill":null,"tags":[],"sprite":"e_bo"}],"supply":{"ally":3,"enemy":3,"regen":2,"enemy_regen":2,"per_supply_unit":0},"objective":{"type":"eliminate"},"objective_text":"Đánh tan đội thuyền giặc ở cửa Hàm Tử trong 8 vòng.","protect":null,"max_rounds":8,"hunger":null,"stratagem":{"name":"Cờ hiệu nhà Tống","text":"Dùng một lần: quân địch hoang mang, đánh yếu đi. Trả lời đúng thì hiệu lực dài gấp đôi.","prompt":"Vì sao quân Nguyên lo sợ khi thấy đội quân của Triệu Trung?","options":[{"id":"a","text":"Vì tưởng nhà Tống đã khôi phục, sang giúp Đại Việt."},{"id":"b","text":"Vì đội quân ấy đông gấp mười lần."},{"id":"c","text":"Vì đội quân ấy có voi chiến."}],"correct":"a","explain":"Thấy cờ hiệu Tống của Triệu Trung, quân Nguyên tưởng nhà Tống đã khôi phục sang giúp Đại Việt nên hoang mang.","effect":{"type":"weaken_all","turns":2}},"tips":["Cung thủ và thuyền bắn được cả hàng sau.","Dùng mưu kế “Cờ hiệu nhà Tống” khi địch còn đông để giảm sát thương của cả đội hình.","Tập trung đánh từng thuyền một."],"win_text":"Quân Nguyên thua to ở Hàm Tử. Tin thắng trận được báo ngay về cho vua.","lose_text":"Chưa thắng được đội thuyền giặc. Hãy dùng mưu kế sớm và tập trung hỏa lực vào một mục tiêu."},"debrief":{"title":"Hàm Tử mở đầu cuộc phản công","paragraphs":["Sau mấy tháng, quân Nguyên suy yếu vì thiếu lương, bệnh tật và thời tiết mùa hè. Từ Thanh Hóa, vua Trần đưa quân trở ra bắc, đánh vào các vị trí của giặc trên khúc sông Hồng chảy qua Khoái Châu.","Tại cửa Hàm Tử, Chiêu Văn vương Trần Nhật Duật chỉ huy đánh thắng quân Nguyên. Trong quân ông có tướng Triệu Trung và những người Tống cũ; thấy cờ hiệu Tống, quân Nguyên tưởng nhà Tống đã khôi phục sang giúp Đại Việt. Quân Trần còn dùng kế ly gián bằng thư buộc vào mũi tên.","Sử liệu chép khác nhau về các tướng cùng dự trận và về việc tướng Nguyên nào chỉ huy ở Hàm Tử, nên trò chơi không gọi tên chỉ huy phía địch. Sau trận này, Trần Nhật Duật cho người về báo tin thắng trận."],"sources":["w2"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s07-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Ai chỉ huy quân Trần trong trận Hàm Tử?$hq$, $hq${"options":[{"id":"a","text":"Chiêu Văn vương Trần Nhật Duật"},{"id":"b","text":"Thượng tướng Trần Quang Khải"},{"id":"c","text":"Trần Bình Trọng"},{"id":"d","text":"Trần Khánh Dư"}],"correct":"a"}$hq$::jsonb, $hq$Trần Nhật Duật làm chánh tướng đánh giặc ở Hàm Tử; Trần Quang Khải chỉ huy trận Chương Dương sau đó.$hq$, $hq$w2$hq$),
    ($hq$s07-t1$hq$, 2, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em là người cầm quân, em chọn cách nào?$hq$, $hq${"situation":"Giữa mùa hè, tin báo: quân Nguyên ốm đau nhiều, lương sắp cạn, đóng rải rác dọc sông Hồng. Quân ta đã củng cố xong ở Thanh Hóa.","options":[{"id":"a","text":"Tiếp tục ở yên trong Thanh Hóa cho an toàn.","feedback":"Bỏ lỡ lúc giặc yếu nhất thì chúng có thể được tiếp viện và hồi sức.","score":0},{"id":"b","text":"Đưa quân ra bắc, đánh các vị trí của giặc trên sông Hồng.","feedback":"Đúng như vua Trần đã làm: phản công khi giặc suy yếu, lấy sông Hồng làm hướng tiến về Thăng Long.","score":2},{"id":"c","text":"Đánh thẳng vào Thăng Long ngay, bỏ qua các đồn dọc sông.","feedback":"Hướng tới Thăng Long là đúng, nhưng phải diệt các vị trí dọc sông trước để khỏi bị đánh từ phía sau.","score":1}]}$hq$::jsonb, $hq$Quân Trần phản công đúng lúc giặc thiếu lương và bệnh tật, đánh lần lượt các vị trí trên sông Hồng rồi mới tiến vào Thăng Long.$hq$, $hq$w2$hq$),
    ($hq$s07-p1$hq$, 3, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép cho đúng.$hq$, $hq${"left_label":"Tên","right_label":"Gắn với","pairs":[{"id":"p1","left":"Trần Nhật Duật","right":"Chánh tướng trận Hàm Tử"},{"id":"p2","left":"Triệu Trung","right":"Tướng người Tống theo Đại Việt"},{"id":"p3","left":"Cờ hiệu nhà Tống","right":"Làm quân Nguyên hoang mang"},{"id":"p4","left":"Thư buộc mũi tên","right":"Kế ly gián lính người Hoa"}]}$hq$::jsonb, $hq$Trận Hàm Tử nổi bật ở cách đánh vào tinh thần của quân Nguyên.$hq$, $hq$w2$hq$),
    ($hq$s07-l1$hq$, 4, $hq$locate$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Trận Hàm Tử diễn ra trên khúc sông Hồng phía nam Thăng Long. Trong các điểm sau, điểm nào là vùng Hàm Tử – Chương Dương – Tây Kết?$hq$, $hq${"campaign_no":2,"spots":[{"id":"s1","label":"Vạn Kiếp","x":0.478,"y":0.233},{"id":"s2","label":"Vùng Hàm Tử","x":0.425,"y":0.318},{"id":"s3","label":"Nội Bàng","x":0.545,"y":0.207},{"id":"s4","label":"Thu Vật","x":0.175,"y":0.168}],"correct":"s2"}$hq$::jsonb, $hq$Hàm Tử, Chương Dương, Tây Kết nằm sát nhau trên khúc sông Hồng phía đông nam Thăng Long.$hq$, $hq$w2$hq$),
    ($hq$s07-q2$hq$, 5, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Điều gì KHÔNG phải là khó khăn của quân Nguyên giữa năm 1285?$hq$, $hq${"options":[{"id":"a","text":"Bị quân Tống đánh vào kinh đô"},{"id":"b","text":"Thiếu lương thực"},{"id":"c","text":"Bệnh tật vì không hợp thủy thổ"},{"id":"d","text":"Mùa hè nóng bức, mưa lớn"}],"correct":"a"}$hq$::jsonb, $hq$Nhà Tống khi ấy đã mất. Quân Nguyên khốn đốn vì thiếu lương, bệnh tật và thời tiết.$hq$, $hq$w2$hq$),
    ($hq$s07-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Vì sao quân Nguyên hoang mang khi thấy quân của Triệu Trung?$hq$, $hq${"options":[{"id":"a","text":"Tưởng nhà Tống đã khôi phục, sang giúp Đại Việt"},{"id":"b","text":"Tưởng vua Nguyên gửi quân sang thay"},{"id":"c","text":"Vì quân của Triệu Trung cưỡi voi"},{"id":"d","text":"Vì họ dùng súng thần công"}],"correct":"a"}$hq$::jsonb, $hq$Quân của Triệu Trung mặc sắc phục, dựng cờ hiệu nhà Tống nên quân Nguyên tưởng nhà Tống đã khôi phục.$hq$, $hq$w2$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$ham-tu$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 8: Chương Dương (Tháng 6/1285)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$chuong-duong$hq$, 2, 8, $hq$Chương Dương$hq$, $hq$Bến Chương Dương (Thường Tín)$hq$, $hq$Tháng 6/1285$hq$, $hq$battle$hq$, $hq$flame$hq$, $hq$Trần Quang Khải cùng Phạm Ngũ Lão, Trần Quốc Toản đánh tan thủy quân Nguyên ở bến Chương Dương rồi giải phóng Thăng Long.$hq$, 0.7, 0.27, 0.39, 0.305, $hq$ham-tu$hq$, 70, 120, 40, $hq$tran-quang-khai$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Thuật lại được trận Chương Dương và việc giải phóng Thăng Long năm 1285."},{"id":"o2","text":"Biết bài thơ “Tụng giá hoàn kinh sư” (Phò giá về kinh) của Trần Quang Khải gắn với chiến thắng này."}],"cards":[{"id":"c1","kind":"who","title":"Ba vị tướng","body":"Sau thắng lợi Hàm Tử, Trần Quốc Tuấn bàn với vua đem toàn quân ra bắc lấy lại Thăng Long. Thượng tướng Trần Quang Khải làm chánh tướng; Phạm Ngũ Lão và Trần Quốc Toản làm phó tướng.","facts":[{"label":"Chánh tướng","value":"Trần Quang Khải"},{"label":"Phó tướng","value":"Phạm Ngũ Lão, Trần Quốc Toản"}],"objective":"o1","source":"w2","art":"general"},{"id":"c2","kind":"how","title":"Đánh vào bến thuyền","body":"Đại quân Thoát Hoan ở Thăng Long sắp cạn lương, chiến thuyền đậu ở bến Chương Dương. Quân Nguyên quen thấy quân Trần thua, nay bị đánh mạnh nên bất ngờ, tan tác bỏ chạy. Phần lớn chiến thuyền của giặc bị quân Trần đốt cháy hoặc chiếm.","facts":[{"label":"Nơi","value":"Bến Chương Dương (Thường Tín)"}],"objective":"o1","source":"w2","art":"boat"},{"id":"c3","kind":"how","title":"Giải phóng Thăng Long","body":"Thừa thắng, quân Trần vây đánh Thăng Long, có cả dân binh các địa phương lân cận tham gia. Trước sức tấn công bền bỉ, quân Nguyên phải bỏ thành, chạy sang bờ bắc sông Hồng rồi rút về phía bắc.","facts":[{"label":"Kết quả","value":"Kinh thành được giải phóng"}],"objective":"o1","source":"w2","art":"palace"},{"id":"c4","kind":"who","title":"Phò giá về kinh","body":"Mừng chiến thắng, Trần Quang Khải viết bài thơ “Tụng giá hoàn kinh sư”: “Đoạt sáo Chương Dương độ, / Cầm Hồ Hàm Tử quan…” (Chương Dương cướp giáo giặc, Hàm Tử bắt quân thù). Bài thơ nhắc người đời sau: thái bình rồi vẫn phải gắng sức giữ nước.","facts":[{"label":"Tác giả","value":"Trần Quang Khải"}],"objective":"o2","source":"w2","art":"scroll"}],"sources":[{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."}],"explore":{"scene":"riverside","title":"Bến tập kết trước trận Chương Dương","intro":"Quân của Thượng tướng Trần Quang Khải đã ngược sông Hồng tới gần Chương Dương. Em giúp chuẩn bị trận đánh vào bến thuyền giặc.","grid":["TTTTTTTTTTTTTTTTTTTTTT","T....h....==.....h...T","T.........==.........T","T..f......==......c..T","T====================T","T.........==.........T","T...T.....==...D.....T","T.........==.........T","::::::::::++::::::::::","~~~~b~~~~~++~~~~~b~~~~","~~~~~~~~~~++~~~~~~~~~~","~~~~~~~b~~~~~~b~~~~~~~","~~~~~~~~~~~~~~~~~~~~~~"],"spawn":[10,1],"npcs":[{"id":"quangkhai","name":"Trần Quang Khải","role":"Thượng tướng, chánh tướng","sprite":"commander","at":[8,6],"idle":"Lấy lại kinh thành là việc của hôm nay.","fictional":false},{"id":"ngulao","name":"Phạm Ngũ Lão","role":"Phó tướng","sprite":"general","at":[13,5],"idle":"Quân ta đã sẵn sàng.","fictional":false},{"id":"quoctoan","name":"Trần Quốc Toản","role":"Phó tướng, Hoài Văn hầu","sprite":"youth","at":[16,7],"idle":"Lá cờ sáu chữ của ta đã dựng lên rồi!","fictional":false},{"id":"scout","name":"Lính trinh sát","role":"Vừa dò bến Chương Dương","sprite":"scout","at":[17,2],"idle":"Tôi vừa ở bến Chương Dương về.","fictional":true},{"id":"oarsman","name":"Anh lính chèo","role":"Thủy binh","sprite":"soldier","at":[5,7],"idle":"Thuyền ta nhẹ, áp mạn thuyền giặc rất nhanh.","fictional":true}],"items":[{"id":"torch","name":"Bó đuốc","sprite":"torch","at":[4,3]}],"zones":[{"id":"dock","name":"Cầu thuyền ra sông","rect":[10,9,2,2],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Gặp Thượng tướng Trần Quang Khải ở bến.","clue":"Kế đánh: đánh thẳng vào bến Chương Dương, đốt và đoạt chiến thuyền của giặc.","type":"talk","npc":"quangkhai","lines":["Chiến thuyền của giặc đậu cả ở bến Chương Dương. Chúng ở Thăng Long đã lâu, lương sắp cạn.","Ta đánh thẳng vào bến, đốt và đoạt thuyền. Mất thuyền, chúng không giữ nổi kinh thành."]},{"id":"s2","goal":"Tìm người trinh sát vừa dò bến Chương Dương về: anh đứng gần đống bao lương phía đông bắc.","type":"find","npc":"scout","lines":["Giặc quen thấy quân ta thua nên canh phòng rất lơ là. Đánh mạnh lúc này là chúng không kịp trở tay."],"wrong":"Tôi không đi trinh sát. Anh ấy đứng gần đống bao lương phía đông bắc."},{"id":"s3","goal":"Báo lại với phó tướng Phạm Ngũ Lão.","type":"ask","npc":"ngulao","prompt":"Phó tướng hỏi: mục tiêu chính của trận này là gì?","options":[{"id":"a","text":"Chiến thuyền của giặc ở bến Chương Dương."},{"id":"b","text":"Kho lương của giặc ở Vạn Kiếp."},{"id":"c","text":"Đoàn thuyền lương ở Vân Đồn."}],"correct":"a","right":"Đúng. Đánh vào thuyền là chặt chân của chúng.","wrong":"Không phải. Em nhớ lại lời Thượng tướng xem."},{"id":"s4","goal":"Lấy bó đuốc ở phía tây bắc bến.","type":"pickup","item":"torch"},{"id":"s5","goal":"Mang đuốc cho phó tướng Trần Quốc Toản, người đứng gần chiếc trống.","type":"give","npc":"quoctoan","item":"torch","lines":["Có lửa rồi! Đội quân cờ sáu chữ của ta xin đi đầu."]},{"id":"s6","goal":"Ra cầu thuyền, theo đại quân đánh vào bến Chương Dương.","type":"battle","zone":"dock"},{"id":"s7","goal":"Trở lại gặp Thượng tướng Trần Quang Khải.","type":"talk","npc":"quangkhai","lines":["Giặc tan rồi, kinh thành sắp về tay ta.","“Đoạt sáo Chương Dương độ, Cầm Hồ Hàm Tử quan…” Ta sẽ chép lại mấy câu này."]}]},"battle":{"mode":"tactics","title":"Trận Chương Dương","intro":"Chiến thuyền giặc đậu ở bến, lính canh giữ phía trước. Mục tiêu là phá các chiến thuyền trước khi giặc kịp cho thuyền rời bến.","allies":[{"id":"quangkhai","name":"Thuyền Trần Quang Khải","cls":"thuyen","row":"front","hp":18,"atk":6,"def":2,"spd":5,"ranged":true,"skill":{"id":"skill","name":"Áp mạn đoạt thuyền","text":"Đòn mạnh vào một đơn vị ở bất kỳ hàng nào.","cost":2,"cooldown":2,"kind":"strike","power":1.6,"ranged":true},"tags":[],"sprite":"thuyen"},{"id":"ngulao","name":"Quân Phạm Ngũ Lão","cls":"bo","row":"front","hp":16,"atk":6,"def":2,"spd":6,"skill":{"id":"skill","name":"Giáo dài","text":"Đòn mạnh; bộ binh cầm giáo khắc chế kỵ binh.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"bo"},{"id":"quoctoan","name":"Quân Trần Quốc Toản","cls":"bo","row":"front","hp":16,"atk":5,"def":2,"spd":7,"skill":{"id":"skill","name":"Cờ sáu chữ","text":"Cả đội tăng sát thương trong 2 vòng.","cost":2,"cooldown":3,"kind":"rally","turns":2},"tags":[],"sprite":"bo"}],"enemies":[{"id":"thuyen1","name":"Chiến thuyền ở bến","cls":"thuyen","row":"back","hp":18,"atk":4,"def":1,"spd":3,"ranged":true,"skill":null,"tags":["ship"],"sprite":"e_thuyen"},{"id":"thuyen2","name":"Chiến thuyền ở bến","cls":"thuyen","row":"back","hp":18,"atk":4,"def":1,"spd":2,"ranged":true,"skill":null,"tags":["ship"],"sprite":"e_thuyen"},{"id":"canh1","name":"Lính canh bến","cls":"bo","row":"front","hp":14,"atk":5,"def":1,"spd":5,"skill":null,"tags":[],"sprite":"e_bo"},{"id":"canh2","name":"Kỵ binh Nguyên","cls":"ky","row":"front","hp":14,"atk":5,"def":1,"spd":8,"skill":null,"tags":[],"sprite":"e_ky"}],"supply":{"ally":3,"enemy":2,"regen":2,"enemy_regen":1,"per_supply_unit":0},"objective":{"type":"destroy","tag":"ship","need":2,"rounds":6},"objective_text":"Phá cả 2 chiến thuyền ở bến trong 6 vòng.","protect":null,"max_rounds":6,"hunger":null,"stratagem":{"name":"Hỏa công","text":"Dùng một lần: các chiến thuyền địch bốc cháy, mất máu mỗi vòng. Trả lời đúng thì cháy lâu gấp đôi.","prompt":"Vì sao quân Nguyên ở Chương Dương bị bất ngờ?","options":[{"id":"a","text":"Vì chúng quen thấy quân Trần thua, không ngờ bị đánh mạnh."},{"id":"b","text":"Vì đêm ấy có bão lớn."},{"id":"c","text":"Vì chúng đang rút quân về nước."}],"correct":"a","explain":"Quân Nguyên thường thấy quân Trần thua, nay thấy quân Trần đánh mạnh nên bị bất ngờ, tan tác bỏ chạy.","effect":{"type":"burn_tag","turns":2,"tag":"ship"}},"tips":["Chiến thuyền địch ở hàng sau: chỉ thuyền của ta (bắn xa) mới với tới khi hàng trước của địch còn người.","Bộ binh cầm giáo khắc chế kỵ binh: hạ lính canh để mở đường.","Hỏa công đốt cả hai chiến thuyền cùng lúc."],"win_text":"Phần lớn chiến thuyền của giặc bị đốt cháy hoặc bị chiếm. Quân Trần thừa thắng tiến về Thăng Long.","lose_text":"Chiến thuyền giặc kịp rời bến. Hãy dùng hỏa công và dồn sức của thuyền ta vào các chiến thuyền."},"debrief":{"title":"Chương Dương và ngày về kinh","paragraphs":["Sau trận Hàm Tử, Trần Quốc Tuấn bàn với vua Trần Nhân Tông đem toàn quân ra bắc. Trần Quang Khải làm chánh tướng, Phạm Ngũ Lão và Trần Quốc Toản làm phó tướng, tiến đánh bến Chương Dương (thuộc Thường Tín), nơi chiến thuyền của Thoát Hoan đang đậu.","Quân Nguyên quen thấy quân Trần thua nên bị bất ngờ, tan tác bỏ chạy; phần lớn chiến thuyền bị đốt cháy hoặc bị chiếm. Quân Trần cùng dân binh các địa phương vây đánh Thăng Long, buộc quân Nguyên bỏ thành chạy sang bờ bắc sông Hồng.","Mừng chiến thắng, Trần Quang Khải viết bài thơ “Tụng giá hoàn kinh sư” (Phò giá về kinh). Em đã mở được bài thơ này trong Kho tư liệu."],"sources":["w2"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s08-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Ai làm chánh tướng trong trận Chương Dương?$hq$, $hq${"options":[{"id":"a","text":"Trần Quang Khải"},{"id":"b","text":"Trần Nhật Duật"},{"id":"c","text":"Trần Khánh Dư"},{"id":"d","text":"Lê Phụ Trần"}],"correct":"a"}$hq$::jsonb, $hq$Thượng tướng Trần Quang Khải làm chánh tướng; Phạm Ngũ Lão và Trần Quốc Toản làm phó tướng.$hq$, $hq$w2$hq$),
    ($hq$s08-q2$hq$, 2, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Hai câu “Đoạt sáo Chương Dương độ, / Cầm Hồ Hàm Tử quan” nhắc tới hai chiến thắng nào?$hq$, $hq${"options":[{"id":"a","text":"Chương Dương và Hàm Tử"},{"id":"b","text":"Bình Lệ Nguyên và Đông Bộ Đầu"},{"id":"c","text":"Vân Đồn và Bạch Đằng"},{"id":"d","text":"Tây Kết và Vạn Kiếp"}],"correct":"a"}$hq$::jsonb, $hq$Bài “Tụng giá hoàn kinh sư” của Trần Quang Khải nhắc hai chiến thắng Chương Dương và Hàm Tử năm 1285.$hq$, $hq$w2$hq$),
    ($hq$s08-s1$hq$, 3, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc của cuộc phản công năm 1285 theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Trận Hàm Tử","when":"Tháng 5/1285"},{"id":"m2","text":"Trận Chương Dương","when":"Tháng 6/1285"},{"id":"m3","text":"Quân Nguyên bỏ Thăng Long","when":"Tháng 6/1285"},{"id":"m4","text":"Trận Tây Kết","when":"24/6/1285"}]}$hq$::jsonb, $hq$Hàm Tử mở đầu, Chương Dương và giải phóng Thăng Long tiếp theo, Tây Kết diệt đạo quân Toa Đô sau cùng.$hq$, $hq$w2$hq$),
    ($hq$s08-p1$hq$, 4, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi vị tướng với vai trò trong trận Chương Dương.$hq$, $hq${"left_label":"Nhân vật","right_label":"Vai trò","pairs":[{"id":"p1","left":"Trần Quang Khải","right":"Chánh tướng"},{"id":"p2","left":"Phạm Ngũ Lão","right":"Phó tướng"},{"id":"p3","left":"Trần Quốc Toản","right":"Phó tướng, đội quân cờ sáu chữ"},{"id":"p4","left":"Thoát Hoan","right":"Chỉ huy đại quân Nguyên ở Thăng Long"}]}$hq$::jsonb, $hq$Trần Quang Khải chỉ huy, Phạm Ngũ Lão và Trần Quốc Toản làm phó tướng đánh vào bến thuyền của đại quân Thoát Hoan.$hq$, $hq$w2$hq$),
    ($hq$s08-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là chánh tướng, em chọn đánh vào đâu?$hq$, $hq${"situation":"Đại quân giặc đóng trong thành Thăng Long, lương sắp cạn. Chiến thuyền của chúng đậu ở bến Chương Dương, canh phòng lơ là.","options":[{"id":"a","text":"Vây thành Thăng Long ngay, mặc bến thuyền.","feedback":"Vây thành là việc phải làm, nhưng để nguyên thuyền thì giặc vẫn còn đường cơ động và tiếp tế.","score":1},{"id":"b","text":"Đánh bến Chương Dương, đốt và đoạt chiến thuyền trước.","feedback":"Đúng như quân Trần đã làm: mất thuyền, giặc không giữ nổi kinh thành.","score":2},{"id":"c","text":"Chờ giặc hết lương tự rút.","feedback":"Chờ đợi là bỏ lỡ lúc giặc đang bất ngờ; chúng có thể rút lui an toàn và giữ nguyên lực lượng.","score":0}]}$hq$::jsonb, $hq$Đánh vào thuyền bè là đánh vào khả năng cơ động của giặc, mở đường giải phóng Thăng Long.$hq$, $hq$w2$hq$),
    ($hq$s08-l1$hq$, 6, $hq$locate$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Sau khi bỏ Thăng Long, quân của Thoát Hoan rút chạy lên phía bắc qua Vạn Kiếp. Hãy chọn Vạn Kiếp trên bản đồ.$hq$, $hq${"campaign_no":2,"spots":[{"id":"s1","label":"Thăng Long","x":0.362,"y":0.272},{"id":"s2","label":"Vạn Kiếp","x":0.478,"y":0.233},{"id":"s3","label":"Thiên Trường","x":0.385,"y":0.385},{"id":"s4","label":"Thu Vật","x":0.175,"y":0.168}],"correct":"s2"}$hq$::jsonb, $hq$Vạn Kiếp nằm phía đông bắc Thăng Long, trên đường quân Nguyên rút về biên giới.$hq$, $hq$w2$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$chuong-duong$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 9: Tây Kết (24/6/1285)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$tay-ket$hq$, 2, 9, $hq$Tây Kết$hq$, $hq$Tây Kết (Khoái Châu)$hq$, $hq$24/6/1285$hq$, $hq$battle$hq$, $hq$target$hq$, $hq$Đạo quân Toa Đô bị cô lập và bị đánh tan ở Tây Kết; Thoát Hoan rút chạy về nước. Cuộc kháng chiến lần thứ hai thắng lợi.$hq$, 0.66, 0.54, 0.44, 0.331, $hq$chuong-duong$hq$, 70, 150, 50, $hq$tran-nhan-tong$hq$, $hq$saga-tay-ket$hq$,
     $hq${"objectives":[{"id":"o1","text":"Thuật lại được trận Tây Kết ngày 24/6/1285 và số phận đạo quân Toa Đô."},{"id":"o2","text":"Nêu được kết quả của cuộc kháng chiến lần thứ hai."}],"cards":[{"id":"c1","kind":"why","title":"Đạo quân bị cô lập","body":"Toa Đô là tướng Nguyên đem quân từ phía nam đánh ra, định hợp với Thoát Hoan. Khi Thoát Hoan đã thua và rút chạy, Toa Đô vẫn không hay biết, còn đóng quân chờ ở sông Thiên Mạc. Được ít ngày biết tin, Toa Đô lui về Tây Kết.","facts":[{"label":"Hai gọng kìm","value":"Thoát Hoan (bắc), Toa Đô (nam)"}],"objective":"o1","source":"w2","art":"map"},{"id":"c2","kind":"how","title":"Trận Tây Kết","body":"Ngày 24/6/1285, quân Trần tấn công Tây Kết. Tổng quản quân Nguyên là Trương Hiển đầu hàng và dẫn đường cho quân Trần. Quân Nguyên bị giết rất nhiều, Toa Đô tử trận; Ô Mã Nhi chạy thoát ra biển.","facts":[{"label":"Ngày","value":"24/6/1285"},{"label":"Kết cục","value":"Toa Đô tử trận"}],"objective":"o1","source":"w2","art":"swords"},{"id":"c3","kind":"how","title":"Thoát Hoan tháo chạy","body":"Trên đường rút về phía bắc, quân Thoát Hoan bị chặn đánh liên tiếp: ở sông Như Nguyệt, ở Vạn Kiếp (cầu phao đứt, nhiều lính chết đuối), ở Vĩnh Bình (tướng Lý Hằng trúng tên độc). Tương truyền Thoát Hoan phải chui vào ống đồng để trốn về nước.","facts":[{"label":"Lưu ý","value":"Chuyện ống đồng là “tương truyền”"}],"objective":"o2","source":"w2","art":"horse"},{"id":"c4","kind":"why","title":"Thắng lợi năm 1285","body":"Chuẩn bị từ sớm, cả nước đồng lòng, lui quân giữ sức và làm giặc thiếu lương, rồi phản công đúng lúc: cuộc kháng chiến lần thứ hai thắng lợi. Sử sách chép khác nhau về người trực tiếp chỉ huy trận Tây Kết, nhưng thống nhất về kết cục của Toa Đô.","facts":[{"label":"Kết quả","value":"Quân Nguyên bị đánh bật khỏi Đại Việt"}],"objective":"o2","source":"w2","art":"star"}],"sources":[{"key":"w2","title":"Chiến tranh Nguyên Mông – Đại Việt lần 2","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử; Hà Văn Tấn – Phạm Thị Tâm)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_2","note":"Một số chi tiết các nguồn chép khác nhau; nội dung chỉ dùng phần các nguồn thống nhất."}],"explore":{"scene":"camp","title":"Doanh trại trước trận Tây Kết","intro":"Tin báo liên tiếp gửi về: Thoát Hoan đã chạy, Toa Đô còn chưa biết. Em giúp viên tướng tiên phong chuẩn bị trận đánh.","grid":["TTTTTTTTTT==TTTTTTTTTT","T########.==.########T","T#h.h..f..==..f..h.h#T","T#........==........#T","T#..c.....==.....D..#T","T#==================#T","T#..F.....==........#T","T#........==...c.c..#T","T#.h...h..==........#T","T#........==..f.....#T","T########.==.########T","TTTTTTTTT.==.TTTTTTTTT",".........====........."],"spawn":[10,11],"npcs":[{"id":"general","name":"Viên tướng tiên phong","role":"Chỉ huy cánh quân","sprite":"general","at":[6,3],"idle":"Đánh trận này phải nhanh và trúng.","fictional":true},{"id":"truonghien","name":"Trương Hiển","role":"Tổng quản quân Nguyên vừa ra hàng","sprite":"enemy","at":[13,8],"idle":"Ta đã ra hàng, xin lập công.","fictional":false},{"id":"guard","name":"Lính gác cổng","role":"Canh cổng bắc","sprite":"soldier","at":[12,3],"idle":"Ngoài cổng bắc là đường tới Tây Kết.","fictional":true},{"id":"cook","name":"Hỏa đầu quân","role":"Lính nấu bếp","sprite":"villager","at":[5,6],"idle":"Giặc đói còn ta no, thế là hơn rồi.","fictional":true},{"id":"soldier","name":"Lính đưa tin","role":"Vừa từ Thăng Long tới","sprite":"scout","at":[15,3],"idle":"Thăng Long đã về tay ta!","fictional":true}],"items":[{"id":"sketch","name":"Sơ đồ trại giặc","sprite":"scroll","at":[15,8]}],"zones":[{"id":"front","name":"Đường tới Tây Kết","rect":[9,0,4,2],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Vào doanh trại gặp viên tướng tiên phong.","clue":"Thoát Hoan đã rút chạy mà Toa Đô không hay biết, nên đạo quân Toa Đô ở Tây Kết bị cô lập.","type":"talk","npc":"general","lines":["Thoát Hoan đã bỏ Thăng Long chạy về phía bắc.","Toa Đô không hề hay biết, còn đóng quân chờ ở sông Thiên Mạc rồi lui về Tây Kết. Đạo quân ấy nay đã cô lập."]},{"id":"s2","goal":"Tìm viên tổng quản quân Nguyên vừa ra hàng: ông đứng gần cột cờ phía đông nam doanh trại.","type":"find","npc":"truonghien","lines":["Ta là tổng quản Trương Hiển. Ta biết đường vào trại Toa Đô ở Tây Kết.","Sơ đồ trại ta để ngay cạnh đây, em mang về cho tướng quân."],"wrong":"Ta không phải người ra hàng. Ông ấy đứng gần cột cờ phía đông nam."},{"id":"s3","goal":"Cầm lấy sơ đồ trại giặc ở cạnh Trương Hiển.","type":"pickup","item":"sketch"},{"id":"s4","goal":"Mang sơ đồ về cho viên tướng tiên phong.","type":"give","npc":"general","item":"sketch","lines":["Có sơ đồ và người dẫn đường, ta sẽ đánh thẳng vào chỗ Toa Đô."]},{"id":"s5","goal":"Trả lời câu hỏi của viên tướng.","type":"ask","npc":"general","prompt":"Vì sao đạo quân Toa Đô trở nên cô lập?","options":[{"id":"a","text":"Vì Thoát Hoan đã rút chạy mà Toa Đô không hay biết."},{"id":"b","text":"Vì thuyền của Toa Đô bị bão đánh chìm hết."},{"id":"c","text":"Vì Toa Đô đã xin hàng."}],"correct":"a","right":"Đúng. Hai gọng kìm của giặc nay chỉ còn một.","wrong":"Chưa đúng. Em nhớ lại tin báo lúc nãy xem."},{"id":"s6","goal":"Ra cổng bắc, tiến về Tây Kết.","type":"battle","zone":"front"},{"id":"s7","goal":"Trở về doanh trại gặp viên tướng.","type":"talk","npc":"general","lines":["Toa Đô đã tử trận. Giặc trên đất ta không còn đạo quân nào đáng kể.","Lần này ta thắng vì cả nước một lòng."]}]},"battle":{"mode":"tactics","title":"Trận Tây Kết","intro":"Đạo quân Toa Đô đã cô lập ở Tây Kết. Có người dẫn đường vào tận nơi chỉ huy. Hạ được chủ tướng là trận đánh kết thúc.","allies":[{"id":"thuyquan1","name":"Thủy quân nhà Trần","cls":"thuyen","row":"front","hp":18,"atk":6,"def":2,"spd":5,"ranged":true,"skill":{"id":"skill","name":"Nỏ lớn","text":"Bắn mạnh vào một đơn vị ở bất kỳ hàng nào.","cost":2,"cooldown":2,"kind":"strike","power":1.6,"ranged":true},"tags":[],"sprite":"thuyen"},{"id":"thuyquan2","name":"Thủy quân nhà Trần","cls":"thuyen","row":"front","hp":16,"atk":5,"def":2,"spd":4,"ranged":true,"skill":{"id":"skill","name":"Mưa tên","text":"Bắn cả một hàng quân địch.","cost":3,"cooldown":3,"kind":"volley","power":0.9},"tags":[],"sprite":"thuyen"},{"id":"bobinh","name":"Bộ binh đổ bộ","cls":"bo","row":"front","hp":16,"atk":6,"def":2,"spd":6,"skill":{"id":"skill","name":"Giáo dài","text":"Đòn mạnh; bộ binh cầm giáo khắc chế kỵ binh.","cost":2,"cooldown":2,"kind":"strike","power":1.5},"tags":[],"sprite":"bo"}],"enemies":[{"id":"toado","name":"Toa Đô","cls":"tuong","row":"back","hp":20,"atk":6,"def":2,"spd":5,"skill":{"id":"skill","name":"Tử thủ","text":"Cả đội địch tăng sát thương trong 2 vòng.","cost":2,"cooldown":3,"kind":"rally","turns":2},"tags":[],"sprite":"e_tuong"},{"id":"eky","name":"Kỵ binh Nguyên","cls":"ky","row":"front","hp":16,"atk":6,"def":1,"spd":8,"skill":null,"tags":[],"sprite":"e_ky"},{"id":"ebo","name":"Lính Nguyên","cls":"bo","row":"front","hp":14,"atk":5,"def":1,"spd":4,"skill":null,"tags":[],"sprite":"e_bo"}],"supply":{"ally":3,"enemy":2,"regen":2,"enemy_regen":2,"per_supply_unit":0},"objective":{"type":"kill","unit":"toado"},"objective_text":"Hạ chủ tướng Toa Đô trong 7 vòng.","protect":null,"max_rounds":7,"hunger":null,"stratagem":{"name":"Người dẫn đường","text":"Dùng một lần: đánh trúng chỗ hiểm, quân địch yếu đi. Trả lời đúng thì hiệu lực dài gấp đôi.","prompt":"Ai đã đầu hàng và dẫn đường cho quân Trần đánh vào Tây Kết?","options":[{"id":"a","text":"Tổng quản Trương Hiển."},{"id":"b","text":"Tướng Ô Mã Nhi."},{"id":"c","text":"Tướng Lý Hằng."}],"correct":"a","explain":"Tổng quản quân Nguyên là Trương Hiển đầu hàng và dẫn đường cho quân Trần tấn công Toa Đô ở Tây Kết.","effect":{"type":"weaken_all","turns":2}},"tips":["Toa Đô ở hàng sau: thuyền của ta bắn tới được ngay.","Không cần diệt hết địch, chỉ cần hạ chủ tướng.","Bộ binh cầm giáo giữ chân kỵ binh để thuyền rảnh tay bắn."],"win_text":"Toa Đô tử trận, đạo quân phía nam của giặc tan vỡ. Cuộc kháng chiến lần thứ hai thắng lợi.","lose_text":"Chưa hạ được chủ tướng. Hãy dồn hỏa lực của thuyền vào Toa Đô thay vì đánh dàn trải."},"debrief":{"title":"Tây Kết và thắng lợi năm 1285","paragraphs":["Toa Đô đem quân từ phía nam đánh ra để hợp với Thoát Hoan. Khi Thoát Hoan đã thua và rút chạy, Toa Đô vẫn không biết, đóng quân ở sông Thiên Mạc rồi lui về Tây Kết (Khoái Châu).","Ngày 24/6/1285, quân Trần tấn công. Tổng quản Trương Hiển của quân Nguyên đầu hàng và dẫn đường. Toa Đô tử trận, Ô Mã Nhi chạy thoát ra biển. Các tài liệu chép khác nhau về người trực tiếp chỉ huy trận này nên trò chơi không gọi tên vị chỉ huy.","Cánh quân Thoát Hoan rút về phía bắc bị chặn đánh ở sông Như Nguyệt, Vạn Kiếp, Vĩnh Bình. Tương truyền Thoát Hoan phải chui vào ống đồng để trốn; đây là chuyện truyền lại, không phải ghi chép chắc chắn.","Cuộc kháng chiến lần thứ hai kết thúc thắng lợi nhờ chuẩn bị sớm, cả nước đồng lòng, biết lui để giữ sức và phản công đúng thời cơ."],"sources":["w2"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s09-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Trận Tây Kết diễn ra vào ngày nào?$hq$, $hq${"options":[{"id":"a","text":"24/6/1285"},{"id":"b","text":"17/1/1258"},{"id":"c","text":"18/2/1285"},{"id":"d","text":"9/4/1288"}],"correct":"a"}$hq$::jsonb, $hq$Ngày 24/6/1285 quân Trần đánh tan đạo quân Toa Đô ở Tây Kết.$hq$, $hq$w2$hq$),
    ($hq$s09-q2$hq$, 2, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Tướng Nguyên nào tử trận ở Tây Kết?$hq$, $hq${"options":[{"id":"a","text":"Toa Đô"},{"id":"b","text":"Thoát Hoan"},{"id":"c","text":"Ô Mã Nhi"},{"id":"d","text":"Trương Văn Hổ"}],"correct":"a"}$hq$::jsonb, $hq$Toa Đô tử trận; Ô Mã Nhi chạy thoát ra biển và ba năm sau lại theo quân Nguyên sang.$hq$, $hq$w2$hq$),
    ($hq$s09-s1$hq$, 3, $hq$sequence$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Xếp toàn bộ cuộc kháng chiến lần thứ hai theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Hội nghị Diên Hồng","when":"Đầu 1285"},{"id":"m2","text":"Quân Trần rời Thăng Long, lui về Thiên Trường","when":"Tháng 2/1285"},{"id":"m3","text":"Trận Hàm Tử","when":"Tháng 5/1285"},{"id":"m4","text":"Trận Chương Dương, giải phóng Thăng Long","when":"Tháng 6/1285"},{"id":"m5","text":"Trận Tây Kết","when":"24/6/1285"}]}$hq$::jsonb, $hq$Chuẩn bị, lui quân, rồi phản công: Hàm Tử, Chương Dương – Thăng Long, Tây Kết.$hq$, $hq$w2$hq$),
    ($hq$s09-p1$hq$, 4, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi tướng Nguyên với kết cục năm 1285.$hq$, $hq${"left_label":"Tướng Nguyên","right_label":"Kết cục","pairs":[{"id":"p1","left":"Toa Đô","right":"Tử trận ở Tây Kết"},{"id":"p2","left":"Thoát Hoan","right":"Rút chạy về nước"},{"id":"p3","left":"Ô Mã Nhi","right":"Chạy thoát ra biển"},{"id":"p4","left":"Trương Hiển","right":"Đầu hàng, dẫn đường cho quân Trần"}]}$hq$::jsonb, $hq$Toa Đô tử trận, Thoát Hoan tháo chạy, Ô Mã Nhi thoát ra biển, Trương Hiển ra hàng.$hq$, $hq$w2$hq$),
    ($hq$s09-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Em là người cầm quân, em chọn cách nào?$hq$, $hq${"situation":"Thoát Hoan đã chạy về bắc. Đạo quân Toa Đô ở Tây Kết còn mạnh nhưng không biết tin, không có ai tiếp ứng. Một tổng quản của giặc vừa ra hàng, xin dẫn đường.","options":[{"id":"a","text":"Để yên đạo quân Toa Đô, dồn hết sức đuổi Thoát Hoan.","feedback":"Bỏ lại một đạo quân mạnh sau lưng là rất nguy hiểm.","score":0},{"id":"b","text":"Nhân lúc Toa Đô cô lập, theo người dẫn đường đánh thẳng vào nơi chỉ huy.","feedback":"Đúng như quân Trần đã làm ngày 24/6/1285.","score":2},{"id":"c","text":"Chờ Toa Đô tự tìm đường rút ra biển.","feedback":"Giặc có thể tự rút, nhưng như thế là để một đạo quân nguyên vẹn thoát đi.","score":1}]}$hq$::jsonb, $hq$Đánh lúc địch bị cô lập và mất liên lạc, lại có người dẫn đường, là chọn đúng thời cơ.$hq$, $hq$w2$hq$),
    ($hq$s09-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Chuyện Thoát Hoan chui vào ống đồng để trốn về nước nên được hiểu thế nào?$hq$, $hq${"options":[{"id":"a","text":"Là chuyện “tương truyền”, chưa phải ghi chép chắc chắn"},{"id":"b","text":"Là sự thật được mọi sử sách ghi rõ"},{"id":"c","text":"Là chuyện xảy ra ở trận Bạch Đằng"},{"id":"d","text":"Là chuyện của tướng Toa Đô"}],"correct":"a"}$hq$::jsonb, $hq$Các tài liệu ghi là “tương truyền”. Khi học lịch sử cần phân biệt điều đã kiểm chứng với điều truyền lại.$hq$, $hq$w2$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$tay-ket$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 10: Thế giặc năm nay dễ phá (Năm 1287)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$chuan-bi-1287$hq$, 3, 10, $hq$Thế giặc năm nay dễ phá$hq$, $hq$Thăng Long$hq$, $hq$Năm 1287$hq$, $hq$prepare$hq$, $hq$scroll$hq$, $hq$Chuẩn bị trước khi giặc sang lần thứ ba: quân Nguyên chia ba đường, có thủy quân lớn và đoàn thuyền lương; Trần Quốc Tuấn tin chắc thắng.$hq$, 0.092, 0.76, NULL, NULL, NULL, 70, 100, 30, $hq$pham-ngu-lao$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Nêu được hoàn cảnh và ba đường tiến quân của quân Nguyên cuối năm 1287."},{"id":"o2","text":"Trình bày được sự chuẩn bị và niềm tin chiến thắng của quân dân nhà Trần."}],"cards":[{"id":"c1","kind":"why","title":"Giặc quyết phục thù","body":"Sau hai lần thất bại (1258 và 1285), vua Nguyên Hốt Tất Liệt đình chỉ kế hoạch đánh Nhật Bản để dồn sức đánh Đại Việt lần thứ ba vào cuối năm 1287. Quân Nguyên mượn tiếng đưa Trần Ích Tắc, người đã hàng giặc, về nước làm vua.","facts":[{"label":"Thời gian","value":"Cuối năm 1287"}],"objective":"o1","source":"manhghep","art":"envoy"},{"id":"c2","kind":"how","title":"Ba đường tiến quân","body":"Quân Nguyên chia ba cánh: một cánh từ Vân Nam xuống; đại quân do Thoát Hoan chỉ huy tiến vào biên giới đông bắc; thủy quân do Ô Mã Nhi và Phàn Tiếp chỉ huy 500 chiến thuyền đi đường biển, theo sau là đoàn thuyền lương của Trương Văn Hổ.","facts":[{"label":"Thủy quân","value":"Ô Mã Nhi, Phàn Tiếp – 500 chiến thuyền"},{"label":"Thuyền lương","value":"Trương Văn Hổ"}],"objective":"o1","source":"w3","art":"map"},{"id":"c3","kind":"who","title":"“Thế giặc năm nay dễ phá”","body":"Với kinh nghiệm đánh bại quân Nguyên hai năm trước, Trần Quốc Tuấn phân tích tình hình rồi tự tin tâu với vua: “Thế giặc năm nay dễ phá.” Vua Trần Nhân Tông đại xá thiên hạ; nhiều tù nhân được tha đã tình nguyện tòng quân.","facts":[{"label":"Tổng chỉ huy","value":"Hưng Đạo vương Trần Quốc Tuấn"}],"objective":"o2","source":"w3","art":"general"},{"id":"c4","kind":"where","title":"Chia quân giữ các nơi","body":"Trần Quốc Tuấn thống lĩnh các vương hầu chia quân giữ những nơi hiểm yếu. Riêng đường biển, Nhân Huệ vương Trần Khánh Dư được giao giữ Vân Đồn, cửa ngõ mà thuyền chiến và thuyền lương của giặc phải đi qua.","facts":[{"label":"Giữ Vân Đồn","value":"Trần Khánh Dư"}],"objective":"o2","source":"w3","art":"flag"}],"sources":[{"key":"w3","title":"Chiến tranh Nguyên Mông – Đại Việt lần 3","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử, Khâm định Việt sử thông giám cương mục)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_3","note":null},{"key":"manhghep","title":"Trận thủy chiến Bạch Đằng: Những mảnh ghép","publisher":"Bảo tàng Lịch sử quốc gia (đăng lại từ Tia Sáng)","url":"https://baotanglichsu.vn/VI/Articles/3096/71341/tran-thuy-chien-bach-djang-nhung-manh-ghep.html","note":"Tổng hợp kết quả khảo cổ các bãi cọc Yên Giang, Đồng Vạn Muối, Đồng Má Ngựa."}],"explore":{"scene":"palace","title":"Buổi chầu ở Thăng Long","intro":"Tin giặc lại sang đã về kinh. Em theo hầu trong buổi chầu bàn việc đánh giặc.","grid":["wwwwwwwwwwwwwwwwwwwwww","wwwwwwwww____wwwwwwwww","#__P______________P__#","#____________________#","#__P______________P__#","#____________________#","#__f______________f__#","#____________________#","#__P______________P__#","#____________________#","#########____#########","..T......====......T..",".........====........."],"spawn":[10,12],"npcs":[{"id":"vua","name":"Vua Trần Nhân Tông","role":"Nhà vua","sprite":"king","at":[10,2],"idle":"Giặc đến ba lần, ta đánh cả ba.","fictional":false},{"id":"hungdao","name":"Hưng Đạo vương","role":"Trần Quốc Tuấn","sprite":"commander","at":[7,4],"idle":"Thế giặc năm nay dễ phá.","fictional":false},{"id":"freed","name":"Người vừa được tha","role":"Xin tòng quân","sprite":"villager","at":[16,8],"idle":"Tôi được vua tha tội, chỉ mong ra trận báo ơn nước.","fictional":true},{"id":"courier","name":"Người đưa lệnh","role":"Lính trạm","sprite":"scout","at":[5,6],"idle":"Ngựa trạm đã sẵn, có lệnh là tôi đi ngay.","fictional":true},{"id":"elder","name":"Viên quan già","role":"Quan trong triều","sprite":"scholar","at":[14,4],"idle":"Hai lần trước ta đều thắng, lần này lòng người càng vững.","fictional":true}],"items":[{"id":"order","name":"Lệnh giữ Vân Đồn","sprite":"token","at":[12,6]}],"zones":[{"id":"door","name":"Cửa điện","rect":[9,10,4,1],"kind":"goal"}],"steps":[{"id":"s1","goal":"Vào điện gặp Hưng Đạo vương để nghe tình hình giặc.","clue":"Giặc chia ba đường: từ Vân Nam, từ đông bắc (Thoát Hoan) và đường biển (Ô Mã Nhi); theo sau thủy quân là đoàn thuyền lương của Trương Văn Hổ.","type":"talk","npc":"hungdao","lines":["Giặc Nguyên lại sang, lần này chia ba đường: một cánh từ Vân Nam xuống, đại quân Thoát Hoan vào từ đông bắc, thủy quân Ô Mã Nhi đi đường biển.","Theo sau thủy quân là đoàn thuyền lương của Trương Văn Hổ. Thế giặc năm nay dễ phá."]},{"id":"s2","goal":"Lên thềm, nhà vua đang hỏi về thế giặc.","type":"ask","npc":"vua","prompt":"Nhà vua hỏi: giặc tiến vào nước ta theo mấy đường?","options":[{"id":"a","text":"Một đường, từ biển vào."},{"id":"b","text":"Ba đường: từ Vân Nam, từ đông bắc và đường biển."},{"id":"c","text":"Hai đường, đều từ phía nam ra."}],"correct":"b","right":"Đúng. Vì thế ta phải chia quân giữ các nơi hiểm yếu.","wrong":"Chưa đúng. Em nghe lại lời Hưng Đạo vương xem."},{"id":"s3","goal":"Vua vừa đại xá. Tìm người vừa được tha đang xin tòng quân: anh đứng gần cây cột phía đông nam.","type":"find","npc":"freed","lines":["Tôi được vua tha tội. Xin cho tôi ra trận để báo ơn nước!"],"wrong":"Tôi không phải người ấy. Anh ta đứng gần cây cột phía đông nam."},{"id":"s4","goal":"Cầm lấy tờ lệnh giữ Vân Đồn đặt giữa điện.","type":"pickup","item":"order"},{"id":"s5","goal":"Trao lệnh cho người đưa lệnh ở phía tây điện.","type":"give","npc":"courier","item":"order","lines":["Lệnh này tôi mang ngay ra Vân Đồn cho Nhân Huệ vương Trần Khánh Dư: giữ chắc đường biển."]},{"id":"s6","goal":"Buổi chầu đã xong. Ra cửa điện phía nam.","type":"zone","zone":"door"}]},"battle":null,"debrief":{"title":"Trước cuộc kháng chiến lần thứ ba","paragraphs":["Sau hai lần thất bại, Hốt Tất Liệt đình chỉ kế hoạch đánh Nhật Bản để dồn sức đánh Đại Việt. Cuối năm 1287, quân Nguyên tiến sang theo ba đường: từ Vân Nam, từ đông bắc (đại quân Thoát Hoan) và đường biển (thủy quân Ô Mã Nhi, Phàn Tiếp với 500 chiến thuyền, theo sau là đoàn thuyền lương của Trương Văn Hổ).","Về phía Đại Việt, vua Trần Nhân Tông đại xá thiên hạ; nhiều tù nhân được tha tình nguyện ra trận. Trần Quốc Tuấn, người chỉ huy toàn quân, tự tin tâu với vua: “Thế giặc năm nay dễ phá.”","Quân Trần chia giữ các nơi hiểm yếu; Trần Khánh Dư giữ Vân Đồn trên đường biển. Lần này giặc không còn trông vào cướp lương tại chỗ mà chở lương theo đường biển, và chính đoàn thuyền lương ấy sẽ quyết định cục diện."],"sources":["w3","manhghep"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s10-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$“Thế giặc năm nay dễ phá” là lời của ai?$hq$, $hq${"options":[{"id":"a","text":"Trần Quốc Tuấn"},{"id":"b","text":"Trần Thủ Độ"},{"id":"c","text":"Trần Bình Trọng"},{"id":"d","text":"Trần Khánh Dư"}],"correct":"a"}$hq$::jsonb, $hq$Trần Quốc Tuấn tâu với vua Trần Nhân Tông trước cuộc kháng chiến lần thứ ba.$hq$, $hq$w3$hq$),
    ($hq$s10-q2$hq$, 2, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Cuối năm 1287, quân Nguyên tiến vào Đại Việt theo mấy đường?$hq$, $hq${"options":[{"id":"a","text":"Ba đường: từ Vân Nam, từ đông bắc và đường biển"},{"id":"b","text":"Một đường duy nhất qua Lạng Sơn"},{"id":"c","text":"Hai đường: đường biển và từ Chiêm Thành ra"},{"id":"d","text":"Bốn đường, có cả đường từ Ai Lao"}],"correct":"a"}$hq$::jsonb, $hq$Một cánh từ Vân Nam, đại quân Thoát Hoan vào đông bắc, thủy quân Ô Mã Nhi và Phàn Tiếp đi đường biển.$hq$, $hq$w3$hq$),
    ($hq$s10-p1$hq$, 3, $hq$pairs$hq$, $hq$practice$hq$, $hq$o1$hq$, $hq$Lật thẻ và ghép mỗi người với nhiệm vụ cuối năm 1287.$hq$, $hq${"left_label":"Nhân vật","right_label":"Nhiệm vụ","pairs":[{"id":"p1","left":"Thoát Hoan","right":"Chỉ huy đại quân vào đông bắc"},{"id":"p2","left":"Ô Mã Nhi","right":"Chỉ huy thủy quân đi đường biển"},{"id":"p3","left":"Trương Văn Hổ","right":"Phụ trách đoàn thuyền lương"},{"id":"p4","left":"Trần Khánh Dư","right":"Giữ Vân Đồn"}]}$hq$::jsonb, $hq$Ba người đầu thuộc quân Nguyên; Trần Khánh Dư là tướng nhà Trần giữ đường biển ở Vân Đồn.$hq$, $hq$w3$hq$),
    ($hq$s10-s1$hq$, 4, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Quân Nguyên thất bại lần thứ hai","when":"1285"},{"id":"m2","text":"Hốt Tất Liệt hoãn đánh Nhật Bản, dồn sức đánh Đại Việt"},{"id":"m3","text":"Quân Nguyên tiến sang theo ba đường","when":"Cuối 1287"},{"id":"m4","text":"Trận Vân Đồn","when":"Đầu 1288"}]}$hq$::jsonb, $hq$Thất bại năm 1285 khiến vua Nguyên quyết phục thù; cuối 1287 giặc sang, đầu 1288 diễn ra trận Vân Đồn.$hq$, $hq$manhghep$hq$),
    ($hq$s10-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em là người chỉ huy toàn quân, em bố trí thế nào?$hq$, $hq${"situation":"Giặc sang theo ba đường. Lần này chúng có thủy quân lớn đi đường biển, kéo theo cả đoàn thuyền chở lương.","options":[{"id":"a","text":"Dồn hết quân về giữ Thăng Long.","feedback":"Bỏ ngỏ biên giới và đường biển thì giặc hợp quân dễ dàng, lương cũng tới nơi.","score":0},{"id":"b","text":"Chia quân giữ các nơi hiểm yếu, cử tướng giữ đường biển Vân Đồn.","feedback":"Đúng như Trần Quốc Tuấn đã làm; Trần Khánh Dư được giao giữ Vân Đồn.","score":2},{"id":"c","text":"Đem toàn bộ thủy quân ra khơi tìm đánh thuyền chiến của giặc.","feedback":"Thủy quân giặc rất mạnh; ra khơi tìm đánh là bỏ lợi thế địa hình sông ngòi của ta.","score":0}]}$hq$::jsonb, $hq$Chia quân giữ nơi hiểm yếu và giữ đường biển giúp quân Trần chủ động trước ba mũi tiến công.$hq$, $hq$w3$hq$),
    ($hq$s10-q3$hq$, 6, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Cánh thủy quân của Ô Mã Nhi và Phàn Tiếp có khoảng bao nhiêu chiến thuyền?$hq$, $hq${"options":[{"id":"a","text":"500"},{"id":"b","text":"50"},{"id":"c","text":"5.000"},{"id":"d","text":"70"}],"correct":"a"}$hq$::jsonb, $hq$Thủy quân Nguyên gồm 500 chiến thuyền; đi theo sau là đoàn thuyền lương.$hq$, $hq$w3$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$chuan-bi-1287$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 11: Vân Đồn (Cuối 12/1287 – đầu 1/1288)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$van-don$hq$, 3, 11, $hq$Vân Đồn$hq$, $hq$Vân Đồn – Cửa Lục$hq$, $hq$Cuối 12/1287 – đầu 1/1288$hq$, $hq$battle$hq$, $hq$anchor$hq$, $hq$Trần Khánh Dư đón đánh đoàn thuyền lương của Trương Văn Hổ. Mất lương, quân Nguyên rơi vào thế bị động.$hq$, 0.925, 0.62, 0.935, 0.755, $hq$chuan-bi-1287$hq$, 70, 120, 40, $hq$tran-khanh-du$hq$, $hq$saga-van-don$hq$,
     $hq${"objectives":[{"id":"o1","text":"Thuật lại được trận Vân Đồn và vai trò của Trần Khánh Dư."},{"id":"o2","text":"Giải thích được vì sao mất đoàn thuyền lương là bước ngoặt của cuộc kháng chiến lần thứ ba."}],"cards":[{"id":"c1","kind":"why","title":"Lương đi đường biển","body":"Rút kinh nghiệm hai lần trước bị đói vì “vườn không nhà trống”, lần này quân Nguyên chở lương theo đường biển. Ô Mã Nhi và Phàn Tiếp cầm thủy quân mở đường; đoàn thuyền lương của Trương Văn Hổ theo sau.","facts":[{"label":"Điểm yếu","value":"Thuyền lương nặng, đi chậm"}],"objective":"o2","source":"w3","art":"boat"},{"id":"c2","kind":"who","title":"Trần Khánh Dư xin chuộc tội","body":"Trần Khánh Dư giữ đường biển nhưng để thủy quân Ô Mã Nhi vượt qua, bị Thượng hoàng sai sứ tới hỏi tội. Ông xin khất vài ngày để lập công chuộc tội, vì đoán rằng thuyền chiến đi trước thì thuyền lương ắt theo sau.","facts":[{"label":"Tước hiệu","value":"Nhân Huệ vương"}],"objective":"o1","source":"w3","art":"general"},{"id":"c3","kind":"how","title":"Trận Vân Đồn","body":"Cho rằng quân Trần yếu, Ô Mã Nhi tiến sâu vào nội địa, bỏ đoàn thuyền lương lại phía sau. Khoảng cuối tháng 12/1287 – đầu tháng 1/1288, đoàn thuyền lương tới Vân Đồn thì bị Trần Khánh Dư tập kích. Trương Văn Hổ thua to, đổ cả thóc xuống biển rồi bỏ chạy.","facts":[{"label":"Thời gian","value":"Cuối 12/1287 – đầu 1/1288"},{"label":"Nơi","value":"Vân Đồn – Cửa Lục"}],"objective":"o1","source":"w3","art":"swords"},{"id":"c4","kind":"why","title":"Bước ngoặt","body":"Các đoàn thuyền lương khác gặp bão hoặc đi lạc nên lương của quân Nguyên mất hoàn toàn. Sách Cương mục chép: “Quân Nguyên từ đấy thiếu lương ăn, mỗi ngày một quẫn bách thêm. Quân sĩ ai cũng muốn về, không ai có lòng chiến đấu.”","facts":[{"label":"Hệ quả","value":"Giặc bị động, phải tính đường rút"}],"objective":"o2","source":"w3","art":"granary"}],"sources":[{"key":"w3","title":"Chiến tranh Nguyên Mông – Đại Việt lần 3","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử, Khâm định Việt sử thông giám cương mục)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_3","note":null}],"explore":{"scene":"shipyard","title":"Bãi biển Vân Đồn","intro":"Thủy quân giặc vừa vượt qua. Sứ giả của Thượng hoàng đã tới hỏi tội. Em ở bên Nhân Huệ vương Trần Khánh Dư.","grid":["TTTTTTTTTTTTTT::::~~~~","T....L.L.....:::::~~~~","T............::::~~~~~","T..h.........::S:~~~~~","T===============:::~~~","T............::::~~~~~","T...L..S.....:::::~~~~","T............::S::~~~~","T..F.........:::::++~~","T............::::~b~~~","T..c.c.......:::~~~~~~","T............::~~~~~~~","TTTTTTTTTTTTT:~~~~~~~~"],"spawn":[1,4],"npcs":[{"id":"khanhdu","name":"Trần Khánh Dư","role":"Nhân Huệ vương, giữ Vân Đồn","sprite":"commander","at":[9,3],"idle":"Thuyền chiến qua rồi thì thuyền lương ắt tới.","fictional":false},{"id":"envoy","name":"Sứ giả của Thượng hoàng","role":"Tới hỏi tội","sprite":"scholar","at":[6,5],"idle":"Ta chờ xem Nhân Huệ vương lập công thế nào.","fictional":true},{"id":"lookout","name":"Lính canh biển","role":"Trinh sát","sprite":"scout","at":[16,1],"idle":"Từ mũi cát này nhìn được ra tận khơi xa.","fictional":true},{"id":"fisher","name":"Người dân chài","role":"Dân biển Vân Đồn","sprite":"villager","at":[15,9],"idle":"Dân chài chúng tôi thuộc từng con nước ở đây.","fictional":true},{"id":"carpenter","name":"Thợ sửa thuyền","role":"Thợ mộc","sprite":"villager","at":[5,7],"idle":"Thuyền nhẹ của ta đã trét xong, hạ thủy lúc nào cũng được.","fictional":true}],"items":[{"id":"horn","name":"Chiếc tù và","sprite":"horn","at":[4,9]}],"zones":[{"id":"sea","name":"Cầu ván ra biển","rect":[18,8,2,1],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Gặp Nhân Huệ vương Trần Khánh Dư.","clue":"Trần Khánh Dư đoán: thuyền chiến của giặc đi trước thì đoàn thuyền lương ắt theo sau, nên xin khất vài ngày để lập công chuộc tội.","type":"talk","npc":"khanhdu","lines":["Ta để thủy quân Ô Mã Nhi vượt qua Vân Đồn, Thượng hoàng đã sai sứ tới hỏi tội.","Nhưng thuyền chiến đi trước thì thuyền lương ắt theo sau. Ta xin khất vài ngày để lập công chuộc tội."]},{"id":"s2","goal":"Tìm người lính canh biển ở mũi cát phía đông bắc để hỏi tin đoàn thuyền lương.","type":"find","npc":"lookout","lines":["Thấy rồi! Đoàn thuyền lương nặng nề đang tới, phía trước không có thuyền chiến mở đường."],"wrong":"Tôi không canh biển. Anh lính ấy đứng ở mũi cát phía đông bắc."},{"id":"s3","goal":"Về báo tin cho Nhân Huệ vương.","type":"ask","npc":"khanhdu","prompt":"Nhân Huệ vương hỏi: vì sao ta nên đón đánh đoàn thuyền lương?","options":[{"id":"a","text":"Vì thuyền lương chở nhiều vàng bạc."},{"id":"b","text":"Vì mất lương thì cả đạo quân Nguyên sẽ đói, không ở lâu được."},{"id":"c","text":"Vì thuyền lương là nơi Thoát Hoan chỉ huy."}],"correct":"b","right":"Đúng. Đánh một trận này bằng đánh mười trận khác.","wrong":"Chưa phải. Em nghĩ xem đạo quân lớn cần gì nhất."},{"id":"s4","goal":"Lấy chiếc tù và để gần bếp lửa phía tây nam.","type":"pickup","item":"horn"},{"id":"s5","goal":"Mang tù và cho người dân chài ở bãi cát phía đông nam.","type":"give","npc":"fisher","item":"horn","lines":["Nghe tù và là thuyền chài chúng tôi kéo ra hết!"]},{"id":"s6","goal":"Ra cầu ván phía đông, xuống thuyền đón đánh đoàn thuyền lương.","type":"battle","zone":"sea"},{"id":"s7","goal":"Trở lại gặp Nhân Huệ vương.","type":"talk","npc":"khanhdu","lines":["Trương Văn Hổ đổ cả thóc xuống biển mà chạy.","Giặc ở Thăng Long sẽ đói. Trận này ta đã chuộc được tội."]}]},"battle":{"mode":"tactics","title":"Trận Vân Đồn","intro":"Đoàn thuyền lương nặng nề đang vượt biển, chỉ có vài thuyền hộ tống. Phải phá các thuyền lương trước khi chúng chạy thoát; mỗi thuyền lương còn nổi sẽ tiếp thêm quân lương cho địch.","allies":[{"id":"khanhdu","name":"Thuyền Trần Khánh Dư","cls":"thuyen","row":"front","hp":18,"atk":6,"def":2,"spd":6,"ranged":true,"skill":{"id":"skill","name":"Đánh chặn","text":"Đòn mạnh vào một đơn vị ở bất kỳ hàng nào.","cost":2,"cooldown":2,"kind":"strike","power":1.6,"ranged":true},"tags":[],"sprite":"thuyen"},{"id":"nhe1","name":"Thuyền nhẹ Vân Đồn","cls":"thuyen","row":"front","hp":16,"atk":5,"def":2,"spd":8,"ranged":true,"skill":{"id":"skill","name":"Tên lửa","text":"Bắn cả một hàng quân địch và làm thuyền bốc cháy.","cost":3,"cooldown":3,"kind":"volley","power":0.8,"status":"burn","turns":2},"tags":[],"sprite":"thuyen_nhe"},{"id":"nhe2","name":"Thuyền dân chài","cls":"thuyen","row":"front","hp":16,"atk":5,"def":2,"spd":7,"ranged":true,"skill":null,"tags":[],"sprite":"thuyen_nhe"}],"enemies":[{"id":"hotong1","name":"Thuyền hộ tống","cls":"thuyen","row":"front","hp":16,"atk":5,"def":2,"spd":5,"ranged":true,"skill":{"id":"skill","name":"Bắn đá","text":"Đòn mạnh vào một đơn vị.","cost":2,"cooldown":2,"kind":"strike","power":1.5,"ranged":true},"tags":[],"sprite":"e_thuyen"},{"id":"hotong2","name":"Thuyền hộ tống","cls":"thuyen","row":"front","hp":14,"atk":4,"def":1,"spd":4,"ranged":true,"skill":null,"tags":[],"sprite":"e_thuyen"},{"id":"luong1","name":"Thuyền lương","cls":"luong","row":"back","hp":17,"atk":0,"def":1,"spd":2,"skill":null,"tags":["supply"],"sprite":"e_luong"},{"id":"luong2","name":"Thuyền lương","cls":"luong","row":"back","hp":17,"atk":0,"def":1,"spd":2,"skill":null,"tags":["supply"],"sprite":"e_luong"},{"id":"luong3","name":"Thuyền lương","cls":"luong","row":"back","hp":17,"atk":0,"def":1,"spd":1,"skill":null,"tags":["supply"],"sprite":"e_luong"}],"supply":{"ally":3,"enemy":2,"regen":2,"enemy_regen":0,"per_supply_unit":1},"objective":{"type":"destroy","tag":"supply","need":3,"rounds":6},"objective_text":"Phá cả 3 thuyền lương trong 6 vòng, trước khi chúng chạy thoát.","protect":null,"max_rounds":6,"hunger":null,"stratagem":{"name":"Đánh vào lương thảo","text":"Dùng một lần: địch mất hết quân lương đang có và không được tiếp thêm. Trả lời đúng thì kéo dài gấp đôi.","prompt":"Vì sao Trần Khánh Dư chọn đánh đoàn thuyền lương?","options":[{"id":"a","text":"Vì mất lương, cả đạo quân Nguyên sẽ đói và phải rút."},{"id":"b","text":"Vì thuyền lương chở vua Nguyên."},{"id":"c","text":"Vì thuyền lương mạnh hơn thuyền chiến."}],"correct":"a","explain":"Đạo quân Nguyên rất đông, trông cả vào lương chở đường biển. Mất đoàn thuyền lương, chúng thiếu ăn và rơi vào thế bị động.","effect":{"type":"cut_supply","turns":2}},"tips":["Thuyền lương ở hàng sau; thuyền của ta đều bắn xa nên với tới được ngay.","Không cần diệt thuyền hộ tống. Mục tiêu là 3 thuyền lương.","“Tên lửa” đốt cả hàng thuyền lương cùng lúc."],"win_text":"Đoàn thuyền lương tan tác. Trương Văn Hổ đổ thóc xuống biển rồi bỏ chạy; quân Nguyên từ đây thiếu lương.","lose_text":"Thuyền lương đã chạy thoát. Đừng sa vào đánh thuyền hộ tống, hãy dồn sức vào thuyền lương."},"debrief":{"title":"Vân Đồn: đánh vào dạ dày của giặc","paragraphs":["Ô Mã Nhi và Phàn Tiếp cầm thủy quân mở đường cho đoàn thuyền lương của Trương Văn Hổ. Sau khi vượt qua được Vân Đồn, Ô Mã Nhi cho rằng quân Trần yếu nên tiến sâu vào nội địa, bỏ đoàn thuyền lương lại phía sau.","Trần Khánh Dư để giặc đi qua nên bị Thượng hoàng sai sứ hỏi tội; ông xin khất vài ngày để chuộc tội. Khoảng cuối tháng 12/1287 – đầu tháng 1/1288, đoàn thuyền lương tới Vân Đồn và bị tập kích. Không có quân chủ lực bảo vệ, Trương Văn Hổ thua to, đổ thóc xuống biển rồi bỏ chạy.","Các đoàn thuyền lương khác gặp bão hoặc đi lạc. Mất lương, quân Nguyên “mỗi ngày một quẫn bách thêm”. Chiến thắng Vân Đồn là bước ngoặt của cuộc kháng chiến lần thứ ba."],"sources":["w3"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
