-- ---------------------------------------------------------------------- chặng 12: Giặc cạn lương ở Vạn Kiếp (Tháng 2 – 3/1288)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$van-kiep-1288$hq$, 3, 12, $hq$Giặc cạn lương ở Vạn Kiếp$hq$, $hq$Thăng Long – Vạn Kiếp$hq$, $hq$Tháng 2 – 3/1288$hq$, $hq$strategy$hq$, $hq$tent$hq$, $hq$Không có lương, Thoát Hoan bỏ Thăng Long về Vạn Kiếp, bị tập kích liên tục rồi quyết định rút quân theo hai đường thủy, bộ.$hq$, 0.464, 0.606, NULL, NULL, $hq$van-don$hq$, 70, 100, 30, $hq$nguyen-khoai$hq$, NULL,
     $hq${"objectives":[{"id":"o1","text":"Giải thích được vì sao quân Nguyên phải bỏ Thăng Long về Vạn Kiếp rồi quyết định rút về nước."},{"id":"o2","text":"Nêu được hai đường rút quân của giặc và việc quân Trần chuẩn bị đón đánh."}],"cards":[{"id":"c1","kind":"how","title":"Chiếm thành mà không thắng","body":"Đầu tháng 2/1288, quân Nguyên đánh tới Thăng Long. Chúng lại vào được kinh thành nhưng rơi vào cảnh thiếu lương thực, vẫn không bắt được hai vua Trần và không phá được chủ lực quân Đại Việt.","facts":[{"label":"Thời gian","value":"Tháng 2/1288"}],"objective":"o1","source":"manhghep","art":"palace"},{"id":"c2","kind":"why","title":"Không lương thì không giữ được","body":"Chờ mãi không thấy thuyền lương của Trương Văn Hổ, Thoát Hoan phải rút khỏi Thăng Long về Vạn Kiếp. Tới cuối tháng 3/1288, quân Nguyên co cụm ở Vạn Kiếp: lương ít, đêm đêm bị tập kích, bệnh tật lan rộng.","facts":[{"label":"Căn cứ của giặc","value":"Vạn Kiếp"}],"objective":"o1","source":"w3","art":"granary"},{"id":"c3","kind":"how","title":"Kế trá hàng","body":"Để giặc thêm xuống sức, vua Trần dùng kế trá hàng: Hưng Ninh vương Trần Tung sang trại giặc hẹn ngày “xin hàng”. Thoát Hoan tưởng thật, án binh chờ đợi. Đang lúc giặc mất cảnh giác, quân Đại Việt tập kích ban đêm, hạ liền mấy trại.","facts":[{"label":"Người sang trá hàng","value":"Hưng Ninh vương Trần Tung"}],"objective":"o1","source":"w3","art":"scroll"},{"id":"c4","kind":"when","title":"Hai đường rút quân","body":"Tướng Nguyên bàn nhau: “Quân có thể về, không thể giữ.” Cuối tháng 3/1288, Thoát Hoan quyết định rút: thủy quân do Ô Mã Nhi và Phàn Tiếp chỉ huy theo đường sông ra biển; bộ binh do Thoát Hoan chỉ huy theo đường bộ. Đoán được, Trần Hưng Đạo cho đón đánh trên cả hai đường.","facts":[{"label":"Đường thủy","value":"Ô Mã Nhi, Phàn Tiếp"},{"label":"Đường bộ","value":"Thoát Hoan"}],"objective":"o2","source":"w3","art":"map"}],"sources":[{"key":"w3","title":"Chiến tranh Nguyên Mông – Đại Việt lần 3","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử, Khâm định Việt sử thông giám cương mục)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_3","note":null},{"key":"manhghep","title":"Trận thủy chiến Bạch Đằng: Những mảnh ghép","publisher":"Bảo tàng Lịch sử quốc gia (đăng lại từ Tia Sáng)","url":"https://baotanglichsu.vn/VI/Articles/3096/71341/tran-thuy-chien-bach-djang-nhung-manh-ghep.html","note":"Tổng hợp kết quả khảo cổ các bãi cọc Yên Giang, Đồng Vạn Muối, Đồng Má Ngựa."}],"explore":{"scene":"camp","title":"Trại tiền quân gần Vạn Kiếp","intro":"Giặc co cụm trong các thành gỗ ở Vạn Kiếp. Tướng quân cần biết chúng sẽ rút đường nào.","grid":["TTTTTTTTTT==TTTTTTTTTT","T########.==.########T","T#h.h..f..==..f..h.h#T","T#........==........#T","T#..c.....==.....D..#T","T#==================#T","T#..F.....==........#T","T#........==...c.c..#T","T#.h...h..==........#T","T#........==..f.....#T","T########.==.########T","TTTTTTTTT.==.TTTTTTTTT",".........====........."],"spawn":[10,11],"npcs":[{"id":"general","name":"Viên tướng tiền quân","role":"Chỉ huy trại","sprite":"general","at":[6,3],"idle":"Giặc đói rồi, nhưng thú cùng đường vẫn nguy hiểm.","fictional":true},{"id":"scout","name":"Lính trinh sát","role":"Vừa từ Vạn Kiếp về","sprite":"scout","at":[16,3],"idle":"Tôi nằm sát thành gỗ của giặc suốt ba đêm.","fictional":true},{"id":"courier","name":"Người đưa thư","role":"Lính trạm","sprite":"soldier","at":[12,9],"idle":"Có thư hỏa tốc là tôi lên đường ngay.","fictional":true},{"id":"cook","name":"Hỏa đầu quân","role":"Lính nấu bếp","sprite":"villager","at":[5,6],"idle":"Đêm nay quân ta lại đi tập kích, phải nấu cơm sớm.","fictional":true},{"id":"guard","name":"Lính gác","role":"Canh cổng bắc","sprite":"soldier","at":[12,3],"idle":"Ban đêm là lúc của quân ta.","fictional":true}],"items":[{"id":"letter","name":"Thư hỏa tốc","sprite":"scroll","at":[4,8]}],"zones":[{"id":"gate","name":"Cổng nam của trại","rect":[9,10,4,3],"kind":"goal"}],"steps":[{"id":"s1","goal":"Vào trại gặp viên tướng tiền quân.","type":"talk","npc":"general","lines":["Giặc bỏ Thăng Long, co cả về Vạn Kiếp. Lương cạn, đêm nào cũng bị quân ta tập kích.","Ta cần biết chúng định rút đường nào. Em tìm người trinh sát vừa về mà hỏi."]},{"id":"s2","goal":"Tìm người trinh sát vừa từ Vạn Kiếp về: anh đứng gần chiếc trống ở phía đông bắc trại.","clue":"Giặc rút theo hai ngả: thủy quân (Ô Mã Nhi, Phàn Tiếp) theo đường sông ra biển; bộ binh (Thoát Hoan) theo đường bộ lên biên giới.","type":"find","npc":"scout","lines":["Tướng giặc bàn nhau: “Quân có thể về, không thể giữ.”","Chúng chia hai ngả: thủy quân của Ô Mã Nhi và Phàn Tiếp theo đường sông ra biển, bộ binh của Thoát Hoan theo đường bộ lên biên giới."],"wrong":"Tôi không đi trinh sát. Anh ấy đứng gần chiếc trống ở phía đông bắc."},{"id":"s3","goal":"Về báo tin cho viên tướng.","type":"ask","npc":"general","prompt":"Quân Nguyên sẽ rút theo những đường nào?","options":[{"id":"a","text":"Cả đạo quân rút theo đường biển."},{"id":"b","text":"Hai ngả: thủy quân theo sông ra biển, bộ binh theo đường bộ lên biên giới."},{"id":"c","text":"Cả đạo quân ở lại cố thủ Vạn Kiếp."}],"correct":"b","right":"Vậy thì ta đón chúng trên cả hai đường. Phải báo ngay cho Hưng Đạo vương.","wrong":"Người trinh sát nói khác. Em nhớ lại xem."},{"id":"s4","goal":"Lấy phong thư hỏa tốc ở gần lều phía tây nam.","type":"pickup","item":"letter"},{"id":"s5","goal":"Trao thư cho người đưa thư đứng gần cột cờ phía nam.","type":"give","npc":"courier","item":"letter","lines":["Thư này tôi mang ngay tới Hưng Đạo vương: thủy quân giặc sẽ theo đường sông ra biển."]},{"id":"s6","goal":"Việc đã xong. Rời trại theo cổng nam.","type":"zone","zone":"gate"}]},"battle":null,"debrief":{"title":"Từ Thăng Long về Vạn Kiếp","paragraphs":["Đầu tháng 2/1288, quân Nguyên đánh tới Thăng Long. Chúng lại chiếm được kinh thành nhưng thiếu lương, không bắt được hai vua Trần và không phá được chủ lực quân Đại Việt. Chờ mãi không thấy thuyền lương, Thoát Hoan rút về Vạn Kiếp.","Ở Vạn Kiếp, quân Nguyên cố thủ trong các thành gỗ, thường xuyên bị tập kích ban đêm, lương ít, bệnh tật lan rộng. Vua Trần còn dùng kế trá hàng (Hưng Ninh vương Trần Tung sang hẹn ngày “xin hàng”) rồi bất ngờ tập kích.","Cuối tháng 3/1288, Thoát Hoan quyết định rút quân theo hai ngả: thủy quân do Ô Mã Nhi và Phàn Tiếp chỉ huy, bộ binh do Thoát Hoan chỉ huy. Trần Hưng Đạo đoán được và tổ chức đón đánh; trận quyết định sẽ diễn ra trên sông Bạch Đằng."],"sources":["w3","manhghep"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
INSERT INTO public.hk_saga_items (stage_id, code, position, kind, usage, objective, prompt, data, explanation, source)
SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s12-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Vì sao Thoát Hoan phải bỏ Thăng Long rút về Vạn Kiếp?$hq$, $hq${"options":[{"id":"a","text":"Vì thiếu lương do đoàn thuyền lương không tới"},{"id":"b","text":"Vì quân Trần đốt kinh thành"},{"id":"c","text":"Vì vua Nguyên gọi về"},{"id":"d","text":"Vì thủy quân Nguyên đã bị diệt ở Bạch Đằng"}],"correct":"a"}$hq$::jsonb, $hq$Đoàn thuyền lương bị đánh tan ở Vân Đồn nên đại quân Thoát Hoan không có lương để ở lại Thăng Long.$hq$, $hq$w3$hq$),
    ($hq$s12-q2$hq$, 2, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Ai sang trại giặc hẹn ngày “xin hàng” để giặc mất cảnh giác?$hq$, $hq${"options":[{"id":"a","text":"Hưng Ninh vương Trần Tung"},{"id":"b","text":"Trần Khánh Dư"},{"id":"c","text":"Trần Quốc Toản"},{"id":"d","text":"Trần Bình Trọng"}],"correct":"a"}$hq$::jsonb, $hq$Vua Trần dùng kế trá hàng, cử Hưng Ninh vương Trần Tung sang trại quân Nguyên.$hq$, $hq$w3$hq$),
    ($hq$s12-s1$hq$, 3, $hq$sequence$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Xếp các sự việc theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Đoàn thuyền lương bị đánh tan ở Vân Đồn","when":"Đầu 1/1288"},{"id":"m2","text":"Quân Nguyên đánh tới Thăng Long","when":"Đầu 2/1288"},{"id":"m3","text":"Thoát Hoan rút về Vạn Kiếp"},{"id":"m4","text":"Giặc quyết định rút quân theo hai đường","when":"Cuối 3/1288"}]}$hq$::jsonb, $hq$Mất lương, chiếm Thăng Long cũng không giữ được; giặc co về Vạn Kiếp rồi quyết định rút.$hq$, $hq$w3$hq$),
    ($hq$s12-p1$hq$, 4, $hq$pairs$hq$, $hq$practice$hq$, $hq$o2$hq$, $hq$Lật thẻ và ghép cho đúng.$hq$, $hq${"left_label":"Tên","right_label":"Gắn với","pairs":[{"id":"p1","left":"Thoát Hoan","right":"Rút theo đường bộ"},{"id":"p2","left":"Ô Mã Nhi, Phàn Tiếp","right":"Rút theo đường thủy"},{"id":"p3","left":"Trần Tung","right":"Sang trại giặc trá hàng"},{"id":"p4","left":"Vạn Kiếp","right":"Nơi giặc co cụm trước khi rút"}]}$hq$::jsonb, $hq$Giặc rút theo hai ngả thủy, bộ từ căn cứ Vạn Kiếp.$hq$, $hq$w3$hq$),
    ($hq$s12-t1$hq$, 5, $hq$tactic$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Em là người chỉ huy, em chọn cách nào?$hq$, $hq${"situation":"Trinh sát báo: giặc sắp rút theo hai ngả, thủy quân theo sông ra biển, bộ binh theo đường bộ lên biên giới.","options":[{"id":"a","text":"Để chúng rút yên cho nhanh hết chiến tranh.","feedback":"Để nguyên lực lượng giặc rút đi thì chúng sẽ lại sang.","score":0},{"id":"b","text":"Chuẩn bị sẵn trận địa trên đường rút của chúng, cả đường thủy lẫn đường bộ.","feedback":"Đúng như Trần Hưng Đạo đã làm: đón đánh trên sông Bạch Đằng và dọc đường bộ lên biên giới.","score":2},{"id":"c","text":"Dồn quân đánh thẳng vào các thành gỗ ở Vạn Kiếp ngay.","feedback":"Giặc đói nhưng còn đông và có thành lũy; đánh lúc chúng đang rút, đội hình kéo dài, sẽ lợi hơn nhiều.","score":1}]}$hq$::jsonb, $hq$Đánh địch trên đường rút, ở nơi địa hình có lợi cho ta, hiệu quả hơn công phá căn cứ của chúng.$hq$, $hq$w3$hq$),
    ($hq$s12-l1$hq$, 6, $hq$locate$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Hãy chọn Vạn Kiếp, nơi quân Nguyên co cụm trước khi rút.$hq$, $hq${"campaign_no":3,"spots":[{"id":"s1","label":"Thăng Long","x":0.092,"y":0.76},{"id":"s2","label":"Vạn Kiếp","x":0.464,"y":0.606},{"id":"s3","label":"Trúc Động","x":0.627,"y":0.741},{"id":"s4","label":"Nội Bàng","x":0.565,"y":0.273}],"correct":"s2"}$hq$::jsonb, $hq$Vạn Kiếp – Phả Lại nằm ở ngã ba sông, là căn cứ quân sự của quân Nguyên.$hq$, $hq$w3$hq$)
) AS v(code, position, kind, usage, objective, prompt, data, explanation, source) WHERE s.code = $hq$van-kiep-1288$hq$
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------- chặng 13: Bạch Đằng (9/4/1288)
INSERT INTO public.hk_saga_stages (code, campaign_no, position, title, place, date_label, kind, icon, summary, map_x, map_y, anchor_x, anchor_y, unlock_after, pass_percent, reward_xp, reward_gold, card_code, badge_code, content, status, review_note) VALUES
    ($hq$bach-dang$hq$, 3, 13, $hq$Bạch Đằng$hq$, $hq$Cửa sông Bạch Đằng$hq$, $hq$9/4/1288$hq$, $hq$battle$hq$, $hq$waves$hq$, $hq$Trận quyết chiến: quân Trần đóng cọc ở cửa sông, nhử thủy quân Ô Mã Nhi vào trận địa lúc nước lên và phản công khi nước rút.$hq$, 0.752, 0.8, NULL, NULL, $hq$van-kiep-1288$hq$, 70, 200, 80, $hq$tran-hung-dao$hq$, $hq$saga-bach-dang$hq$,
     $hq${"objectives":[{"id":"o1","text":"Giải thích được cách quân Trần lợi dụng thủy triều và bãi cọc trên sông Bạch Đằng."},{"id":"o2","text":"Thuật lại được diễn biến, kết quả trận Bạch Đằng ngày 9/4/1288 và ý nghĩa của chiến thắng."}],"cards":[{"id":"c1","kind":"where","title":"Dòng sông và con nước","body":"Sông Bạch Đằng là đường thủy ra biển của thủy quân Ô Mã Nhi. Ở cửa sông, nước triều lên xuống rất mạnh. Năm 938, Ngô Quyền từng thắng quân Nam Hán tại đây. Trần Hưng Đạo nghiên cứu kỹ quy luật thủy triều để bày trận địa cọc.","facts":[{"label":"Điều then chốt","value":"Thủy triều lên – xuống"}],"objective":"o1","source":"wbd","art":"river"},{"id":"c2","kind":"how","title":"Bãi cọc ngầm","body":"Cọc bằng gỗ lim và nhiều loại gỗ khác, một đầu đẽo nhọn, được đóng xuống lòng sông khi nước triều rút, cách nhau khoảng 0,9 – 1,2 m. Nước lên thì cọc chìm khuất. Hiện vật cọc Bạch Đằng tìm thấy ở sông Chanh (Quảng Ninh) đang được lưu giữ tại bảo tàng.","facts":[{"label":"Đóng cọc lúc","value":"Nước triều rút"},{"label":"Khoảng cách","value":"0,9 – 1,2 m"}],"objective":"o1","source":"coc","art":"stakes"},{"id":"c3","kind":"how","title":"Cọc đóng ở đâu?","body":"Khảo cổ học đã tìm thấy các bãi cọc Yên Giang, Đồng Vạn Muối, Đồng Má Ngựa. Cọc không chặn ngang lạch sâu (đáy sông cổ có chỗ sâu 15 – 16 m, không đóng nổi) mà làm hẹp các dòng chảy, phối hợp với ghềnh đá để cản thuyền lớn và ngăn giặc đổ bộ lên bờ.","facts":[{"label":"Ba bãi cọc","value":"Yên Giang, Đồng Vạn Muối, Đồng Má Ngựa"}],"objective":"o1","source":"manhghep","art":"map"},{"id":"c4","kind":"when","title":"Sáng 9/4/1288","body":"Toàn thư chép: “Nhân lúc nước triều lên, Vương cho quân khiêu chiến rồi giả thua chạy, giặc đuổi theo, quân ta cố sức đánh lại. Nước triều xuống, thuyền giặc vướng cọc hết.” Nguyễn Khoái chỉ huy quân Thánh Dực giao chiến; hai vua đem quân tiếp chiến.","facts":[{"label":"Ngày","value":"9/4/1288"},{"label":"Nhử địch","value":"Quân Thánh Dực của Nguyễn Khoái"}],"objective":"o2","source":"manhghep","art":"boat"},{"id":"c5","kind":"why","title":"Kết quả","body":"Đến chiều, cánh thủy quân Nguyên bị tiêu diệt. Tướng Đỗ Hành bắt được Ô Mã Nhi; Phàn Tiếp cũng bị bắt; hơn 400 chiến thuyền rơi vào tay quân Trần. Cánh quân bộ của Thoát Hoan bị chặn đánh trên đường rút về nước. Cuộc kháng chiến lần thứ ba toàn thắng.","facts":[{"label":"Bị bắt","value":"Ô Mã Nhi, Phàn Tiếp"},{"label":"Thuyền thu được","value":"Hơn 400 chiếc"}],"objective":"o2","source":"w3","art":"star"}],"sources":[{"key":"wbd","title":"Trận Bạch Đằng (1288)","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử)","url":"https://vi.wikipedia.org/wiki/Tr%E1%BA%ADn_B%E1%BA%A1ch_%C4%90%E1%BA%B1ng_(1288)","note":null},{"key":"w3","title":"Chiến tranh Nguyên Mông – Đại Việt lần 3","publisher":"Wikipedia tiếng Việt (dẫn Đại Việt sử ký toàn thư, Nguyên sử, Khâm định Việt sử thông giám cương mục)","url":"https://vi.wikipedia.org/wiki/Chi%E1%BA%BFn_tranh_Nguy%C3%AAn_M%C3%B4ng_%E2%80%93_%C4%90%E1%BA%A1i_Vi%E1%BB%87t_l%E1%BA%A7n_3","note":null},{"key":"coc","title":"Cọc Bạch Đằng","publisher":"Bảo tàng Lịch sử quốc gia","url":"https://baotanglichsu.vn/vi/Articles/1002/28186/coc-bach-djang.html","note":"Hiện vật cọc gỗ lim phát hiện tại sông Chanh (Quảng Ninh) năm 1976."},{"key":"manhghep","title":"Trận thủy chiến Bạch Đằng: Những mảnh ghép","publisher":"Bảo tàng Lịch sử quốc gia (đăng lại từ Tia Sáng)","url":"https://baotanglichsu.vn/VI/Articles/3096/71341/tran-thuy-chien-bach-djang-nhung-manh-ghep.html","note":"Tổng hợp kết quả khảo cổ các bãi cọc Yên Giang, Đồng Vạn Muối, Đồng Má Ngựa."}],"explore":{"scene":"shipyard","title":"Bãi đóng cọc bên sông Bạch Đằng","intro":"Gỗ lim từ rừng đã kéo về bờ sông. Em giúp chuẩn bị trận địa và nhận lệnh của Hưng Đạo vương.","grid":["TTTTTTTTTTTTTT::::~~~~","T....L.L.....:::::~~~~","T............::::~~~~~","T..h.........::S:~~~~~","T===============:::~~~","T............::::~~~~~","T...L..S.....:::::~~~~","T............::S::~~~~","T..F.........:::::++~~","T............::::~b~~~","T..c.c.......:::~~~~~~","T............::~~~~~~~","TTTTTTTTTTTTT:~~~~~~~~"],"spawn":[1,4],"npcs":[{"id":"hungdao","name":"Hưng Đạo vương","role":"Trần Quốc Tuấn, chỉ huy toàn quân","sprite":"commander","at":[9,3],"idle":"Đánh giặc ở đây phải nương theo con nước.","fictional":false},{"id":"khoai","name":"Nguyễn Khoái","role":"Chỉ huy quân Thánh Dực","sprite":"general","at":[15,9],"idle":"Thuyền nhẹ của quân Thánh Dực đã sẵn sàng.","fictional":false},{"id":"elder","name":"Lão chài xem con nước","role":"Dân cửa sông","sprite":"elder","at":[15,1],"idle":"Lão ở cửa sông này cả đời, nhìn nước là biết giờ.","fictional":true},{"id":"carpenter","name":"Thợ đóng cọc","role":"Thợ mộc","sprite":"villager","at":[14,6],"idle":"Cọc lim đẽo nhọn, đóng xuống là chắc như đinh.","fictional":true},{"id":"soldier","name":"Lính kéo gỗ","role":"Dân binh","sprite":"soldier","at":[5,7],"idle":"Gỗ lim nặng lắm, mười người mới kéo nổi một cây.","fictional":true}],"items":[{"id":"stake","name":"Cọc lim đẽo nhọn","sprite":"stake","at":[6,6]}],"zones":[{"id":"river","name":"Cầu ván ra sông","rect":[18,8,2,1],"kind":"enemy"}],"steps":[{"id":"s1","goal":"Ra mũi cát phía đông bắc hỏi lão chài về con nước.","clue":"Lời lão chài: nước lớn thì bãi cạn chìm hết, thuyền to đi được; nước ròng thì bãi lộ ra, thuyền to mắc cạn.","type":"talk","npc":"elder","lines":["Con nước ở cửa sông này lên xuống mỗi ngày.","Nước lớn thì bãi cạn chìm hết, thuyền to đi lại như không. Nước ròng thì bãi lộ ra, thuyền to là mắc cạn."]},{"id":"s2","goal":"Mang một cây cọc lim đã đẽo nhọn ở bãi gỗ ra bờ sông.","type":"pickup","item":"stake"},{"id":"s3","goal":"Đưa cọc cho người thợ đóng cọc ở bãi cát.","type":"give","npc":"carpenter","item":"stake","lines":["Cọc phải đóng lúc nước ròng, trên bãi cạn. Lạch sâu thì không cắm tới đáy.","Đóng xong, nước lên là cọc chìm dưới mặt nước, giặc không nhìn thấy."]},{"id":"s4","goal":"Tới nhận lệnh của Hưng Đạo vương.","clue":"Lệnh của Hưng Đạo vương: nước lớn thì khiêu chiến rồi giả thua, dẫn giặc qua bãi cọc; đợi nước rút mới quay thuyền lại đánh.","type":"talk","npc":"hungdao","lines":["Thủy quân Ô Mã Nhi sắp xuôi sông Bạch Đằng ra biển.","Lệnh của ta: nước lớn thì ra khiêu chiến rồi giả thua, dẫn giặc qua bãi cọc. Đợi nước rút mới quay thuyền lại đánh."]},{"id":"s5","goal":"Truyền lệnh cho tướng Nguyễn Khoái ở bến thuyền phía đông nam.","type":"ask","npc":"khoai","prompt":"Tướng Nguyễn Khoái hỏi lại: khi nào thì quay thuyền lại đánh?","options":[{"id":"a","text":"Ngay khi giặc vừa vào cửa sông."},{"id":"b","text":"Khi nước rút, thuyền giặc vướng cọc."},{"id":"c","text":"Khi trời tối hẳn."}],"correct":"b","right":"Rõ. Quân Thánh Dực sẽ nhử giặc; nước rút là đánh.","wrong":"Không phải. Em nhớ lại lệnh của Hưng Đạo vương xem."},{"id":"s6","goal":"Ra cầu ván phía đông, xuống thuyền. Trận Bạch Đằng bắt đầu.","type":"battle","zone":"river"},{"id":"s7","goal":"Trở lại gặp Hưng Đạo vương.","type":"talk","npc":"hungdao","lines":["Ô Mã Nhi đã bị bắt. Thủy quân giặc tan trên sông này.","Thắng được là nhờ trên dưới một lòng và biết nương theo đất nước mình. Em hãy nhớ lấy."]}]},"battle":{"mode":"bachdang","title":"Trận Bạch Đằng 1288","intro":"Thủy quân Ô Mã Nhi đang xuôi sông ra biển. Em chỉ huy cả ba việc: đóng cọc, nhử địch và phản công. Đây là mô hình giản lược để học; con nước đổi theo từng lượt như thanh thủy triều cho thấy.","grid":["bbsssmsssrbb","sssssssssrbb","dddddddddddd","ssssssssdddd","bbssssssmsbb"],"zone":[5,8],"stakes":{"total":6,"per_turn":3},"tide":{"prepare":[2,1,0,0,1],"lure":[2,2,2,2,2],"counter":[1,0,0,1]},"bait":{"id":"thanhduc","name":"Thuyền nhẹ quân Thánh Dực","at":[4,1],"hp":8,"atk":2,"speed":3,"range":5,"sprite":"thuyen_nhe"},"fleets":[{"id":"hungdao","name":"Thủy quân mai phục của Hưng Đạo vương","mouth":[5,0],"hp":14,"atk":4,"speed":2,"fire":1,"key":true,"sprite":"thuyen"},{"id":"haivua","name":"Thủy quân của hai vua","mouth":[8,4],"hp":14,"atk":4,"speed":2,"fire":1,"key":false,"sprite":"thuyen"}],"enemies":[{"id":"omanhi","name":"Thuyền chỉ huy của Ô Mã Nhi","at":[2,2],"hp":16,"atk":4,"flagship":true,"sprite":"e_thuyen"},{"id":"phantiep","name":"Đoàn thuyền của Phàn Tiếp","at":[1,2],"hp":14,"atk":3,"flagship":false,"sprite":"e_thuyen"},{"id":"hauquan","name":"Đoàn thuyền hậu quân","at":[0,2],"hp":12,"atk":3,"flagship":false,"sprite":"e_thuyen"}],"strand_damage":4,"archers":1,"rules":["Con nước đổi sau mỗi lượt theo thanh thủy triều; em xem trước được các lượt sắp tới.","Chỉ đóng được cọc khi nước Thấp và chỉ trên bãi cạn. Lạch sâu, ghềnh đá không đóng được. Mỗi con nước thấp đóng tối đa 3 cụm, tổng cộng 6 cụm.","Cọc đóng ở cửa sông nhánh sẽ chắn đường ra của chính thủy quân mai phục.","Nước Cao: cọc chìm, mọi thuyền đi qua được. Thuyền địch đã bị khiêu chiến bám theo đúng vệt nước của thuyền nhẹ, mỗi lượt 2 ô; chưa bị khiêu chiến thì theo lạch sâu ra biển.","Để thuyền địch áp sát (kể cả ô chéo) thì thuyền nhẹ bị đánh.","Nước rút: thuyền địch đang ở ô có cọc bị vướng cọc (đứng yên, hư hại, chịu thêm nửa sát thương); ở bãi cạn thì mắc cạn, mỗi lượt chỉ lê được 1 ô; ở lạch sâu thì chạy ra biển.","Bè lửa chỉ trúng thuyền đã vướng cọc hoặc mắc cạn. Cung thủ hai bờ bắn thuyền vướng cọc mỗi lượt.","Thua khi thuyền chỉ huy địch hoặc hai đoàn thuyền thoát ra biển, khi mất thuyền nhẹ lúc đang nhử, mất cánh quân của Hưng Đạo vương, hoặc nước lên lại mà chưa diệt xong."],"briefing":{"prepare":"Đọc con nước rồi đóng cọc. Khi nước cao, mặt sông trông như nhau; hãy chờ nước rút để thấy bãi cạn. Đóng cọc trên bãi cạn mà em định dẫn giặc đi qua, và đừng chắn hai cửa sông nhánh.","lure":"Nước đã lên, cọc chìm dưới mặt nước. Bấm Khiêu chiến khi thuyền địch vào tầm, rồi lui thuyền nhẹ qua bãi cọc. Thuyền địch sẽ bám theo đúng đường em đi. Tính sao cho lúc nước rút chúng đang nằm trên bãi cọc, và đừng để chúng áp sát.","counter":"Nước rút! Ra lệnh cho từng cánh quân: áp sát thuyền vướng cọc để đánh, thả bè lửa vào thuyền đã mất cơ động, chặn lạch sâu nếu còn thuyền địch chạy. Phải dứt điểm trước khi nước lên lại."},"win_text":"Thuyền giặc vướng cọc giữa lúc nước rút, bị đánh từ nhiều phía. Thủy quân Ô Mã Nhi tan vỡ trên sông Bạch Đằng.","lose_text":"Trận địa chưa phát huy tác dụng. Xem lại lời giải thích bên dưới rồi thử lại: bãi cọc, đường nhử và con nước phải khớp với nhau."},"debrief":{"title":"Bạch Đằng 1288 trong sử sách và khảo cổ","paragraphs":["Cuối tháng 3/1288, quân Nguyên rút về nước theo hai đường. Cánh thủy quân của Ô Mã Nhi và Phàn Tiếp xuôi về phía biển; ngày 8/4/1288 tới Trúc Động, bị ngăn không vào được sông Giá nên tiến vào sông Bạch Đằng.","Trần Hưng Đạo đã chuẩn bị trận địa cọc ở cửa sông. Bảo tàng Lịch sử quốc gia cho biết cọc được đóng khi nước triều rút, cách nhau khoảng 0,9 – 1,2 m. Các cuộc khai quật ở Yên Giang, Đồng Vạn Muối, Đồng Má Ngựa cho thấy cọc không chặn ngang lạch sâu mà làm hẹp các dòng chảy, phối hợp với ghềnh đá.","Sáng 9/4/1288, nhân lúc nước triều lên, quân Trần khiêu chiến rồi giả thua, giặc đuổi theo. Nước triều xuống, thuyền giặc vướng cọc. Nguyễn Khoái chỉ huy quân Thánh Dực giao chiến, hai vua đem quân tiếp chiến; quân mai phục hai bờ và hỏa công cùng đổ ra.","Đến chiều, cánh thủy quân Nguyên bị tiêu diệt. Tướng Đỗ Hành bắt được Ô Mã Nhi; Phàn Tiếp bị bắt; hơn 400 chiến thuyền bị quân Trần thu giữ. Cánh quân bộ của Thoát Hoan cũng bị chặn đánh trên đường rút. Cuộc kháng chiến lần thứ ba kết thúc thắng lợi.","Màn chơi là mô hình giản lược: khúc sông chia ô, con nước đổi theo lượt, số cọc và số thuyền đều là quy ước. Diễn biến thật phức tạp hơn nhiều, trên một chiến trường dài hàng cây số mà khảo cổ học vẫn đang tiếp tục nghiên cứu."],"sources":["wbd","w3","coc","manhghep"],"fiction":"Nhân vật “tiểu tướng” do em điều khiển, những người lính, dân làng không có tên trong sử và mọi lời thoại là phần sáng tạo của trò chơi. Các chỉ số máu, sát thương, số lượt là quy ước để chơi, không phải số liệu lịch sử; thắng hay thua trong trò chơi không làm thay đổi kết quả lịch sử."}}$hq$::jsonb,
     'published', $hq$Nội dung khởi tạo ngày 15/11/2026: dữ kiện đã đối chiếu với các bài Wikipedia tiếng Việt về ba cuộc kháng chiến chống Mông – Nguyên và hai bài của Bảo tàng Lịch sử quốc gia về Bạch Đằng. Cần giáo viên Lịch sử rà soát lại; quản trị tổng có thể đưa chặng về Nháp bất cứ lúc nào.$hq$)
ON CONFLICT (code) DO NOTHING;
