SELECT s.id, v.code, v.position, v.kind, v.usage, v.objective, v.prompt, v.data, v.explanation, v.source FROM public.hk_saga_stages s, (VALUES
    ($hq$s13-q1$hq$, 1, $hq$quiz$hq$, $hq$both$hq$, $hq$o1$hq$, $hq$Quân Trần đã lợi dụng hiện tượng tự nhiên nào để thắng trận Bạch Đằng năm 1288?$hq$, $hq${"options":[{"id":"a","text":"Gió mùa đông bắc"},{"id":"b","text":"Thủy triều lên – xuống"},{"id":"c","text":"Sương mù dày đặc"},{"id":"d","text":"Mưa lũ đầu nguồn"}],"correct":"b"}$hq$::jsonb, $hq$Nước triều lên che bãi cọc để nhử giặc vào; nước triều rút làm thuyền giặc vướng cọc.$hq$, $hq$wbd$hq$),
    ($hq$s13-s1$hq$, 2, $hq$sequence$hq$, $hq$both$hq$, $hq$o2$hq$, $hq$Xếp các bước của trận Bạch Đằng theo đúng thứ tự.$hq$, $hq${"items":[{"id":"m1","text":"Đóng cọc ở cửa sông lúc nước ròng"},{"id":"m2","text":"Nước lên, thuyền nhẹ khiêu chiến rồi giả thua"},{"id":"m3","text":"Thuyền giặc đuổi theo vào trận địa"},{"id":"m4","text":"Nước rút, thuyền giặc vướng cọc"},{"id":"m5","text":"Quân mai phục đổ ra đánh, bắt Ô Mã Nhi"}]}$hq$::jsonb, $hq$Chuẩn bị trận địa, nhử địch lúc nước lên, phản công khi nước rút.$hq$, $hq$manhghep$hq$),
